/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20130612-17","meetingId":"h25-cm06","date":"2013年6月12日","dateIso":"2013-06-12","committee":"震災対策特別委員会","time":"午後１時００分～午後２時３９分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれご説明いただきましたが、一つひとつがとても大事なテーマで、今日は大雑把に伺おうとは思いますけれども、この１年間、しっかり議論をしていきたいと思います。防災広場についてですけれども、これらすべて「市街地大火を防ぐ」と目的がありますけれども、では、どれぐらいの広さのまちに、どれぐらいの防災広場が、どれぐらい必要なのか、そういう目標を伺いたいと思います。建替えもそうです。","respondent":"品川木密整備担当課長","answer":"それからもう一つご説明しました７０％については、この７０％に到達すれば延焼率が０％になると理論的に出されている数字があります。基本的には、この木密事業の最終的な目標値としましては、不燃領域率７０％というところで進めていくようなことになるかと考えております。","voiceIndex":31,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"一般的には、公園が増えたり道幅が広がれば、防災に役立つのかと。その点も伺いたいと思います。これでよいのかという点を伺いたいと思います。確かにいろいろな根拠が必要になるから、それが根拠を落とし込んだ計画とおっしゃいますけれども、でも、実際に起きる被害をまずは明らかにしていくことがその対策につながっていくのではないかと思うのですけれども、改めてそこの点を伺いたいと思います。","respondent":"品川木密整備担当課長","answer":"そういったことを踏まえて対策を練ると考えれば、現状の不燃化事業、それから、先ほど済みません、耐震化事業の説明が漏れてしまいました。耐震化事業は耐震化率、今回、耐震改修促進計画も変更しまして、平成３２年までに９５％に耐震化率を上げていくという目標があります。","voiceIndex":33,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"耐震化についてですけれども、ここは一言ですけれども、先ほど目標があるというお話がありましたけれども、今日は議論の初めなので、要するに実績が載っておりますけれども、目標に対して現状はどこまで進んだのか、それをまず明らかにしていただきたいのと、あと支援策の内容について１点だけ求めたいのですけれども、これまで木造住宅の一般診断無料化など。","respondent":"品川木密整備担当課長","answer":"ですので、対応は何もしていないということではないと考えております。それから電車の脱線につきましても、これはＪＲが当然やっていることです。","voiceIndex":35,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"この地域防災計画の展開についても伺いたいのですけれども、発災型防災訓練、昨年、一斉に行われて、ばたばたもありましたけれども、私は意義のある取り組みだったと思いますし、今後も課題や教訓を明らかにしてぜひ発展させていただきたいと思うのですけれども、ずばり住民自身が主体的に取り組む意義を品川区自身はどのように考えているのか、ここを伺いたいと思います。","respondent":"鈴木防災課長、品川木密整備担当課長","answer":"３点のご質問をいただきまして、まず１点目、住民が主体的な参加をした訓練、もしくは実際のときの取り組みについて、どのように区が考えているかというご質問ですが、区としましては、東日本大震災以降。耐震の自助の件ですけれども、新しくつくっております耐震改修促進計画、それから、今までつくっていました耐震改修促進計画の中にも書いてあるとおり、基本的に耐震化については自助という形で。","voiceIndex":37,"id":"exchange-004"},{"speaker":"中塚委員","kind":"提案","question":"それと、学校避難所運営についても伺いたいのですけれども、一つ提案したいのが、学校避難所運営訓練をぜひしっかりやっていただきたいと思いますので、現状どれぐらい行われているかということと、ぜひやっていただきたいということですけれども、これも幅広い地域住民が参加できる実践型の訓練にしていただけたらと思うし、その際、地域は広いですから、学校単位でまずは説明会を開催して。","respondent":"鈴木防災課長","answer":"当然、区は、専門的なアドバイス、それから消防も連携した支援体制を組んで取り組むものですので、私の説明がまずかったのか、真意が伝わっていないようなので、もう一度言っておきます。","voiceIndex":40,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校避難所運営について説明会をやったらどうかと思ったのですけれども、それについて伺いたいのと、福祉避難所について、要するに現状で福祉避難所としての運営訓練を実施されているのか、されていないのであれば、やっていく必要性があるが、どのように考えているのか、そこをご説明いただきたいと思います。","respondent":"鈴木防災課長","answer":"ただ、一律に説明会をすればいいというものではございませんので、これは柔軟に対応しています。","voiceIndex":42,"id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"もう一つが、地域防災計画の中で、それぞれ分科会をつくってマニュアルを作成していくということですけれども、医療体制のところは、医療機関、連携機関、ここには記載がありますけれども、ほかの要援護者、それから学校避難所運営、この２つでの分科会に来られる連携主管課、あるいは、どういった方が来るのかは、ここは概要説明の中では大体のイメージはわかるのですが。","respondent":"品川木密整備担当課長、鈴木防災課長","answer":"２‐２の耐震の実績を見ていただきたいのですけれども、昨今、こちらは、木造住宅の除却の制度を入れ始めてから、非常に空き家の申請が多くなってきています。今年度の検討につきましては、今度は分科会でみんなが集まるのではなくて、各複数の課の対策本部の部隊単位ですが、そちらが主体になりまして、防災課と防災課の派遣するコンサルタントがサポートしまして。","voiceIndex":44,"id":"exchange-007"},{"speaker":"こんの委員","kind":"提案","question":"今、確認はさせていただいた部分も踏まえながら、今後の一つひとつ詰めていく部分で、また提案なり、提言なりさせていただきたいと思います。現状、今日は概要説明ですので、本当に中身のご説明をいただきましたので、また掘り下げていく部分では、皆様の地域の声もあわせて上げていきたいと考えています。どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-008"},{"speaker":"塚本委員","kind":"意見","question":"そういった観点から、いろいろな地域においていろいろな事業をこれまでやられて、実績もここに報告いただいていますけれども、今後の展開として、より力を入れていくべきプライオリティーの部分、また、もし新たな事業等もあるのであれば、そういったところも含めてお話いただければと思います。","respondent":"品川木密整備担当課長","answer":"その中で木密１０年プロジェクト、ここの密集事業のところにも書いてありますとおり、東中延１丁目・２丁目、中延２丁目・３丁目地区が、昨年度、木密１０年プロジェクト先行実施地区に入ってあります。","voiceIndex":48,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、いろいろご説明いただきました。それぞれ、実施に当たって実現すれば、大きな効果を見込まれての事業だと理解いたしておりますので、特にまたその事業の効果が、先ほど不燃化領域率というお話もありましたけれども、そういった客観的な指標できちっとはかれるような形で進めていただいて、より限られた体力の中で最大の効果をという視点で進めていただければと思いますので、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"確かにまちとしてのリスクはそれぞれ特徴があるかもしれないけれども、人が住んでいるのは建物であり、働いている場所であれば、また建物ですから、そういう意味では、重点化が地域の支援を外すという考えに働いてしまったら、震災から区民の命や暮らしを守ることはできないと思うのですけれども、その点をどのようにお考えなのか伺いたいと思います。ただし、建替え支援は、まだ地域を限定しているわけです。","respondent":"品川木密整備担当課長","answer":"木密地域には、先ほども説明しましたように区内３分の１程度、木造住宅密集地域があるという状況ですが、特に重点整備地域については、密集事業や木密不燃化１０年プロジェクト等を利用してやっていく。","voiceIndex":51,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"伺いますけれども、重点的に手厚くすることはあると思うのです。建替えでなくても、除却であっても、そういう効果があるというのであれば、地域を分けることが、ひいては区民の支援を分けてしまうと、本来であれば取り除ける危険が取り除くための支援が受けられないのは、私は自治体の姿としては問題だと思うのですけれども、そこについて伺ったのですけれども、よろしくお願いします。","respondent":"品川木密整備担当課長","answer":"建替・除却につきましては、これは先ほどもご説明しましたとおり、不燃化の効果があるということであれば、対象地域はどこにすればいいかということを考えれば、区内の約３分の１を占める木造住宅密集地域を対象にしていくという考え方で、現在、進めている。","voiceIndex":53,"id":"exchange-012"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん発災直後の雑居ビルだったり、超高層ビルの長周期地震動だったり、鉄道の脱線だったり、そういうのもしっかりと考え得る被害、品川区も数値化されていないけれども車両火災は起こり得ると言っているわけですから、そういうところもしっかり被害として、まずテーブルの上に載せて議論ができる、そういう資料もそれぞれ準備していただけると、学校避難所といい、災害弱者といい、災害時の医療といい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"確認です。資料のことではないのですけれども、この日程案に既に視察が入っているのですけれども、これはご説明がなかったのですけれども、これはどのような考えで入っているのか、ご説明をお願いしたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-014"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、今の中では案だということ、日程も案という形ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-015"},{"speaker":"こんの委員","kind":"質問","question":"中身も日程も案ということなので、この視察が、時期が変わったり、あるいは中身、あるいはこの議論の場合によっては増える場合もあるしと、全く、では不確定な案ということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-016"},{"speaker":"こんの委員","kind":"提案","question":"特に今、私はここという案を持ち合わせているわけではないのですが、一応、このようにもう既に先方の決まったかのような場所が書かれていたので、もう既にそのような調整が行われているものと思ってしまったのですが、そうではないということですので、おいおい、このほかに場所があればという提案が出されても大丈夫だということですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"今のお話だと、視察の場所についても、今後の委員会の議論の中でとおっしゃいましたけれども、そういう流れの中で視察先も出していく、そんな感じなのか、それとも、今、ほかの委員からも調査事項についての意見がありましたが、今、いつそれを、その視察先の意見を出すのはいつになるのでしょうか。今ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-018"},{"speaker":"つる委員","kind":"提案","question":"今でしょということなら、視察で災害時要援護者とか、今後、学校避難所運営とかの議論の中でも、多分、詳細にやりとりをしていただきたい部分であるのですけれども、文京区の妊産婦・乳幼児避難所なのです。そこを視察先の中の一つの検討として挙げていただければと思いますので、提案させてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-019"},{"speaker":"木村委員","kind":"提案","question":"それで、このことに対して、もしそういう大きな地震が来た場合のときのことを考えると、早急に何かいろいろやらなければいけないとは思うのですが、管理組合との話し合いとか、近い将来的に区としては何か提案をするようなこととか、それからあと、耐震化の助成費用が大体２,５００万円、３分の１ということですけれども、それが適用されるのかどうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6432#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":30635,"voices":74}},{"id":"h25-20130701-6","meetingId":"h25-cm07","date":"2013年7月1日","dateIso":"2013-07-01","committee":"区民委員会","time":"午前１０時００分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４５号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第４５号議案 平成２５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"低い支持率を高くするために、税金を使って気運醸成をするというのは、やはり問題であると思います。今回のこの１０分の１０ですけれども、品川区だけでなくいろいろな自治体も手を挙げているのかと思いますけれども、東京の全ての自治体で手を挙げてやっているのでしょうか。その辺からもこの事業の規模といいますか、税金の総額というのも少し見えてくるのかと思いますので、そこを伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"その１,０００万円を有効に活用して、地域のプランターの水やりの話だとか、そういうものに活用していったところです。それから、また事業の規模ですが、これも東京都のほうでは２３区を初め、市町村のほうでも事業を展開しているものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"ということは品川区だけだと、今回の補正予算と今までで、２,２００万円ぐらいの税金が使われていると。税金の使い方として本当にこれでよいのかと、その点は指摘したいと思います。今回の事業は１団体に５０万円の助成ということですけれども、従来取り組んできたイベントであっても助成をするのか、例えばオリンピック招致のために新たに企画されたものだけなのか、その内容について伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、東京都のほうで、国体の助成金の要綱を改正して、オリンピックとともにあわせてやるものについて出しますよというものです。そして、今、言ったこのオリンピックと国体の両方をＰＲする事業について、５０万円出しますよというものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"取りかえるのは大変なのですよね。私のところに寄せられるのは、健全に活動している団体からも体罰というこの根深い恥ずかしい状況を克服して、健全なスポーツ発展のために取り組みたいといったご意見も伺っているのですけれども、前回答弁がなかったので改めて伺いますけれども、スポーツにおける体罰がなぜいけないのか、その克服の取り組みをどう考えているのか、この点をあわせて伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"まさに今、２０１３年の子どもたちが例えば小学校６年生、中学校１年生の子どもならば、２０２０年というと二十歳前後になります。そして、今、その中学生であり小学生の子どもたちが、本当に２０２０年にはオリンピックの檜舞台に立つ可能性があると考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"オリンピックについてですけれども、冒頭で一言述べたつもりではおりましたけれども、オリンピックそのものは人間のあくなき探求、より高いレベルに達しようとする挑戦、うまくいったときの達成感、またもちろん相手のあるスポーツですからうまくいかないこともあるでしょう。聞きたかったのは、体罰について、スポーツにおける体罰がなぜいけないのか。ここは区民委員会ですから、文教委員会では……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"スポーツ界における体罰はなぜいけないのかという、ここの見解は前回の区民委員会でも出ていないのですよ。私が予算特別委員会のときに聞いたのは、だめだと思うという点は一言ありましたけれども、それだけに、特に今回このスポーツ予算でオリンピックが出ているだけに、改めてスポーツにおける体罰がなぜいけないのかと、ぜひ区の見解を聞かせていただきたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"私は個人的に学生時代には部活もやっていましたけれども、そういうある１つの閉塞された中での競技を目指すところでは、必ずしもそういうことが常に起きているかもわかりませんけれども、現状は、今、お話をしたようなことです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言、今のお話で、地域に開かれた仲間づくりのスポーツと、アスリートと呼ばれるスポーツが違うというのは、またちょっと違うだろうと思っていて、やはり裾野の広い地域での目指したスポーツがあるからこそ、世界とも戦える優秀なアスリートが生まれてくると思いますので、それはちょっと言葉のあやかもしれませんけれども、ぜひその地域に根ざした身近でスポーツができる環境。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"そういう意味で、投資対効果というのは行政の中でも必ず考えますよね。税金ですから、お金を投入してどういうふうに効果が出てくるかということも考えると思いますけれども、その辺というのは、もう率直というかストレートな質問ですけれども、担当課長としては今の思いはどう思っているのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で東京都のほうから話が来たのが、今回の、今、ご説明をしているこの助成金を２月１４日に東京都のほうから案が示されて、その段階では細かいこともまだ決定されませんでした。そんな中で、３月１１日に締め切りだったわけです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そんな中で、東京都が本当に時期を非常に狭めた期間で募集をするというのは、せっかくそういったやろうかというやる気になっている団体に対して、非常に失礼な話だと思いますので、その辺はぜひ東京都のほうに、せっかくやってもらえるのであればもっと期間もしっかりとっていただいて、幅広い団体に支援できるような形にしてほしいということを強く伝えていただければと、これは要望で終わります。","respondent":"安藤文化スポーツ振興課長","answer":"それと、今の２２の団体ですが、既に終わっている団体もありますが、まだ若干残っている団体もあります。商店街のほうにつきましては、ほとんどもう４月、５月のイベントとして消化をしています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問","question":"そうすると、２２の枠は枠として確保してありますけれども、それで一応２２の団体が申請はしているけれども、１７件は決定していて、５件がどうなるかわからないという、今の説明でよろしいですか。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、一応この事業が９月７日までに実施してくださいね、９月７日まではいいですというような段階なので、これから５団体が上がってくる可能性がまだあるだろうという枠をとって、５団体をとってあります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問","question":"そうすると、５団体はまだ枠があいているよということで、区内の団体にもまだあと５枠はチャンスがあるという理解でよろしいのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"要は、あと区がやるものだとか、自治体がやるものだとか、それが東京都との交渉になってあります。そんな中で、全て５団体が出てきた段階で、いいよというのは東京都のほうに確認をしなければ、これはちょっと難しいと考えております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問","question":"もちろん申請するに当たってはいろいろ様々な条件があると思うのですが、申し込みを先着順であと５件受け入れますよという認識でよろしいのかどうか。それとも、もう既にある一定のところに声をかけていて、対外的にはこの５件もあとは書類を出してもらうだけの段階で、今、進んでいるのか、その辺だけもう一度教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、これから東京都との話し合いの中で、より多くやれればと考えています。ですから、締め切りの時期もありますので、新たにここで新しい団体の募集は今のところは考えてございません。","voiceIndex":27,"id":"exchange-011"},{"speaker":"山元委員","kind":"質問","question":"今、ずっとお話を聞いていると、品川区で１７団体もそうですが、あくまでもこういう団体が出ていますという決定権は東京都にあって、品川区ではないということなのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"東京都のほうで、この費用については出せませんとか、この項目については受理しますとか、そういうチェックが入りまして、そのままうちのほうでまた団体のほうにバックすると。だから品川区には決定権というものが、この事業についてはございません。","voiceIndex":33,"id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"その１７件によっては、この５０万円を完璧に使うものもあれば、それ以下のところもあるかと思いますが、それはあくまでも５０万円以内で何かイベントをやるよということで、例えば今度余ったお金というか、それとも５０万円を下さって、余ったら返すのですか。ちょっと変な言い方ですけれども。","respondent":"安藤文化スポーツ振興課長","answer":"ある団体は、総経費８０万円を計上していまして、そのうちの５０万円を申請すると。しかし、それは実際にはありませんけれども、場合によってはこの項目、例えば高価な備品だとか、そういうものは対象外ですよという形で、東京都のほうからはお話があります。","voiceIndex":35,"id":"exchange-013"},{"speaker":"山元委員","kind":"質問","question":"一応２２件というお話ですが、そのうち１７件の傾向性というか、やはり商店街が多いのか、それとも企業で何かイベントをしているのか、大雑把でいいですけれどもその辺の傾向と、それからもう一つ、２つの申請が東京都のほうから中止というか断られたというのですか、そういうふうにおっしゃっていましたが、それは何で申請したのがバックされてしまったのか、そこら辺もちょっと教えていただけますか。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、５０万円要求している中で、だめなものを削られたらまた出し直して、なるべく５０万円になっていくような形で、申請団体とは協議しています。","voiceIndex":37,"id":"exchange-014"},{"speaker":"山元委員","kind":"質問","question":"最後です。２２団体のうち１７団体ということは、あと５件ということで、実際に９月にある程度オリンピックが決定するということもあって、２カ月ぐらいしかない。そういう招致とか気運を高めるということもあるでしょうが、実際、この５団体というのは何か予定はあるのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"１つは、まず、今、うちのほうで進める３つの事業、招致のロゴを配したうちわをつくって区民まつりに配るだとか、それも、今、申請最中です。それから軟式野球連盟の希望に対しましても実施しております。","voiceIndex":39,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"今のお話の中で一つ質問があるのですけれども、申請して落とされるということがありましたね。例えばその飲み食いに関してもそうですが、テントがだめとか、そういうことに対して、もともと申請する前に、こういうものに関しての、品川区としての指導はないのですか。","respondent":"安藤文化スポーツ振興課長","answer":"それで、社会通念上として、うちのほうでボランティアとして１人２,２００円とか出していますので、それでは大丈夫ですかということを向こうに確認とるとか、そういうやり取りというのがあります。だから非常にシビアなところがあることはある。","voiceIndex":41,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"基本的にこの流れがわかりました。スポーツ祭東京２０１３と合わせて気運を醸成するという中で、今までの事業を大体聞いていると、オリンピックのための形だと。全然目につかなかったのです。確かに９月７日という前提があるから、今はこっちだよというのがあるかもしれないけれども、その１０月に始まるものが何か消えてしまっているという感じがするのですけれども、その辺はいかがですか。","respondent":"安藤文化スポーツ振興課長","answer":"ですから東京都自体、国体は実際にやりますけれども、そこに便乗して一気にスポーツとしての気運を高めていくということで、よく言うのは相乗効果を狙ってやっていきますという考え方なのですね。","voiceIndex":43,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ハンドボールとグラウンドゴルフ、随分アピールしてもらっているのはわかりますけれども、今回のこの事業に関して、そこら辺は全く入っていないというのを今まで感じているのですけれども、そこら辺も少し加えてほしかったというところが自分の意識にはありますけれども、その辺ちょっと。","respondent":"安藤文化スポーツ振興課長","answer":"この事業でやる場合にも、うちのほうで「ゆりーと君」、国体のあれはゆりーと君です。ゆりーと君が出前で出張しまして、そこで国体をアピールして、必ず宣伝をしていただいたりだとか、国体も忘れないようにしていただくためには、そういう情報も全部出しております。","voiceIndex":45,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ここがオリンピックの誘致、今、徹底してほしいし、それと同時に１０月からの国体。ホッケーも大井の競技場、それからビーチバレー、この辺の言葉が、オリンピック誘致と言うけれども、品川区でこれがあるというのが何かあまり見えなくなってきているような気がするので、その辺もちょっと意識してほしい気がいたします。","respondent":"安藤文化スポーツ振興課長","answer":"今、ご指摘どおり、品川区内にも、品川区のものではございませんけれども、大井中央海浜公園でホッケー、それとホッケーの後にはパラリンピックで視覚障害者５人制サッカー、それと脳性麻痺者７人制サッカーも行います。","voiceIndex":47,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自民党は賛成です。当然９月に招致ができるように、これからも頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-020"},{"speaker":"山元委員","kind":"質問・要望","question":"公明党も賛成です。本当に子どもたちの夢があるスポーツですので、ぜひ実行していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"便乗してオリンピックに充てるのではなくて、もともとスポーツ祭東京２０１３の健全な発展にこそ力を注ぐべきだと思いますし、あと、先ほどこの議論を聞いておりますと、内容を見たら余りにもとってつけたような事業で、都がくれるから品川区は使うという税金の使い方に、今回で１,１００万、今までと合せると２,１００万、こんな税金の使い方は前代未聞だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"}]},{"id":"topic-02","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今回の事故が起きたわけですけれども、その原因についてはどのように分析されているのかという点を伺いたいと思います。今回の直接の原因やそういう体制に問題はなかったのか、今回の件を受けて、例えば地域センターとか区民の方がいろいろ使うものの総点検などの取り組みはどのようになっているのか、状況を伺いたいと思います。","respondent":"久保田地域活動課長","answer":"幾つか不具合のあったテーブル・椅子がございましたので、そちらのほうの利用は差し控えるようにしまして、適時交換をしていくというところでございまして、八潮地域センターにつきましても数がありますので、そちらについてはもう既に２４年度の予算の中で必要なものは交換して。","voiceIndex":61,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"普通のビニール製の椅子だったら、しょうゆをこぼしてもふけばきれいになりますけれども、しみ込むタイプなので、本当に何かすごいしみが跡になってしまって、次に買い替えるときも、それぞれ地域センターで要望があって対応していると思いますけれども、こういうものがいいとか、こういうものがちょっとあれだったとか、いろいろ公表しながら、情報交換しながら買い替えていただけたらと思います。","respondent":"久保田地域活動課長","answer":"例えば、椅子の背もたれがちょっと外れかかっているというようなものがございましたので、そういったものにつきましては使用しないように、倉庫のほうにしまって対応させていただいているということです。","voiceIndex":63,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて点検したら、机が８０個、椅子が１６個不具合があったと。これだけ見れば、やはり日常的な点検に問題があったと言わざるを得ません。ぜひ日常的な点検や注意を払うというところを強めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"確認","question":"どういう、言葉の上で整理してもらえると。そこら辺、逆に言うと万が一わからないで出してしまうことって、職員の方が多分つくのだろうけれども、集会室を使用していた人たちは、使えなくても置いておくと、かえって危ないのではないかという気がするので、その辺、整理の仕方というのが気になったので、ちょっと確認だけ。","respondent":"久保田地域活動課長","answer":"すみません。説明が不足していました。倉庫にしまったというのは、粗大ごみ等で出すのは時期がありますので、それまでの間倉庫にしまうですので、当然使用できないものについては「使用できません」という張り紙を張って、使わないように利用者の方には注意喚起しています。","voiceIndex":66,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"粗大ごみとしても十分出てしまっている時期だろうと思うので、置いておく必要はないし、粗大ごみにするのだったらもう出てしまっているのではないのという感じがするのだけれども。もう既に倉庫になくなっているのではないのかというイメージがあるけれども、理由があるの。","respondent":"久保田地域活動課長","answer":"説明が足りませんでした。その事故があった後に倉庫にしまったりして、使わないようにしたということの説明です。","voiceIndex":68,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"今までに、こういう事故があったのかということを１点お聞きしたいのですけれども。","respondent":"久保田地域活動課長","answer":"このような形で専決処分の報告ということで、私どものほうも以前からちょっとさかのぼって、全てさかのぼるには数がかなりありますので、さかのぼったところでは平成１４年から確認しましたけれども、地域センターで同様の事故は今まで起きてございません。","voiceIndex":72,"id":"exchange-028"},{"speaker":"吉田委員","kind":"意見","question":"初めてこういうことがあったということはわかったのですけれども、これから全部点検なさるということですけれども、先に老朽化することもあると思うので、今まで大丈夫なものがどんどん悪くなることもあるので、これから定期的にそういう点検するようなことをお考えなのかどうか。","respondent":"久保田地域活動課長","answer":"利用者の方から申し出があれば、そういったものも確認をして対応するように、ただ、こういった事故が起きていますので、私どもも定期的にやるというような形で検討していかなければならないと思ってありますので。","voiceIndex":74,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど利用者の方にお伺いしてということもあるのですけれども、要望なのですが、これから先、定期的に必ずやっていただいて、事故を未然に防ぐということは非常に大切なことなので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"そこで質問したいのですが、今回この専決処分が地域活動課の担当といいますか、地域センターで起きたから地域活動課がやっていると思うのですけれども、答えられる範囲でいいのですが、区の備品、椅子とかテーブルとかは地域センターだけではないではないですか。","respondent":"久保田地域活動課長","answer":"昨年、平成２４年の１１月にこの事故が起きた後に、まず私ども地域活動課だけではなくて、地域振興事業部長の指示で、特に貸し出し施設についてはそういった危険がないかということで、今、ご指摘があったように文化センター、中小企業センター等につきましては。","voiceIndex":77,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2668#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":18881,"voices":85}},{"id":"h25-20130701-7","meetingId":"h25-cm07","date":"2013年7月1日","dateIso":"2013-07-01","committee":"厚生委員会","time":"午前１０時００分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４５号議案、平成２５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第４５号議案、平成２５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"定期予防接種、子宮頸がんの、これは内訳なんですけれども、件数をどのぐらいに見込んで金額が幾らになっているのかということと、あと子宮頸がん、任意予防接種のときには、１００％の助成で今年度は予算が立てられているというふうに思っているので、ここの部分で当初予算のところで何件分を想定されていた予算なのかということ、それから定期接種化に当たって、これはちょっと、じゃ。","respondent":"伊津野品川区保健所保健予防課長","answer":"子宮頸がんワクチンにつきましては、件数としまして７,２００件、金額としまして１億１,９４４万８,０００円を予定しております。任意予防接種として予定しておりました件数ですが、全額補助を予定しておりましたので、件数としては７,２００件、同じであります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"それで、定期接種、この部分で、対象者にお知らせをしていると思うんですが、随分自治体によってはこの定期接種のお知らせの時期がずれているというような情報もあるんですが、品川区の場合には対象者にいつ、どういった方法でお知らせをされていたのかお伺いしたいと思います。","respondent":"伊津野品川区保健所保健予防課長","answer":"今年度、定期接種化になりまして、ぎりぎり４月１日からの実施を目指しまして、３月末に中学１年生から高校１年生、さらに二十歳の任意接種のものなんですが、通知を個別に発送しております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"今回の子宮頸がんワクチンの予防接種、副反応がほかの予防接種に比べて多いというふうに言われているんですけれども、インフルエンザに比べてどのぐらい違いがあるというふうに区が認識をしているのかお伺いをしたいということが１点。それから、６月１４日に積極的な接種勧奨を控えるということが出されていましたけれども、これを区は区民や対象者にどのような周知方法をとってきているのかお伺いします。","respondent":"伊津野品川区保健所保健予防課長","answer":"区民への今回の積極的勧奨の中止の周知につきましては、まずホームページでこういう事態が起きているということを通知しておりますし、区報では７月１１日号で掲載したいというふうに考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"副反応が１６.６倍ぐらいということなんだけれども、重篤な反応という部分については大変高率な値が出ているんだというふうに認識をしておりまして、あとその部分について、そういったところを調査や情報収集が必要であるということで、厚生労働省が勧奨を控えるということになったというふうに認識をしているんですが、その辺の副反応の重篤なケースというのを。","respondent":"伊津野品川区保健所保健予防課長","answer":"今回の積極的勧奨の中止につきましても、因果関係が否定できない持続的な疼痛が特異的に見られていることから、一時的に情報提供ができるまでの間、勧奨を中止しようということでありますので、国の勧告に従って区のほうも対応したいというふうに考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"これからもう少し周知を進めてほしいという前提でお伺いをするんですけれども、インフルエンザワクチンに比べて、サーバリックスは副反応が３８倍で、重篤な副反応は５２倍、ガーダシルは副反応が、インフルエンザに比べてですけど、副反応が２６倍で重篤な副反応は２４倍というような、そういった報告について区はどのような認識を持たれているのでしょうか。","respondent":"伊津野品川区保健所保健予防課長","answer":"この何倍という数字につきましては、いろんな方法によって若干違いがあります。検討会の資料によりますと、サーバリックスで１８.８倍、ガーダシルで１４.４倍あったという報告があります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"今回補正予算ということなので、これは定期接種となって、自治事務になったということだというふうに、国の法定受託事務から自治事務になったということで、この補正が出されているというふうに思うんですが、そこに自治事務になったということは、どういう意味が区には発生するというふうに考えられるんでしょうか。","respondent":"伊津野品川区保健所保健予防課長","answer":"区のほうが主体として行いますが、その内容につきましては、各区独自の施策ではありません。国のほうの要請に従って行うものでありますので、それについて、法に基づいて実施していく所存であります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"それとなおかつ、今学校に向けて何らか個別に、これは個名で郵送された３月末のお知らせで、学校を通じてとか、教育機関を通じて何らかの情報提供を差し控えているのだということの手だてをするべきだというふうに考えるんですが、その辺は何かご検討されていることがありますでしょうか。","respondent":"伊津野品川区保健所保健予防課長","answer":"リスクの説明ですが、あくまでも今回の接種、積極的勧奨の控えにつきましては、まだはっきりしないということなので、リスクが明らかに今回高まったということではないということを再度申し上げたいと思います。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最初にお伺いしたいんですが、最近盛んに子宮頸がん予防ワクチンに関して、インフルエンザワクチンとの関係がどうだとかという話がちまたで飛び交っているんですけど、何か医学的な意味というのはあるんでしょうか。そこをちょっとお聞きしたい。","respondent":"伊津野品川区保健所保健予防課長","answer":"先ほどもお答えしましたが、この副反応の報告は、単に上がってきたものを集計したものでありますので、インフルエンザみたいに昔からある、大分世の中に出て、副反応報告とかもなかなか上がらないような状況のワクチンと新しく入りまして、みんなの関心も高くて、副反応。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回の子宮頸がん予防ワクチンに関しては、今積極的な勧奨を中止するということになっていますが、一部には子宮頸がんが危険だから、どの程度危険があるか、それを検討するために中止になっているという非常に曲解している方がいるんですが、そもそも今回子宮頸がんのワクチンの積極的な勧奨を一時中断して、やりたい希望者には予防接種をその場でやっていただく、ただし。","respondent":"伊津野品川区保健所保健予防課長","answer":"今回重篤な副反応ということで話題になっておりますＣＲＰＳというものですが、その病気自体もよく、あまりわかっていない、原因もわかっていないということで、今後検討班のほうで、研究班を立ち上げまして、全国１６の大学病院を中心にそういう症例を集めまして。","voiceIndex":21,"id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それは当然のことでありまして、それをゼロにすることはできない。そもそも子宮頸がんというのは、今何人ぐらい死亡して、どのぐらいの発生頻度があるかということも、当然詳しく、副反応をこうして書くんだったら、詳しくその辺のことも、同じぐらいの比率で書くべきだと思うんですが、いかがでしょうか。","respondent":"伊津野品川区保健所保健予防課長","answer":"その点についての広報も今後ホームページ等を通じまして、そこは別に中止するわけじゃありませんので、その辺は継続していきたいと考えています。","voiceIndex":23,"id":"exchange-010"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ただ、それでも、やっぱりどうしても避けられないものというのがあるので、その避けられないときに、避けられない副反応が起きたときに、品川区ではどう対応するのか、そのワクチンの悪口を言うんじゃなくて、善意で注射を受けたにもかかわらず、それで予期せぬ副反応が出た患者さんに、どのように寄り添ってケアしていくのか、そのような観点の検討というのは必要だと思いますが、いかがでしょうか。","respondent":"伊津野品川区保健所保健予防課長","answer":"予防接種というものはそういうものでありますが、全体の、接種した場合のメリット、それを踏まえて現在では積極的な勧奨を一時中止しておりますが、定期接種であることは変わりありませんので、その辺の考えは続けていきたいというふうに考えております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後にします。どのぐらいの国で、何億人の人が今ワクチンをやっているか、その辺のこともやっぱり広報で載せたほうがいいんじゃないかと思うんですけど、いかがでしょうか。","respondent":"伊津野品川区保健所保健予防課長","answer":"子宮頸がんワクチンは、世界中で１００カ国以上超えるところで接種されておりまして、その中で中止になった国は１カ国もないというふうに聞いております。その辺のところをどこまで情報の中に織り込むかというのも今後検討していきたいと考えています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問・要望","question":"子宮頸がんのワクチンの話がいろいろ出ているんですけれども、杉並区でしたか、杉並区の中学生だったかな、それで、最近の、ここ何カ月かの品川区での接種の状況というんですか、杉並区のほうで問題になって、まだ積極勧奨しないとなってからはそんなに日がたっていないので、あまり統計的にあれかもしれないんですけど、そのあたり、どれくらい接種率が下がっているかということと、あと。","respondent":"伊津野品川区保健所保健予防課長","answer":"今年度になってからの接種率というか、接種の状況なんですが、まだ５月までしか入っておりませんで、新しく接種対象になります中学１年生につきましては、昨年の４月の段階で３０名だったのが、今年度は６３名になっておりました。","voiceIndex":29,"id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういう差があると思うんですけども、ただ、一方で、やっぱり非常に大事なワクチンだと思いますので、あとは、個人で判断してくださいとなると、やっぱり自分のかかりつけのお医者さんですとか、やってもらうお医者さんに相談するケースが多いと思いますので、そこでしっかりその辺の連携というんですか、医師会との、また各お医者さんによっても全く同じ対応ということはできないかもしれませんけども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"私は、社会福祉施設建設費から特別養護老人ホーム、杜松小学校跡の高齢者福祉施設整備費についてお伺いをします。先ほどのご説明の中で、この補正予算の説明書の中に、公共工事設計新労務単価適用等に伴いということなんですけれども、この新労務単価適用になった背景とかその辺の意味合いについて、もう少し詳しくお聞かせいただければと思います。","respondent":"永尾高齢者福祉課長","answer":"新労務単価が適用になったというところは、国のほうの政策的な、経済政策というところが大きくなっております。その政策に基づいて、国のほうで方針が出され、それに従いまして、区のほうでも単価の上昇ということで対応したところです。","voiceIndex":32,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それで一つ、ちょっと説明が長くなってしまうんですが、その背景としてあったのは、そもそもやはり、公共工事が前の政権のときにかなり減ってしまったということもあって、あとここ数十年、２０年ですか、不況が続いていて、公共工事が減っていたというところで、職人の待遇が非常に悪くなっていたというところがあったので、そこを何とか改善したいという思いで、国、東京都、区と連携をして。","respondent":"永尾高齢者福祉課長","answer":"労務単価の割合ですが、その工事の内容によっていろいろ、１５％だったり、３０％だったり、４５％だったり、やる内容によって変わってきております。","voiceIndex":34,"id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問","question":"国の単価を基準としてというのは、いわゆる労務費というか、例えばガードマンを雇ったら、ガードマンの単価とか、そこら辺、ちょっと所管が飛び越えてしまって申しわけないんですけど、あまりやり過ぎるとあれなんですが、もし、おわかりの範囲で結構なんですけれども、国のそういう基準を、１人につき幾ら、そういう基準を単価にしていると、そういうことなんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"それで、この労務単価ですけれども、職種によって大分違っておりまして、多いところだと、例えば防水工とか、はつり工とか、そういうのになりますと、人手が非常にかかるという部分もあって、２３％ぐらい増加していたり、また少ないところでいきますと、わかりやすいのでいくと。","voiceIndex":36,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"詳しいことは総務委員会等でまたいろいろお聞きをしていきたいというふうに思うんですけれども、先ほどの、今回の労務単価のアップの意味合いとかを考えますと、やはり元請けのゼネコンだけではなくて、下請け、また孫請けの職人がやっぱり賃金が少ない、また社会保険の加入率が少ない、低いというところを改善をというところでしたので、今回の工事に当たっても、ぜひそこのところ。","respondent":"永尾高齢者福祉課長","answer":"それで積算をした結果、６.９５％の伸びということで、結果的にはその部分についての補正をお願いしたところです。","voiceIndex":38,"id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"子宮頸がんの話に戻っちゃうんですが、このワクチンは３回接種ですよね。こういう方々に対して、やはりワクチンは３回打つべきものなんだ、ただし、こういうこともありますよ。勧奨はしないようにということになったかもしれないけど、打ち始めている方々に対して、どのような形でアナウンスをかけていくのか、何か方策があれば教えてください。","respondent":"伊津野品川区保健所保健予防課長","answer":"国のほうでも、こういう方たちにつきまして、不利益にならないような措置を考えるということを言っておりますので、それに基づいて対応していきたいと考えております。","voiceIndex":40,"id":"exchange-019"},{"speaker":"渡部委員","kind":"質問・要望","question":"３回打っていただかないとということも大事だと思いますので、その方々は、最終的にはご自身のご判断になるかとは思うんですが、しっかりと行政として後を追っかけられるところは今回このような報道が出されていますから、逆に追っかけていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問・要望","question":"さっきの杜松小学校跡のほうにちょっと戻らせていただくんですが、これは補正なので、この設計労務単価が上がったことで、４月１日以降に旧単価で契約した工事は変更の協議ができるという旨の通知文を、各建設関係のところに発送していただいたというふうに品川区の対応で聞いているんですけど、そうすると、この業者のほうからそれに応じて変更してもらいたいと、こういうことで協議の要請があって。","respondent":"永尾高齢者福祉課長","answer":"この件につきましては、工事委託をする予定でございまして、その委託の業者のほうから、工事単価が上がって、このままだと入札ができないというようなことのお話がございまして、それをきっかけに変更したものです。","voiceIndex":43,"id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問","question":"そこは区とかが、どこまでそれに関知できるかというのはあるんですけれども、国なんかは大臣みずから建設団体を呼んで、そこにお願いという形になりますけど、しっかりその上げた分を現場の人件費として、途中で下請け、孫請けに行くに従ってなくなっちゃうというのでは困っちゃうので、業者をもうけさせるために国とか区のお金をあげるわけじゃないので。","respondent":"永尾高齢者福祉課長","answer":"この趣旨を尊重しまして、実際に入札をするのは委託業者のほうにはなりますけれども、入札をした結果、従事される工事業者に対して、区のほうからも申し入れをしていきたいというふうに思っております。","voiceIndex":45,"id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そしたら去年、旦那さんが風疹にかかったんですよね。まだ妊娠していなかったから、よかったねという話にはなったんですけれども、やはり、そういう状況もあるので、男性のほうからも接種したいという声も出てきましたので、ぜひとも対象を広げるということをお願いしたいなと思うんですけれども、その辺いかがでしょうか。","respondent":"伊津野品川区保健所保健予防課長","answer":"昨今の報道にもありますように、明らかに風疹のワクチンが不足しておりますので、これからさらに対象を広げるというのは、なかなか現実問題として、財政的な問題もありますが、それ以上に最も受けてもらいたい方が受けられないというような状況に陥ることが予想されますので。","voiceIndex":47,"id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"財政問題以上にワクチンが不足しているということが原因で、最優先するところを選んでということだったんで、そうかと思ったんですけど、でも、やっぱりそこから広がってしまうと、とても親、その家族まで一生の問題になっていくので、本当にワクチンの不足というところでは何とも対応が難しいと思うんですけれども、ぜひワクチンが足りてくる状況になれば、ご検討いただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-024"},{"speaker":"井上委員","kind":"質問・要望","question":"６月７日付で文部科学省より子宮頸がん予防ワクチンの接種に関連した欠席等の状況調査というのがありまして、これは接種によって一定期間欠席している生徒、体育や部活を休んでいる何らかの制限が生じた生徒を調査するということですけれども、品川区の場合は欠席を通知している者はないということで既に報告をされているということなんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"だから、流行を防げないとすると、３年前の麻しんの流行のときみたいに、ワクチンもない、それから検査キットもない、何もないでお手上げで、ただひたすら流行が終わるのを首をすくめて待つか、じゃなかったら、ＭＭＲワクチンを１００万本単位で輸入して、それで緊急接種を、それこそ２０代から４０代の男女すべてに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-026"}]},{"id":"topic-02","title":"の専決処分の報告について（報告第２０号）","agenda":"の専決処分の報告について（報告第２０号）","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"これは自転車の事故なんですけれども、これは例えば自転車なんかは、今自転車の安全運転とかいろいろ言われていて、何か保険みたいな第三者に対する賠償保険というんですか、これはかかっているんですかね。何十万円とかとありますけど、あれも当然保険がかかっていると思うんですけども、保険で補填された分もこういう形で数字として出てくるのか、そこをちょっと教えてください。","respondent":"永尾高齢者福祉課長","answer":"品川区の場合は、自治体賠償責任保険に加入しておりまして、そこの保険の中で支払いをしたものです。","voiceIndex":61,"id":"exchange-027"},{"speaker":"たけうち委員","kind":"意見","question":"じゃあ、いずれにしても金額がどうあれ、出どころは保険なので、保険料は負担しているけども、直接の損害賠償という形で区がまた新たに持ち出したわけじゃなくても、一応こういう形で毎回出てくるということで、そういう認識でよろしいんですね。","respondent":"永尾高齢者福祉課長","answer":"支出をする際には、一般会計の中から支出をし、歳入につきましても、区の一般会計の歳入として入ってくるものですので、改めて区が独自の予算で支出するということではございません。","voiceIndex":63,"id":"exchange-028"}]},{"id":"topic-03","title":"（仮称）上大崎三丁目高齢者福祉等施設の整備および運営事業者の公募","agenda":"（仮称）上大崎三丁目高齢者福祉等施設の整備および運営事業者の公募","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"それで、杜松小学校のときは、いわゆる運営していただく事業者がハード面での設計から使い勝手のいいような形で、そういう意見をもらうということで、そういう形になった。それで何か問題があるかというと別に問題はなかったと思うんですが、そういう考え方でこれも比較的早い段階から設計にも事業者の方なんかが意見を言えるような、ということでのこういう流れという考えでよろしいんですか。","respondent":"永尾高齢者福祉課長","answer":"杜松小学校のときと違うのが、工事につきましては、区が工事をするということを考えております。もう一つ違うところが、スケジュールに少し余裕を持って建てているところです。","voiceIndex":69,"id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。もう一つ、この運営事業者の主な応募資格の事業実績で、ア、イ、ウと三つあるんですけども、この条件を満たしている区内の社会福祉法人というのは何法人ぐらいあるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"区内の法人、今五つの法人、その他ありますけれども、区内の特別養護老人ホームを運営している法人は全て満たしています。","voiceIndex":71,"id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"今の関連になるんですが、運営できるところが設計からということなんですけれども、指定管理者になり得る、そこのところが設計をし、そして契約の部分というのは、もし区外、都内じゃない、外部の方たちがそういったところで選定をされた場合に、設計までは自分たちが運営するところでいいんですけど、工事契約みたいなところはどこが権利を持つとか、そういったところの仕組みはあるんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"今回公募する部分というのは、設計の部分と運営の部分になります。設計の部分は運営事業者のほうで見つけていただく形にはなると思いますけれども、工事自体は区が実施しますので、契約等も区の基準に基づいて行うものです。","voiceIndex":73,"id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"公募の目的のところに、優良な事業者の誘致を図ることを目的に広く事業者を公募すると、この広くというのはどのぐらいまでのことを指しているのか教えていただきたい。","respondent":"永尾高齢者福祉課長","answer":"全国を予定しているところです。ですので、ホームページ等にも載せる予定になっております。","voiceIndex":75,"id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"全国ということで、その目的の一番最初のほうにも、良好なパートナーシップのもととあるんですが、いろいろ細かく精査しながら選定していくんだろうと思うんですけれども、あまり新しい、目新し過ぎるとどうなのかなと、私としてはちょっと不安があるんですけれども、その辺はどのようにお考えですか。","respondent":"永尾高齢者福祉課長","answer":"それで、また東側には区道が越境しているという部分、それとあと、土地自体も２ｍから３ｍぐらいの高低差があるということ、そういうことを考えると、やはりそういう整備にある程度精通しているところを選定しなければいけないということで、まずは書類審査を行って。","voiceIndex":77,"id":"exchange-033"},{"speaker":"井上委員","kind":"質問","question":"ここの場所が現状どういうふうな状況になっているのかということと、あと大変今設計が大変だなというのがわかったんですが、通常建てるときよりも、どのぐらいの工事経費の、これによってかかる経費、何割増しとか、そういったところでは、工事費の部分というのが設計に絡めて大変大きなウエートを占めてくるなというのを感じるんですが、どのぐらいの、同じ規模のものを建てるよりも。","respondent":"永尾高齢者福祉課長","answer":"現状は更地になってあります。ただし、この擁壁の部分の工事を考えますと、その部分が現在の推計では約２億円ぐらいかかるんじゃないかというふうに思われます。","voiceIndex":79,"id":"exchange-034"},{"speaker":"たけうち委員","kind":"提案","question":"施設の内容なんですけど、特別養護老人ホームとショートステイという形なんですが、ちょっと場所のイメージとかが湧かないのであれなんですけど、よくデイサービスみたいなものとか、小規模多機能とか、グループホームとか、こういったものを併設していくパターンが多いかと思うんですけど、ここはあえてそういう形じゃないという、それともこの事業者の提案によって。","respondent":"永尾高齢者福祉課長","answer":"区の条件として出しているのが、こちらにある特別養護老人ホーム１００名程度とショートステイ１８名程度なんですけれども、そのほかに任意提案ということで事業者が採算のとれる範囲で提案してきたものが妥当であれば、それも認めるようにしております。","voiceIndex":81,"id":"exchange-035"}]},{"id":"topic-04","title":"の平成２４年度品川区介護保険制度の運営状況","agenda":"の平成２４年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"井上委員","kind":"質問","question":"最後の１５ページのところのモニタリング等調査部会のところなんですけれども、なかなかここまで上がってくる件数は少ないのかなというふうに実際思っているんですけれども、委員の構成の推進委員の２名と向上委員会委員２名の方、ここで苦情が上がってきて、ここで調査をするという内容だと思うんですけど、どういった立場の方がここの４名になっているんでしょうか。","respondent":"永尾高齢者福祉課長","answer":"介護保険制度推進委員会の中で互選をした上で、モニタリング等調査部会の委員を決定しています。","voiceIndex":87,"id":"exchange-036"},{"speaker":"井上委員","kind":"確認","question":"ここのところで、人権擁護というか、そういった立場とか、そういう人たちがなっているのかなというところの確認をしたかったので、これは後でお伺いをしたいというふうに思います。それからこれは今年３年の計画の中の中途ということで、３年間終わった後で、来年、再来年でしょうか。","respondent":"永尾高齢者福祉課長","answer":"法改正の動きを着実ににらみながら、区のほうで検討するんですけれども、検討のその都度、介護保険制度推進委員会にお諮りしながら、現場の方、また当事者の方のご意見を聞きながら方針を決めていきたいというふうに考えているところです。","voiceIndex":89,"id":"exchange-037"},{"speaker":"井上委員","kind":"質問・要望","question":"要支援のところで、少しだけの手助けがあれば、在宅でひとり暮らしが継続できるというところは、小さな事業所とか、自立支援の助け合いをしているとか、そういった事業者からはよく聞くところで、やはり当事者の方たち、本当に財政の面というのは、これだけの資料を見ると大きくて、じゃあどこまで保険料を上げていくのかというところを考えると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"９ページの徴収方法別対象者数というところで、普通徴収の徴収率が７６.７％ですけれども、そうすると、残りの２３.３％は滞納という形になるんでしょうか。他区では、滞納している方々にペナルティーという形でサービスが受けられなくなるということもあるというふうにお聞きしているんですけれども、今品川区の滞納者数はどれぐらいいて、金額で言うとどれぐらいなのか。","respondent":"永尾高齢者福祉課長","answer":"その方の生活実態を見て、やはり生命の危険等がある場合につきましては、滞納されている方につきましても、サービスを行っております。保険料の支払いについても分割のご相談をするとか、そういう形で進めておりますので、無理な方法での徴収はしておりません。","voiceIndex":92,"id":"exchange-039"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、収支の状況、去年の４月から第５期になって、保険料がちょっと上がったんですけれども、１年たって、見込み額と同じようになっているのか教えていただきたいんですが。","respondent":"永尾高齢者福祉課長","answer":"収支の見込みですけれども、実際に保険料につきましては、若干普通徴収の徴収率が落ちた部分はありますけれども、実際には低所得者の方にそんなに、多少の負担は強いられておりますけれども、どちらかというと、高所得者の方の負担を増やしているような方式をとっておりますので。","voiceIndex":94,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3358#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":30308,"voices":100}},{"id":"h25-20130701-8","meetingId":"h25-cm07","date":"2013年7月1日","dateIso":"2013-07-01","committee":"建設委員会","time":"午前１０時０１分～午後 ２時３５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を92件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４８号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第４８号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"確認","question":"地域の確認をしたいと思います。資料２と３のところで、条例で定めた事項、新旧対照表があるんですけれども、赤字で示されているのは新しい、わかるんですが、これ、以前どうだった、何がどう変わったのかというのが新旧対照表があるにもかかわらず、どう変わったかがこれだとわからないんですね。なので、１つ１つ、アからケまでですか、これ、教えてください。","respondent":"中村建築課長","answer":"これを７００％に変更いたします。それから、その下が建蔽率の最高限度ということで、７０％と申しますのは、これは現在、従前の都市計画で行きますと８０％でございました。これを７０％ということで、空地を多く増やすということで減らしています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"２５ページの説明なんですけれども、一点斜線のところが地区計画再開発促進地区の全体の地域ということで、網かけのところが地区整備計画の区域、今回はこの網かけのところだけなんですか、ちょっとそこがよくわからなくて、真ん中の白抜きのところが、ここは建物の制限だけなんですか。大もとの根本のところなんですけれども、なぜ容積率を４００％から５００％を７００％にまで引き上げるのか。","respondent":"溝口都市開発課長","answer":"続きまして、高さの考え方ですが、これまで、先ほどの容積と相対する形になりますが、そういった公共貢献等を評価する中で、一定の建物の高さが必要になるということで、Ｂ地区については１４５メートル、Ｉ－３地区につきましては。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２５ページの説明をしていただいた網がかかっていない部分は、これから中身が決まっていく、地区計画的なものはまだ決まっていないのでそのままということだと思うんですけれども、１つは、こうやって武蔵小山の周辺５６ヘクタールが大きな網かけにはなっているんですけれども、この中で地区ごとに地域の発想でばらばらに計画が立てられること自体、一つ一つを見ていくのではなくて。","respondent":"溝口都市開発課長","answer":"大きく３点質問をいただいております。その中で一つ目、地区全体の考え方、またＩ－３地区がどうかというのは、これはあわせてお答えします。当地区につきましては、しゃれた街並み推進条例、東京都の条例になります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その間、２０１２年の世論調査でも、再開発による地域整備というのは、１５問中１５位の最低なんですよね。再開発による地域整備、これを求めているのは６％のみなさんですよね。なので、区が行った調査とすごいギャップがあるわけですけれども、これにかわる情報というか、いや、こうじゃなくて、いや、区民は変わっていますという情報があるんだったら示していただきたいと思いますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"地元の方々というこの定義につきましては、基本的には、やはりまず第一は権利者の方々が大事だと考えていますので、協議会等が地元で立ち上がっておりますので、５６ヘクタールの対象区域の中で協議会の方たちとお話し合いをしていますし、その中で定まってきたもの。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"Ｂ地区に関しては、道路１０％、空地、今までなかったので２５％拡大される、私は道路は本当に狭いので、広がる、また空地もないので、それが確保されるというのは、本当に地域の環境、それ自体は空地ができるということはいいことであると思っていますけれども、たびたびお伺いしても、税金投入の額が全然はっきりしないんですが、わかったら教えていただきたかったんですが。","respondent":"溝口都市開発課長","answer":"空地、できることはよいことということなのであれなんですけれども、区民の声の関係ですが、先ほど、Ｂ地区では２人という話でしたが、当然その上の借地権者、また、現在、組合設立に向けて、今現在、店舗等を行われている借家人の方、また間借りして営業されている方。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"意見","question":"免震構造とか制震構造という言葉は、この間の駅前のところの開発のときもこれで大丈夫ですと、そこも大丈夫と言っていますけれども、決してそういう段階ではないんですね。私は本当に大きなリスクを背負っているのと、あと、指導するという立場にある行政が、今の段階で本当に前にどんどん進んでいいのかというところにおいては、本当に大きな疑問を持っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"もう一度確認したいんですけれども、例えば、ここだけでなくて、東京都全体がさまざまな再開発が進んでいます。例えば、目黒であったり、恵比寿であったり、渋谷であったり、当然これは東京都の中で、ある意味、武蔵小山と商業のライバル関係になるわけですね。","respondent":"溝口都市開発課長","answer":"そういった中で武蔵小山、品川区長計で行きますと、西の玄関口、また、荏原の中心核として、これからもまちづくりを発展させていく持続的なパルム商店街の繁栄等を築いていく、そういった中で今回、まちづくりというのは大きく役割を果たしているというふうに私は考えております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"それは続けていくんですけれども、例えば、今まで品川区内でもさまざまな町で再開発をしてきましたよね。今いろいろ意見があったけれども、再開発が完了した地域の区民の方々から、これをやらなければよかったとか、それから、再開発そのものが区民の利益に反するとか、そういう意見があったんでしょうかということをまずお伺いします。","respondent":"溝口都市開発課長","answer":"品川区におきましては、大崎をはじめ大井町、さまざまな拠点と言われるところで再開発事業をこれまで進めてきました。そういった中で、広場がある、空地ができてよかった、または道路が広がってよかった。","voiceIndex":18,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"相当好評をいただいたんです。だから、先ほどの意見を聞いて、非常にいろいろおっしゃるんだけれども、私としては、そういうことに対してもっと合理的に反論してほしい。実際、再開発の成功例もたくさんあるわけで、そういうことをもっと品川区ははっきりと打ち出していって、理解を求めていく作業をすればいいと思うんですが、いかがでしょうか。","respondent":"片田都市環境事業部長","answer":"特に大崎の西口の再開発の中でも、開発によって生まれた空地のところに対しては、避難上の空地というところの位置づけの中で、東京都としても広域的な避難拠点といいましょうか、そういうところにも位置づけられてきておりますので。","voiceIndex":20,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"意見","question":"木造のいろいろなアパートが並んでいたところを全部壊して、１１階建てのマンションにする計画になっています。だから、やっぱりいろいろな思いがあるかもしれないけれども、当然、何十年も時間もたてば、建物を更新していかないといけないわけであるから、やっぱりそういう現状もしっかり見た上で私たちは対処していかなければいけないなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問・要望","question":"この開発によって、行政側の一番、商業の面からも、土地の活性化の面からも私は意義があると思うんですけれども、そこのところのご決意、あるいはお考えがあったら、ご答弁いただきたいと思います。","respondent":"溝口都市開発課長","answer":"ただ単にマンションを建てるだけではなく、低層に一定の商業施設を入れる、またはそれも大規模店舗ではなく、個店等を入れて、商店街とともに活性化できるような商業店舗の導入を考えていきたいと考えておりますので、ただ単に再開発の地域だけがという形ではなく。","voiceIndex":23,"id":"exchange-011"},{"speaker":"大沢委員","kind":"意見","question":"そういう意味では、この武蔵小山の地、今まではただ単に品川区の戸越銀座、大井サンピア、品川区の商店街の中でずっと戦後来ましたけれども、広域的な部分、東京都の中でこの品川の武蔵小山の商業地としてのポテンシャルなり意義がどういうふうにあるかということを考えながら、近隣住民の方、商業地、あるいは住宅地もある、そこの部分としっかりとした連携をとりながら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"東京都が決められているんですか。なので、どうしてもこの地域でまた再開発した後もやっていきたいよという方たちの条件整備等々はかなり丁寧にやっていただきたいし、この商店街全体を見て、どういう商店街にしていくか、街並みにしていくのかということは、やっぱり品川区が意向を聞くと言っても、なかなか借地権の方が８６軒ですから、なかなか言いたい事が見えないだろうと思うんです。","respondent":"溝口都市開発課長","answer":"資料３の２４ページの条件の考え方ですが、これにつきましては、基本的には今回定める地域の方と区で話し合いを進めていく中で、そういったものを東京都に案として上げて、調整等でできたものが今回の成果という形になっております。","voiceIndex":26,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"このご時世ですから、じゃあ、新しい場所になって、新しい地域になって、本当に売り上げも温存できるのかとなると、かなり不安なところがあると思うんです。そこは担当者間であると思うので、そことしっかりと協力し合いながら、その地域の特性を失わずに、そして新しい街並みといいますか、商店街というものを目指していただきたいなということで、それについてお答えいただきたい。","respondent":"溝口都市開発課長","answer":"商店街の継続性につきましては、当然、うちの中でも担当の所管部署がありますので、そことの連携、また、地元の商店街等ありますので、そういったところとの連携というのを図りながら、商業店舗のテナントをどうするかとかというのは決めていきたいというふうに考えております。","voiceIndex":28,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点です。１点目は、伊藤委員にお伺いしたいんですが、先ほど、共産党の施設とか個人の名前が出されましたけれども、そこの建て替えのところは、都市計画とか地区計画にかかっている地域の問題なのか、民間の建て替えの問題なのか、誤解を招くといけないので明らかにしていただきたいと思います。地権者の方々も本組合設立のときに、意見が合わなかったら出ていくしかないんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-015"},{"speaker":"伊藤委員","kind":"意見","question":"先ほど、個人名とおっしゃいましたけれども、私は桜井恵子元区議会議員の名前でお話をさせていただきました。それだけですので、それ以外の個人名は話しておりませんのでご理解ください。それから、再開発かどうかということについてはわかりません。そういうことです。","respondent":"溝口都市開発課長","answer":"そういったものも少しどういう形で権利者の方たちが事業継続を図っていくのか、そういったものについては十分配慮しながら進めるようにというふうに準備組合には指導しているものですので、一概に再開発をやるとみんな出ていかなければならない。","voiceIndex":31,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"伊藤委員に対しての再開発かどうかわからないというところにおいての、今回、出す事例ではなかったのではないかと思います。なので、取り消していただきたいなと思うんですが、固有名詞、桜井恵子元区議ですか、おっしゃった。こういうところに出すべきではないと思います。私は取り消していただきたいと思います。正しい表現の仕方をしていただきたい、これはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"ただ、それと一緒に、商店街がある。ですから、２点です。今の状況とこれから先の問題。","respondent":"溝口都市開発課長","answer":"Ｂ地区の権利者の対応ですが、これにつきましては、借家人、また間借人、そういったさまざまな権利をお持ちの方が当地区にはおりますので、そういった方々にきめ細かく対応するようにということで、準備組合のほうを指導しておりますし。","voiceIndex":34,"id":"exchange-018"},{"speaker":"原委員","kind":"質問・要望","question":"やはりどうしてもこれは駅に隣接しているという形の再開発ですので、あくまでも地域住民と、それからあとは商店街、必ず再開発のときには、従前の昔からある商店街の組合と、それから、新たに入ってくる、どういう表現をしていいのかわかりませんけれども、核となるものが入るか入らないか、それによっても大分違いますし、それからもう１点、区のほうと電鉄を含めた形での。","respondent":"溝口都市開発課長","answer":"再開発等をやるに当たっては、地元の商店街、複数商店街がありますので、そういったところとも協議等をしながら進めてきているものですので、それにつきましては引き続き継続して行うような形で進めていきたいというふうに考えております。","voiceIndex":36,"id":"exchange-019"},{"speaker":"原委員","kind":"質問・要望","question":"ただ、この武蔵小山に関しましては、そういった問題が以前にやはり出たということもあるので、その辺をやっぱり行政としては考慮に入れて慎重に扱っていただきたいので、その辺のご意見があったら。","respondent":"溝口都市開発課長","answer":"例えば、今後、Ｂ地区でやられる再開発事業におきましては、しっかり風環境についても計画段階から周辺への影響を考慮した形で計画を進めているものですし、今後も事業を進めるに当たっても風環境の変化というのは十分検証しながら。","voiceIndex":38,"id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"この武蔵小山は目黒区と隣接しているわけですけれども、その先、２６号線ですか、そのまま行きますと、目黒区の学芸大学などと直結しているというところで、あの地域は目黒本町のあたりの方々はほとんど武蔵小山のほうに買い物に行くのではないかと思うんですが、将来的に武蔵小山が発展をすることによって、隣の目黒区の学芸大学、もしくは自由が丘。","respondent":"溝口都市開発課長","answer":"ただ、あくまでも品川区のところで行きますと、品川区につきましては、武蔵小山駅を西の玄関口と位置づけております。それにふさわしい町に今後もまちづくりを進めていきたいというふうに考えるものです。","voiceIndex":40,"id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"今お答えいただきましたけれども、品川区と目黒区、区は違うけれども、そういう意味ではどのような競争力が生まれるのかとか、２カ所が一緒に成長、どのような発展があるのかということをもう一度お聞かせください。","respondent":"溝口都市開発課長","answer":"当然、町を活性化することによって、目黒区にお住まいの方も武蔵小山駅をご利用される方が、より日常の買い物ですとか、そういったものが便利になるということで、品川区内だけではなく、周辺地域の町の活性化にもつながるものが今回の開発、まちづくり。","voiceIndex":42,"id":"exchange-022"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"これまでのご説明を伺っていて、再度、参考のためにどのような地区の方たちのご意見なり、あるいはこの改正をしようとされていることに関してのご意見なり、方向性が出ているのかというのをお聞きしたんですけれども、例えば、Ｂ地区に関しては、今、建設組合も立ち上げている、準備をしている段階だということで、いわゆる町の老朽化、これを更新をどうしていくかという考え方、これは理解できる一方で。","respondent":"溝口都市開発課長","answer":"今回、事業を、都市計画をする前段で、事業説明会等を行う中でも、準備組合のほうでやった説明会の中の資料を見ましても、商店街の活性化ですとか、木密の解消、そういったものに向けて今回の再開発をやっていくんだということでやっておりますので。","voiceIndex":44,"id":"exchange-023"},{"speaker":"こんの副委員長","kind":"提案","question":"先ほどの他の委員からの質問のご答弁でもそこら辺は出ていたので、もう少しいわゆる具体的な活性化と一括りに、あるいは道路が広がる、緑が増える、それはそうなんですけれども、それは非常に大事なことで、更新をしていく、町の老朽化を、いわゆる更新をして新しく生まれ変わり、再開発ですから、今まで以上にいいものにされていくというところでは、私は大変大事な事業であるので、これはやるべきだと。","respondent":"溝口都市開発課長","answer":"一般に開放する駐輪場を整備することによって、地域の駐輪対策等も行っていく、そういったものも事業になっているものです。そういったことをすることによってやっていく。今回、地域貢献という形で、子育て支援施設も今回の再開発には入れるという形で考えているものです。","voiceIndex":46,"id":"exchange-024"},{"speaker":"こんの副委員長","kind":"意見","question":"地域貢献も含めて進めていくという、こうしたことが、これからまだまだ住民の皆さんとの説明会等もまたご理解いただくことでの話の中では、ぜひより細かく、それはお考えでしょうけれども、ぜひその点を見据えながら、町の活性化、老朽化を更新をしていくというこの再開発の考え方というものをご理解いただくような形で、やっぱり老朽化したままでは、いくら活性をしたくてもできないという部分を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"反対します。意見を言ってよろしいでしょうか。高層化は区民の願いではありません。高層化をすればするほど、ゼネコンに利益が流れるという、これはもう既に明らかであると思います。３・１１以来の新たな長時間長周期地震動が超高層化への安全性にも疑問が出されている中で、東京都と品川区が主導して高層化を進めることは、私たちはやめるべきであると思っていますので、反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-026"}]},{"id":"topic-02","title":"第４９号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第４９号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"すみません、ちょっと確認させていただきたいんですけれども、この移設はもう既に行われたんでしょうか、行われていない、ちょっと確認だけさせてください。","respondent":"谷口交通安全担当課長","answer":"工事が終了しまして、今、各関係機関と調整しまして、移設につきましてはまだ、この議決が終了しまして、それ以降になります。","voiceIndex":61,"id":"exchange-027"},{"speaker":"大沢委員","kind":"質問","question":"広報に載ったように記憶はしているんですが、この件については、広報しながわには載っていないですか。","respondent":"谷口交通安全担当課長","answer":"６月２１日付の広報しながわのほうに提示しています。","voiceIndex":63,"id":"exchange-028"},{"speaker":"大沢委員","kind":"質問","question":"ここの６月２１日、これは何面になりますか。これですね、見つかりました。情報館というところで、再移設をしますという、これ、お知らせということで出ていますが、これ、今日、条例審議ですよね。審議をするところで、ここのところのタイミングとして出していいものなのかどうか、ちょっとお伺いしたいと。","respondent":"谷口交通安全担当課長","answer":"当然ご指摘のとおりだと思いますけれども、やはり利用者に対する周知という意味を含めまして、事前に広報しながわに載せた次第です。","voiceIndex":65,"id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"手続、議会に対する提示、また予算、今までの手続等は十分にわかるんですけれども、やはりこの議案が議決されて初めてこういうものが広報等々に載ってくるべきであって、これを否決したらここの部分はどうなってくるんですか。そこら辺の危機管理とか、どういうふうにお考えなのでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"今回の条例改正は特に場所、位置の変更ということで改正をします。もちろんそれに付随する規則等がございまして、中身の内容等々を細かく今までも説明をしてきたところですけれども、そういったことを経て、このような形の手続をするですので、ご理解いただければと思います。","voiceIndex":69,"id":"exchange-030"},{"speaker":"大沢委員","kind":"質問・要望","question":"理解できないのでお話をさせて、決してけんかを売っているわけではないんですけれども、基本に忠実であるべき行政というものが、こういうフライング的なものをやる、たびたびこういうことがあっては困るので、以前にも何かあったように私記憶があったのでこういうことを聞かせていただきましたけれども、その点について、今後どのように扱われていくのか、お考えがありましたらお示しいただきたいんですが。","respondent":"松代防災まちづくり事業部長","answer":"そういう中にあって、このような、まず工事をし、この位置の変更があるということを並行して進めする。これはこれまでも我々の進めてきた中では、議会としましてもご理解とご承知をいただいた上で進めているものと、このように認識しているものです。","voiceIndex":71,"id":"exchange-031"},{"speaker":"大沢委員","kind":"質問","question":"先ほど、以前にあったやにというのは、この委員会ではなかったから、それは付言をしておきます。ただし、ここの部分においては、条例である以上、委員会の委員長が報告をして、それなりの議決をもってこれが執行されるということが大事だ。理解とというのは、それはあくまでも部長の単なるご認識であって、そこは改めていただかないと私は困ると思うんですけれども、どのようにお考えになりますでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"ご指摘の点は厳に受けとめまして、今後もしっかりと議会に報告し、また、ご議論いただき、ご審議いただいた決に基づいて執行するように努めてまいりたいと、このように考えているところです。","voiceIndex":73,"id":"exchange-032"},{"speaker":"大沢委員","kind":"質問・要望","question":"わかっていながらということなので、ご容赦賜りたいと思うんですが、もう１個、ここの部分の手続上のものについては、ご一考いただきながら進めていただきたいなと。確かに利用者の方の利便性を考えますと、早い提示というのはわかりますが、やはり議会の議決が必要だということは十分にご認識いただいて、特にこういう公の配布物に関しては、掲示する上ではご留意をいただきたいなとお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-033"},{"speaker":"伊藤委員","kind":"質問","question":"今のことは繰り返しませんので、これからのことで、要は、これは条例なんですよ。年４回の本会議でしか可決できない話であって、そうすると、利用者の利便性を確保するのであれば、議会日程が当然あるわけじゃないですか。例えば、第２回定例会に上程するとか、今は第３回でしたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問・要望","question":"例えばこれが内部の規約改正であるとか、それから、所管の中でのものだったら話は別だけれども、条例だと我々としてもそう言わざるを得ない話なので、それには年４回の本会議の中でこういうふうなことを可決していこうということを願うのであるならば、先に条例案を議会に出して、それからこういうふうにＰＲしていくことを考えたほうがいいんじゃないでしょうかと思うんですが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"ちょっと言いわけではありませんが説明をしますと、まず、ここの計画に当たっては、先ほど言いましたように、移設に大きな費用がかかるということで、まず、きちんと予算審議を経て、平成２５年度の対応ということが必要になってくるということがあります。","voiceIndex":80,"id":"exchange-035"},{"speaker":"原委員","kind":"質問","question":"先に意見を出してはいけないんですけれども、ですから、今たまたまこの話で、大沢委員のほうからお話があって、伊藤委員もそういうようなお話があったんですが、そこに入ってしまうと、今度は手続論の問題と、単純な話として、土地を買うときにも実際には議会というか、議会自体が動いていない開発公社が先というような……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-036"},{"speaker":"原委員","kind":"質問・要望","question":"議会は開かれているときが決まっている。であれば、実際に広報でオープンにしていくのであれば、そこに、例えばですよ、例えば、これは可能かどうかというご意見をいただきたいんですけれども、括弧書きだったり、ただし書きだったり、条例案が必要になりますとか、そういうようなものをちょっと入れることができるのかどうか、その辺、行政のほうのお考えをいただければと思います。","respondent":"松代防災まちづくり事業部長","answer":"いずれにしましても、繰り返しになりますが、本来の手続論、議決等を経てやるべきことが我々の基本だということに立ち返って対応させていただければというふうに思っております。","voiceIndex":83,"id":"exchange-037"},{"speaker":"原委員","kind":"意見","question":"今まで品川区は、ここへ来て、ここの数年私は思うんですけれども、非常に行政処理が早くなってきて、スピーディーになってきているので、私はすごく、特にこの建設関連に関しましてもいいことだと、行政がおくれることは、結局それは最終的には区民が苦労してしまうことですので、意見として、あくまでも、その前に伊藤委員や大沢委員から出た話も含んでいただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"質問なんですけれども、今回、東口と西口がありますけれども、台数の変化、新しいところに移設して増えると聞いて、減るところもあるんですか、台数の変化を教えていただきたいと思います。この対策で十分なのかどうか、その辺も含めてお答えいただきたいと思います。","respondent":"谷口交通安全担当課長","answer":"総体的にですが、現在、定期自転車、当日のバイクを含めまして１,００７台収容しております。それが移設後は１,４４４台と、プラス４３７台増加予定です。キャンセル待ち等が３００人ほどおりますので、これも全部吸い込めるという予定ですので、特に問題等はございません。","voiceIndex":86,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"見に行きましたら、結構本当にいっぱいですね。そういった面では、あの辺がすごいガチャガチャしているなというか、混み合っているなという思いもしたんですけれども、なので、阪急に対しての働きかけとかもあるんですけれども、郵便局前の問題も含めて、これからきちんとやっていけるのかどうかというところをもう一度お聞かせいただきたいと思います。","respondent":"谷口交通安全担当課長","answer":"引き続き、放置自転車防止につきましては、手続をとってまいりたいと思います。あわせて、阪急の関係ですけれども、阪急は今、工事をやっております。あそこが終わりましたら、付置義務でまた数百台、２００台か３００台増えますので、それで十分対応できると考えております。","voiceIndex":88,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"は要望なんですけれども、１点は、定期利用申請書を置いてあったのでいただいてきたんですけれども、定期利用のところが、今、屋根なしが高架下になると屋根ありになって、２,３００円になりますので、あらかじめご確認いただきますと書いてあるんですが、この辺のことは、どうして上がるのか、もとに戻ったんですか。","respondent":"谷口交通安全担当課長","answer":"以前は下にあったものが外に出たりとか、そういう部分、配置をやりましたので、その関係で若干料金の差が出ております。従業員等の施設要望につきましては、引き続き、指定管理者ですＮＣＤのほうと調整をしながら実施を考えているところです。","voiceIndex":90,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"利用料金に関しては、指定管理者のほうで決める料金でしたか。できたら、これ、屋根あり、屋根なしという状況はあるのかもしれないんですけれども、なるべく本当に利用料は上げないでいただきたいなと思うんですけれども、いかがでしょうか。","respondent":"谷口交通安全担当課長","answer":"現状の施設環境等々を含めまして、一応ご理解いただきたいと思います。ぜひよろしくお願いいたします。","voiceIndex":92,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"整備されていたと思うんですけれども、それをどういうふうな形に原状復帰をするのか。利便性いいんですよね。高架下よりも駅に近いですから。もう一つは、精算機、かねがね要望しているんですが、電子カードというんですか、ＩＣカード、Ｓｕｉｃａ等々が使えるようにならないのかなと思うんですけれども、非常に利便性がよくなると思うんですが、それの検討はどうなっているでしょうか。","respondent":"谷口交通安全担当課長","answer":"阪急等の付置義務等も合わせますと４,０００台近くなります。それを踏まえますと、十分に対応できる体制と考えているところです。原状復帰につきましては、委員ご指摘のとおり、原状復帰は当然考えております。","voiceIndex":94,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"十分足りるということなんですね。４,０００台あるからもう大丈夫ですよというのは、果たしてどこからその台数が出てくるのかなと。周りの放置自転車等々の状況を踏まえても、４,０００台あるので大丈夫だというふうに結論づけているのか、そこの判断の基準を教えてください。これはもう少し研究をしていただきたいなというふうに思うんですが、コメントをお願いします。","respondent":"松代防災まちづくり事業部長","answer":"最初のほうの駐輪台数で満足しているかどうかですけれども、これは非常に難しいと考えています。委員からもそういった疑義が出ているぐらい、我々も違う意味では、何をもって満足台数かというのを把握するのに、いろいろと苦慮しているところがあります。","voiceIndex":96,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"今話題の地下に駐輪場をつくって、自動で排出するというようなことがありますので、これからはこれを機会に少し研究を進めていただきたいなと思います。最後に、電子のカードですけれども、カード利用については、今後、利便性も考えると、ぜひ検討の中に入れていただきたいということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-045"},{"speaker":"こんの副委員長","kind":"質問","question":"この移設に関しては、私も議会で、実は今、西本委員がおっしゃった部分、残すべきではないかと議会質問でもさせていただたいたんですけれども、今、緊急的措置という、そのときにもご答弁いただいて緊急的措置でしたので、この工事が終わった後は移設をしますよということでありましたけれども、ここの部分はそうだとしても、東側の部分、きゅりあんのほうに向かうここも今残るという状態ですけれども。","respondent":"松代防災まちづくり事業部長","answer":"もちろん東口のほうもそういった形で言えば、ほかへ駐輪場をきちんと確保して、そこが本来の歩行者もしくは修景等の施設も含めた形が一番望ましいということは十分承知していますが、周辺の状況等も考えまして、西口は元に戻させていただき。","voiceIndex":99,"id":"exchange-046"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"もう一方で、やっぱり商業、こういう企業に駐輪場をお願いするということも一方でされているかとも思いますけれども、建設後、どのようにこの駐輪場がなされていくのかということがもしおわかりになれば、ここら辺のご説明もいただきたいと思いますが、私も台数に関しての確保というんでしょうか、移設というよりも、そのまま残して。","respondent":"松代防災まちづくり事業部長","answer":"今後ともそういったことは十分に伝えてまいりますし、我々公の行政がやる対応と、その鉄道事業者、または民としての本来すべき受け入れるお客様等への対応としての駐輪場、そういったものは今後もしっかりと伝えて指導してまいりたいと、このように思っております。","voiceIndex":101,"id":"exchange-047"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"現状わかりました。もう１点、細かくて恐縮なんですが、駐輪場の機械というんでしょうか、ガチャンと入れる、この機械を工夫していただきたいんですね。どうかここを工夫をしていただきたいことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-048"},{"speaker":"伊藤委員","kind":"質問","question":"今までいろいろな質問を聞いていてふと思ったんですけれども、何も品川区の責任だけで駐輪場を設置する必要は私はないと思っています。だから、例えばＪＲとか、東急とか、そこを利用するであろう鉄道事業者があるわけだから、例えばＪＲなり東急に対しては、もっと強く要請してもいいんじゃないですか。何か見ていて皆さんがかわいそうに見えてきたんです。お聞かせください。","respondent":"松代防災まちづくり事業部長","answer":"一方で、既存の駅等につきましてはというと、まだまだおくれておりますけれども、何らかの形で、例えば東口等でＪＲのほうの、若干店舗を入れた改築等があるというようなときには、必ず駐輪場をつくるというようなことも含めて指導しておりますし。","voiceIndex":104,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"わかっていますが、区としてやれることをやります、ほかのところもやれるところはやりますという考え方でやっているのだろうと思うんですが、そういう考え方よりは、自転車対策を品川区としてこうやっていくんだよということの柱をつくった上で協力体制を促すというのが、その発想というんですか、考え方というか、何とかしてよねというだけでは、やっぱり協力体制もとれないだろうと思うので。","respondent":"松代防災まちづくり事業部長","answer":"区としての自転車等への対応です。どうしても今、駐輪対策のほうでのお話をずっと差し上げてきましたので、これまでの放置自転車への対応というところがまず一つあります。","voiceIndex":107,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ難しいのはわかります。そういう意味では、対処療法的なことをやっても仕方ないので、ですから、全体的に通して区民の方々にどういうふうなことを要望し、自転車に対して品川区の考えはこうだからというようなところを明確にしていく必要があるのかなというふうに思いますので、区も大変でしょうけれども、頑張っていろいろ研究していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-051"},{"speaker":"あべ委員長","kind":"質問","question":"すみません、私から１点だけ質問させてください。最初に議論になっていました条例改正案の提出のタイミングなんですけれども、第１回定例会は予算の関係で難しいとしても、５月の臨時会という発想はなかったんでしょうか。ある程度検討された上で出されたんですか。","respondent":"松代防災まちづくり事業部長、あべ委員長","answer":"いずれにしましても、全てが言いわけになりますので、今後は、先ほどご指摘があったように、きちっとした手順を踏むことが我々の責務ですので、今後。機動力がある行政というのはとてもいいことだと思いますが、議会対応というものについても、機動力をぜひ持って当たってほしいと思います。","voiceIndex":110,"id":"exchange-052"}]},{"id":"topic-03","title":"を行います。 初めに、(1)専決処分の報告","agenda":"を行います。 初めに、(1)専決処分の報告","exchanges":[{"speaker":"西本委員","kind":"質問","question":"「工事費等」と書いてあるんですが、「等」とは何でしょうか。この職員の方のけがとか、後遺症、そういうものはございませんでしたでしょうか。","respondent":"稲田道路課長","answer":"ここで書いてある工事費等というのは、工事の材料と、それにかかる手間という意味で工事費等という表現をさせていただきました。職員におきましては、けが等はございませんでした。","voiceIndex":127,"id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問","question":"この２１万円の支払いというのは、おそらく２３区が入っている保険から支払われたものとして想像するんですけれども、それでよろしいのでしょうかというのが１点と、それから、もちろんこういうことについて補償されていることはわかるんだけれども、時としてそういう制度に守られているのではないかという推測を私はするわけです。","respondent":"稲田道路課長","answer":"そういう意味におきましては、常日ごろから注意喚起というのは言っていくことはもちろんのことなんですけれども、今回、私どもが対応したやり方というのは、ベテラン職員、ちょっと若手だったんですけれども、ベテラン職員が一緒に同乗しまして、車の運転の仕方。","voiceIndex":129,"id":"exchange-054"},{"speaker":"伊藤委員","kind":"確認","question":"後段部分はわかりました。前段の保険のところの確認で、すみません、私が記憶しているのだと、２３区の全ての区が加入して、当該区の職員がこういう事故を起こした際に、そこから支払われる保険があると推測するんですけれども、このお金の出どころは、そこなんですよね。","respondent":"稲田道路課長","answer":"それとはまた別なものということです。","voiceIndex":131,"id":"exchange-055"}]},{"id":"topic-04","title":"品川区立区民住宅（ファミーユ西五反田東館）の指定管理者募集","agenda":"品川区立区民住宅（ファミーユ西五反田東館）の指定管理者募集","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"区民住宅の指定管理の状況が今どうなっているのか、ここのファミーユ西五反田東館、西館だけでなく、数と、どこが指定管理者を受けているのかを教えていただきたいのと、前回、何社が応募して、どこが管理を受けたのか、前回が東急コミュニティーですかね、その流れを教えてください。","respondent":"大串住宅担当課長","answer":"これまでの応募状況ですが、東館につきましては、前回、この東急を含めて３社の応募がありました。その３社の中から東急が決定されたです。","voiceIndex":138,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問","question":"ここのファミーユ西五反田東館、西館以外のところは、みんな宅建だったんですね。今、区営も区民の借上型も、両方とも全部宅建でやっているというところにおいて、なぜファミーユのところは、多分前のところも大手だったと思うんですけれども、大手でなくてはいけない理由とか、前回何がどう変わってここに移ったのかということを教えてください。","respondent":"大串住宅担当課長","answer":"その違いです。単純に申し上げまして、ファミーユ西五反田、先ほど申し上げましたように、東館が４００戸、西館が９８戸というところでございまして、その建物規模の中で、消防法の関係で２４時間の防災センターを設置しなければならないという条件になっています。","voiceIndex":140,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"今回の選定方法がプロポーザル方式ということなんですが、どういう希望をもってプロポーザル、どういう改善を求めているのかというところをお聞きしたいと思います。","respondent":"大串住宅担当課長","answer":"そうした中で、応募いただいた企業、事業者の方のほうからいろいろなアイデアをいただいて、その中でよりよい住民サービスの向上、こういったものが図られるものについて指定管理をお願いしたいというふうに考えているところです。","voiceIndex":142,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"滞納者が増えているということを考えると、家賃なんかが結構高くなってきているのではないかなと思うんですが、その辺の今後の考え方、対策、それから指定管理者に対しての求めるもの、滞納者等々の対策に関して求めるものというのはどういうことなのでしょうか。","respondent":"大串住宅担当課長","answer":"先般、昨年の１１月でしたけれども、最初のパレスガルといったところが２０年の契約満了に伴ってオーナーのもとに返還をしたという形です。借上住宅につきましては、今後も２０年の契約満了とともにオーナーのほうに返していく、この方針は変わりません。","voiceIndex":144,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"その滞納者に対する、今回の指定管理者に対しての役割というのは、どういうふうに考えたらいいのでしょうか。","respondent":"大串住宅担当課長","answer":"そうなった場合、やはり初期の対応というのが一番大きいものになってくるのかなと思います。例えば１０万円の家賃、これが１カ月滞納して、次の月も滞納するとなれば、雪だるま式に２０万、３０万というふうに膨らんでいってしまいます。","voiceIndex":146,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、指定管理者の中での、例えば区の中でもいろいろ相談の窓口がありますでしょうし、いろいろ助けられる部分があるかと思うんです。そこはやっぱり区の機関の役割もきっちりわかった上で紹介してあげるとかということで、なるべく裁判とかにかけないような状況でうまく解決できると、お互いに傷をつけなくて済むのかなと思いますので、ぜひそこら辺も含めて選定をしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-061"},{"speaker":"原委員","kind":"質問","question":"ですから、中の施設に関しては、歩くところには車が突っ込んでこないように全部きれいになっているんですけれども、意外と駐車場の周り、それからコンビニ関係のところ、ですから、プロポーザルをやっていくときに、その辺のところの人間の動きですね、住まわれている方と第三者で来られる方、それから設備関係、その辺について含んでどのぐらいかというのをお聞かせいただければと思います。","respondent":"大串住宅担当課長","answer":"今、例を挙げていただいようにいろいろな施設が入り組んでいるといったところで、なかなか管理が難しい面はあろうかと思いますが、当然そこに住んでいらっしゃる方の安全安心、こういったものも担保していかなければならないといったところで、その辺の安全管理のやり方。","voiceIndex":149,"id":"exchange-062"},{"speaker":"原委員","kind":"質問・要望","question":"今ご説明いただいたように、非常に施設的には広くて、意外と夜なんかはちょっと怖いなという、女性とか小さい子なんかは怖いなという場所なんですけれども、ただ、現況、非常にきれいに保たれているみたいなので、その辺のところももう一歩踏み込んでやっていただければと思います。要望ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-063"},{"speaker":"こんの副委員長","kind":"質問","question":"今のご説明で、いわゆるプロポーザルでこれまで管理をされていた東急コミュニティー、区の窓口として業務管理をしてくださっていた中で、効率的にも区の業務としてよかった点、あるいは、こういった点の問題点があったよというのが何かありましたら、現状、どうでしょうか。","respondent":"大串住宅担当課長","answer":"悪い点というのは、特にはあれですけれども、現状を申し上げれば、やっぱり滞納等々が増えてまいりましたので、その辺の対応ということでは、改善の余地といいますか、交渉していただける部分があるのかなというふうには考えておるところです。","voiceIndex":152,"id":"exchange-064"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"それが１点。滞納だけではなくて。こうしたことも一切合切この管理をされている会社が窓口となって対応していただくことと理解しているんですが、そこら辺の対応、区はどのように要望していくのかというか、どこまでを管理をきちんと、また対応していただくような考え方を持っていらっしゃるのか。居住者同士の問題だけではなく、いわゆる施設としてのあり方も絡む中で、そこら辺はどうお考えでしょうか。","respondent":"大串住宅担当課長","answer":"入居者同士のトラブル、これはさまざまあります。正直申し上げて、なかなかそれに１００％対応できるかどうかというのは非常に難しいことだと考えています。これは特に住宅の居住者の問題だけではないと考えています。","voiceIndex":154,"id":"exchange-065"},{"speaker":"こんの副委員長","kind":"確認","question":"当然専門家の方を起用するわけですので、それはそうなんですけれども、でも、お任せし放しということはちょっとあれかもしれないですけれども、そうじゃないと理解しておりますけれども、でもやはり、専門家だけれども、区としてはやはり、最終的には区のスキームをとっていくということを考えると、そこら辺、専門家ですが。","respondent":"大串住宅担当課長","answer":"当然、区の住宅です。設置者は我々ですので、そういったトラブル等々全てを指定管理者に押しつけるということは考えてございません。トラブルについては、こちらのほうで責任持って対応していきます。","voiceIndex":156,"id":"exchange-066"},{"speaker":"こんの副委員長","kind":"意見","question":"ぜひいろいろなお声があって対応は大変かというふうに思います。そのご苦労は重々理解しているところでありますが、どうぞ管理者の選定に際しては、そういったところも一つ視点を置いていただいてお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":158,"id":"exchange-067"}]},{"id":"topic-05","title":"武蔵小山駅周辺地区のまちづくり","agenda":"武蔵小山駅周辺地区のまちづくり","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"課長も係長もご参加していらしたんですけれども、まずその辺、どういうふうに受けとめていらっしゃるのかなというところをお伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"そういった中で今回の説明会ですが、私どもとしては、質問に対してしっかり再開発準備組合は誠意を持って答えていたというふうに感想を持っています。","voiceIndex":163,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"提案","question":"実際的に今回の駅周辺地区まちづくりの今回の提案のところは、パルムの駅前の去年説明があった６４０戸に、今度新たに戸数は４１０戸加わっていく、そのほかにも第三、第四、第五の準備組合の計画があるということでは、駅周辺を皮切りにして、開発計画がどんどん進められようとしていること、問題、その辺で地域全体がどうなっていくのかということと、あともう一つ出されたのは、工事中の問題。","respondent":"溝口都市開発課長","answer":"風につきましては、今後もいろいろ事業計画、実際の建物計画等していく中でも、再度どのような形状にしていけば風環境が従前と変わらない形でできるのか、そういったものは引き続き指導していきたいと考えていますし。","voiceIndex":165,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いつも説明ではこうです。形状を変更すると、変更するんですか、これで行くんですよね。ぜひ風の問題はそう捉えていただきたいなというのを強く求めたいと思います。学校の問題、保育園の問題、あと、地震が起きたときにいろいろな備蓄をしたり、場所を提供しますなんて言っているけれども、地震が起きたときに中にいる方たちが外に出たらどうなるんですかという質問も出ましたよね。いかがでしょうか。","respondent":"溝口都市開発課長","answer":"今後、再開発の準備組合ですと権利変換、そういった事業が進むにつれて、具体的な建物が詳細なものが決まっていきます。そういった中でさらなる対応ができるもの、また、対応が必要なものであれば、それはしっかり指導していきたいというふうに考えております。","voiceIndex":169,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問","question":"起こってからでは遅いんです。事前に、例えば人口増がどのくらい、自動車がどのくらい増える、学校のインフラに対してどの程度の対応ができているのかと数字が出ているのでしょうか。それが１点、特に強調したい点です。そういった意味で、区の立場は、今後、地権者としてなっていくのでしょうか。区の立場がどういうふうになるのか教えてください。","respondent":"溝口都市開発課長","answer":"すみません、具体的な数字は、あくまでも現段階では準備組合のほうでいろいろ検討している段階でありますので、この場で好評できるような数字は私どもは持っておりません。","voiceIndex":171,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"数字はまだ公表できないということですよね。いつになったら公表できるのでしょうか。ぜひそういうのが、いつ出るんですか、しっかり出していただきたいというのと、やはり区へ、この間の説明会も、事業者に説明を求める部分もあるけれども、半分以上は行政が本来質問を受けて答えなくてはいけない中身だったんですよ。私はぜひ今の時点で区の説明会を行うべきであると思うんですが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"区といたしましては、今後、都市計画手続に合わせまして、まずは関係権利者への説明、その後、広く一般に都市計画という切り口で当事業についてはしっかり説明会等をもちながら事業を進めていきたいというふうに考えているものです。","voiceIndex":173,"id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まだ組合が設立されないと事業計画がきちっと立たないので総事業費が出ない、税金投入の額も決まらないということでしたけれども、ぜひ、税金が入る問題なので、そこの地権者だけの問題ではありません。いつもいつも求めていますが、行政側の説明会を固まってからではなく、ちゃんと形成途上においてもきちんと説明をすべきであると思いますので、それを求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-073"}]},{"id":"topic-06","title":"廃棄物処理手数料改定の周知","agenda":"廃棄物処理手数料改定の周知","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"確認に加えて質問しますけれども、これはいわゆる現行料金から新料金への移行は、２３区一緒だということでいいですか。","respondent":"小林品川区清掃事務所長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-074"},{"speaker":"伊藤委員","kind":"質問","question":"それがなぜか２３区は一緒になっているんだけれども、しようがない話なのかもしれないけれども、例えば品川区だけがこの金額を変えていくとか、そんなことはまず可能なのでしょうかというのが１点と、それから、前高橋区長がおっしゃっていたのが、こういうふうなことをもっとばらばらにして解体していってコストを下げていったほうがいいんじゃないかということをお話ししていたと思うんだけれども。","respondent":"小林品川区清掃事務所長","answer":"これは平成１２年の移管当時から、移管までは東京都として一体の処理をしてきた、これを引き継ぎつつ、ご指摘のとおり、方向性としては各区の状況に応じて、それぞれ事業内容、料金も含めて対応していくべきものというふうに考えております。","voiceIndex":184,"id":"exchange-075"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今の説明を聞いて思い出しました。それも一部理解はできるんだけれども、なぜなのかなと思います。だけれども、これから私たちとしては、そういう品川区であってほしいと思うわけであって、共通の部分と、それから原価計算をして、あくまでコストが比較的回収できるのであれば、現状のままの処理金額で行くとか、そういう柔軟な発想をしていっていただきたいと思うんですが、いかがでしょうか。","respondent":"小林品川区清掃事務所長","answer":"基本的なスタンスは、今ご指摘のとおりの考え方に立って、日ごろの収集運搬等についても、コスト意識を持って、区民のサービスを支える事業、経費を削減していく点も含めて、より効率的な事業に努めてまいりたいと考えております。","voiceIndex":186,"id":"exchange-076"}]},{"id":"topic-07","title":"の３の所管事務調査","agenda":"の３の所管事務調査","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"所管事務調査として提案しますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":192,"id":"exchange-077"},{"speaker":"こんの副委員長","kind":"提案","question":"私どものほうからは、３点出させていただきました。１点目が、空き家対策について。２点目に、大井町駅周辺のまちづくりについてということで、新品川区まちづくりマスタープランが策定されておりますので、その中で特に大井町駅の、今日もありました駐輪場の問題等々もありますので、その辺をという問題意識を持っております。この３点を提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":193,"id":"exchange-078"},{"speaker":"木村委員","kind":"意見","question":"私たちの会派は、空き家対策について。この空き家対策は、防犯、防災、それから環境等についていろいろ調査をしていこうということです。それからあとは、補助２９号線、山手通りから環七まで通る道路ということで、こちらのほうも整備についていろいろ調査をしようと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":194,"id":"exchange-079"},{"speaker":"西本委員","kind":"提案","question":"もう一つは、マスタープランができましたので、それぞれの地域を踏まえ、上とはかぶってしまうかもしれないんですけれども、まちづくりという視点から調査研究をしていく必要があるのではないかということで、二つ提案をさせていただきました。","respondent":"あべ委員長","answer":"それぞれご説明ありがとうございました。この件について、何かご意見がございましたら、お願いいたします。","voiceIndex":195,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"教えていただきたいんですけれども、公明党と民・改のほうで、空き家対策、これは、すみません、私の認識不足かもしれないんですけれども、やはりかなり問題点が多いというふうな認識をお持ちでここに出されたということなんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-081"},{"speaker":"こんの副委員長","kind":"提案","question":"うちからの提案の考え方というのが、いわゆる戸建ての空き家です。店舗というよりは、いわゆる老朽している、いわゆる空き家になっている一軒家というか、集合住宅の空き家ということではなくて、やはり防犯、防災といった観点で非常に町に点在する空き家が多く、目立ちますし、木密地域の中にもそういった問題が出てきます。そういうような認識です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":198,"id":"exchange-082"},{"speaker":"木村委員","kind":"意見","question":"私たちも大体同じです。そういう感じで、いろいろと老朽化していくそういう木造住宅密集地域での空き家、だんだん多くなってきているという中で、やっぱり首都直下型の地震が起きた場合のこととか、いろいろなことを、防犯のこともありますけれども、そういうところが悪の住み家になるようなこともあるということもいろいろ考えて、そういうことを調査してみたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":199,"id":"exchange-083"},{"speaker":"西本委員","kind":"意見","question":"木密地域不燃化という形ですると、何か全部入ってしまうかななんていう感じがあるんですけれども、一つちょっと心配というか、空き家になってしまっているところの保管というか、どういう考え方で進めていったらいいのかな、それを調査研究するというのが役割なのだけれども、なかなか進まない、要は、民地、民家なので、それを行政側がどこまで整理できるものなのかなということと……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-084"},{"speaker":"大沢委員","kind":"意見","question":"まさに今、除却のための云々という話で、これ、木密不燃化１０年プロジェクト、まさにこの除却のために必要な空き家対策ということなので、ここの部分もちょっと含みおきをしながらこの話を煮詰めていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":203,"id":"exchange-085"},{"speaker":"伊藤委員","kind":"提案","question":"自民党が提案させていただいたとおり、１０年プロジェクトに関する中でのさまざまな派生するものがあるわけでしょうから、それを総合的に当委員会で所管事務調査していくことは、今お話があった空き家対策も含めてでしょうし、いろいろな派生が出てくると思われますので、それは正副委員長にし切っていただいて結構なんですけれども、不燃化１０年プロジェクトの中で対処していっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-086"},{"speaker":"西本委員","kind":"意見","question":"木密、空き家についてもその中で話をすればできないものではないかなと思っていて、あと、民・改の補助２９号線については、まさにその中に入っていますので、ちょっとかぶっていないなと思うのが、公明党の大井町駅周辺地区のというのと、私どもが出したまちづくりマスタープランという形がちょっと違う項目になるかなということなので、別に私どもとしては、集中してまとめたいというのであれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":205,"id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２の主な取組みと支援策のところで、旧同潤会地区のところが補助金の条件の引き上げで１億円が３倍にもなっているわけなんですが、この辺の内容がどういう中身でどう変わるのかというのが一つと、実際的にこの同潤会のところのどんな建物か、図面がもう引けているのかどうか、どのくらいの階高のものが建つのか、総事業費がどのくらいなのか、そこの中身をひとつ教えていただきたいのと、あと。","respondent":"品川木密整備担当課長","answer":"アパートですと、おおむね２００平方メートルか３００平方メートルぐらいになるかと思いますが、こちらのアパートについても除却支援の対象となります。","voiceIndex":211,"id":"exchange-088"},{"speaker":"飯沼委員","kind":"意見","question":"地域ごとに変化があるのかというあたりと、同潤会のところは、多分、第一種の低専地域と受けとめているんですが、この辺にも高い建物が建てられるようになるのかどうか、その点と、あと、４町会のところなんですけれども、地権者の皆さんの合意とかがどのくらい進んでいるのかという点と、あと、合計の全体のプロジェクト、この地域の４町会のところの合計の予算がどの程度かわかっているのか、その辺を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":213,"id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"そこの、これはもう本気でやるんですよというようなところがどこまで伝わるかによって、それがちゃんと伝われば、迷っている方はもちろんかなりの動きが出てくるでしょうし、でも、反対と言ったときの最後のところの強制力というんですか、そこもある程度打ち出していかないと、その力がどこまであるかわかりませんけれども、ある程度、東京都も含めて品川区の意気込みを。","respondent":"品川木密整備担当課長","answer":"これに向かって、やはり区としてもしっかりやっていきたいというふうに考えております。本日説明しました支援内容をしっかり周知していきながら、この目標に向かって進んでいきたいというふうに考えております。","voiceIndex":217,"id":"exchange-090"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひお願いいたします。やはりこっちがいかに本気になるかによって、相手側も本気になるかということになりますので、きっちりとそれは伝えていただいて、また、そもそもなぜこういうふうなプロジェクトができてきたのかというところを根底から、もうわかっているだろうという段階ではなくて、１から全部しっかりと理解していただくように配慮していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":219,"id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問","question":"今後のスケジュールのところなんですけれども、７月から８月に向けて地元町会への説明とありますけれども、地域は町会の一部だったりもしますよね。そういった面で、町会挙げて説明ができるような、町会ごとの説明会というのが大事かと思うんですけれども、その辺の考えはいかがですか。","respondent":"品川木密整備担当課長","answer":"この説明につきましては、町会等といろいろ話し合って、どのような形でやっていくかというところは、今後考えていきたいというふうに思います。","voiceIndex":220,"id":"exchange-092"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4076#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":67119,"voices":223}},{"id":"h25-20130701-9","meetingId":"h25-cm07","date":"2013年7月1日","dateIso":"2013-07-01","committee":"文教委員会","time":"午前１０時００分～午後 ２時０８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第４７号議案、品川区子ども・子育て会議条例","agenda":"の第４７号議案、品川区子ども・子育て会議条例","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"一つ確認というか、お聞きしたいのですけれども、委員を選出するということで２０名以内ということで、その中に保護者の代表という方も入っているというご説明がございましたけれども、会議の日程を、どういう曜日、時間帯にするかにもよるかと思うのですが、実際に働いている共働き世帯の、今現在お子様を預けているという当事者がなかなか参加しづらい時間帯、日程とかですと。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区子ども・子育て会議の委員選出のご質問です。委員は次世代育成支援対策推進協議会のメンバーに加えて、区内に住所を有する保護者、例えば区立、私立の幼稚園利用者の方々なども考えております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"この会議体が充実されることを願います。その辺の兼ね合いというのですか、委員によってはやはり再任を希望されることが想定されるのですが、その辺のイメージというかシミュレーションをお聞かせください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"一方、こちらの任期は２年と考えまして、逆に言いますと、子ども・子育て支援事業計画を今回の委員には策定していただき、次世代のほうの任期も法定では平成２７年３月までとされていることから、あわせて委嘱するために、支援事業計画の確定と次世代の後期計画をあわせて。","voiceIndex":9,"id":"exchange-002"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですが、この委員の２０名以内というところに委員の公募があると思うのですが、何人ぐらいの割合というか、例えば保護者の方がどのぐらい、学識経験者の方がどのぐらいという数字がもし既にあれば、教えていただきたいと思うのですが。","respondent":"今井制度改革・待機児童対策担当課長","answer":"次世代委員と同じように、学識経験者や、民生委員なども含めました子ども・子育て支援に関する事業に従事する者、そして区内に居住する保護者ということで考えております。それとともに今後、区民委員は子育て中の方から３名公募するというふうに、今、検討しております。","voiceIndex":11,"id":"exchange-003"},{"speaker":"大倉委員","kind":"意見","question":"では残りの１７名ぐらいの方は、こちらの保護者や学識経験者から選ぶということで、わかりました。有識者などいろいろな人の前で話すというのは難しいのかなと思いますので、そういった公募した方が話しやすい環境づくりというのもできればお願いしたいと思うのですが、何かそういったことでお考えがあれば。","respondent":"今井制度改革・待機児童対策担当課長","answer":"公募委員の方につきましては、公募をして選考させていただいた後に、子ども・子育て支援制度に関するご説明を、私どもで一回さしあげてから、この会議に参画していただくように考えております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"南委員","kind":"意見","question":"品川区として委員会の公開を前提として設置をしていくという区側の姿勢が、私は大事ではないかと思うのですけれども、その辺についての考え方と、この会議を開催した後に、やはりこれからの保育の内容とか量とか、そういうもの全てにかかわってくる問題を議論する場ですので、関係者が入っているからそれでいいということではなくて。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そして保育・教育施策の今後の取り組みということですが、先ほどもご説明しました所掌事務の中に、子ども・子育て支援事業計画の策定と、そして推進、評価、こちらがこの会議で行われるように法で定められておりますので。","voiceIndex":15,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"今の最後のところの、支援計画と事業の推進で意見を聞きたいというふうにおっしゃっていたのですけれど、私はこのさまざまな関係者、２０人の方々にとどめずに、必要な場面で必要な区民等々の意見をできるだけたくさん聴取して、区民の要望がどういうところにあるのかというのをしっかりつかんで、この会議の中で議論することが大事なのではないかと思ったので、先ほどそういうふうに聞いたのですけれど。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そしてこの子ども・子育て会議に公募区民を入れていく、そのほかにも保護者を入れていく、そして計画案ができた際には、来年の秋ごろになりますけれども計画案に対するパブリックコメントを実施して、広く区民の意見を伺ってまいりたいと考えています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"意向調査がどういう中身か、今は全然定かでないのであれですけれど、私はぜひ適切な時期に、できるだけ多くの意向を聞いていくということが大事なのではないかと思いますので、どの程度の量の意向調査を考えておられるのかわからないですけれども、できるだけ区民の方々の意見をたくさん聴取していただける、そういう会議体に設定していただきたいということを強く求めておきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"保育所の希望はあくまでもご本人のご意思ですので、今後子ども・子育て支援制度におきましても認可保育所、幼稚園、先ほど申しましたように認定こども園は施設型給付となる一方、同じように公的な仕組みとして地域型保育給付の中に家庭的保育事業などが位置づけられてまいります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"南委員","kind":"確認","question":"いかがでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現在でも入所の第６希望までのところで、認可保育園、家庭的保育事業ということでご本人の希望に合わせて記載していただきまして、その順序に従いまして私ども内定やご相談など、お話をしています。その現行のシステムは変わりません。","voiceIndex":21,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"確かにそうだけれども、さっき言ったように需要と供給との関係で６番目まで書いていただく、できるだけ希望に添えるように、希望をつかみたいということでそういう対策をとっていただいているのはよくわかるのです。そういう方々は翌年転園希望、公立の認可保育園のほうに入りたいという希望は、出せるのですかということです。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現行のとおり、もちろん出していただけます。","voiceIndex":23,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"最後に財政的なところを聞きたいのですけれども、この子ども・子育て会議というのは、品川区としては、設置義務ではなくて努力義務というところで、区長が設置を選択されたということで条例になってきているわけですけれども、これからの保育所運営についての国からのさまざまな補助金、今まで出ていた補助金というのは担保されて、これからもずっと変わらずにあるのかという。","respondent":"今井制度改革・待機児童対策担当課長","answer":"それとともに今ご説明しましたように家庭的保育事業なども地域型保育給付として位置づけられて、この制度の中で、補助金または事業への補助という形で行われてまいります。","voiceIndex":25,"id":"exchange-010"},{"speaker":"高橋委員","kind":"質問","question":"支援計画の条例だとか公的給付の条例、あるいは先ほどあった保育ママ、そういう特定施設の条例とか、新認定こども園の条例とか、そういうもののスケジュールというか大きな流れというか、会議をしながら平成２７年４月を想定してそういった条例もつくっていかないと、間に合わないのではないかと思うのですけれど、その辺の大まかなスケジュール的なところはどうなっているのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"先ほどご説明しました国の子ども・子育て会議は４月から始まってありますが、そこの目標では、区にかかわる部分ですと、例えば地域型保育事業の認可基準ですとか、今年度内には政省令を提示する予定というふうに聞いておりますので、今年度につきましては。","voiceIndex":27,"id":"exchange-011"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、国のほうの平成２７年度に向けてというのがあるのですけれど、区も平成２７年度ということですけれど、例えばもう準備、あるいは現在、社会福祉法人や学校法人が新認定こども園を一刻も早く進めていきたいというふうに思った場合には、やはりそういった条例ができた後に区のほうに申請して、という形になっていくのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"区としましては、この認定基準について並行して確認をしながら、例えば秋には次の年の入園を区民の方にお示しすることになりますので、その前に幼稚園、保育園などの事業所の認定、確認の作業も含めて取り組めるように、準備を進めております。","voiceIndex":29,"id":"exchange-012"},{"speaker":"高橋委員","kind":"質問","question":"ということは、今まさにお話があったように、秋にはということですから、平成２７年４月にやるということは平成２６年度の秋には固まって、希望する方ができるような体制をとっていくという認識でよろしいでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"国の平成２７年４月の本格施行、早ければとなっておりますので、その制度の実施に合わせて考えますと、今はそのスケジュールで想定しております。","voiceIndex":31,"id":"exchange-013"}]},{"id":"topic-02","title":"の第５０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"の第５０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"現実的に公務災害に遭われた校医等は、過去も含めてどのぐらいいらっしゃったのか、参考までに伺いたいと思います。","respondent":"和氣学務課長","answer":"この制度ができまして以降、東京都全体で、昭和３７年からあるのですが、それ以降で６件あったそうです。品川区は条例を平成１４年につくってから、１件もございません。","voiceIndex":45,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですが、この公務災害の想定というのは具体的にどういったものを想定しているのか、ちょっとイメージが湧かないので教えていただければと思います。","respondent":"和氣学務課長","answer":"一番想定できますのは、学校に向かう途中の通勤災害といいますか、この場合が考えられるところです。もう一つは、例えば子どもとの関係でかみつかれてしまったとか、もしくは学校で転んでけがをしてしまったとか、そのような形になると思います。","voiceIndex":47,"id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"ちょっと教えていただきたいのですけれども、何か毎年金額が変わって、都の変更に応じて変わるということなので、区としてはそれに倣うということなのでしょうけれども、率直に何で毎年ちょこちょこ変わるのか。どこかに連動して自動的に変わる仕組みとかになっているのでしょうか。なぜ、毎年こういう条例変更をしなければいけないのかというところを教えてください。","respondent":"和氣学務課長","answer":"主に変わる理由としましては、都の給与条例、医療職給料表の改定で、それぞれ医師の給料が変わってまいります。","voiceIndex":49,"id":"exchange-016"}]},{"id":"topic-03","title":"第４５号議案 平成２５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第４５号議案 平成２５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"単価が引き上がって賃金が増えるということですから、非常にいいことだと思って受けとめました。そしてこの歳入部分を見ると、教育費に該当する項目がちょっとないので、繰越金というところから出るのかなと思ったのですけれど、そのあたり、歳入については後から国から来るのか、何が財源で、どういうふうになってくるのか教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"その単価が幾らから幾らになったか、これはお話しできませんので、答弁は控えします。それから今回は補正ですので、この金額は一般財源、区の持ち出しになりまして、この金額については国から補助あるいは助成がつくということはございません。","voiceIndex":63,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"だから、歳入としてはこの繰越金のところになるのかなとちょっと思ったのですけれども、そのあたりがよくわからないのでもう一度、いつの時期に、どこからどういうふうにというのを教えてください。だけれども、一般的に言って１５.８％というのがどのぐらいの引き上げ額になるのか、概要でいいので金額的なものがわかるような説明をしていただきたいというのがあるのです。","respondent":"齋藤庶務課長","answer":"もう一点、幾らが幾らになるかというのはなかなか説明が難しいのですけれど、一例を申し上げられるのは経理課の担当者でなければお答えできませんので、文教委員会でのご答弁は差し控えします。ひるがえっていうと労務単価ですので、工事によって違います。","voiceIndex":65,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"正確な数字でなくていいですから、大体数千円、２,０００円、３,０００円のアップだとか、そういう概括的な状況で結構ですから、教えていただきたいと思います。","respondent":"田村教育次長","answer":"ですから私たちが知っているのは、いろいろな工事費の中で飲み込める金額でなかったので、足が出た分を、当初予算で飲み込めない部分を、今回補正予算でというお話をしたので、先ほど庶務課長がかなり踏み込んだ説明をしていたので。","voiceIndex":67,"id":"exchange-019"},{"speaker":"南委員","kind":"提案","question":"これ以上質問するつもりはありませんけれども、しかしこういうふうな補正を組んで提出、提案されてきたわけですから、やはりその辺の情報も持参していただきたかったと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-020"},{"speaker":"本多委員","kind":"質問","question":"例えばいつからのものが対象になるとか、公共工事の区分とか、そういう概要をちょっと教えていただけると、この文教委員会の所管はこれだけ上がるのだとわかると思うので、これは経理に聞くようなそもそも論のところかもしれないのですけれど、その制度のあり方、概要だけちょっとわかる範囲でお知らせいただけないでしょうか。","respondent":"齋藤庶務課長","answer":"それで５月２０日以降の工事については新労務単価で、それ以前のものについては、もう既に設計、積算しておりますので、再度計算をし直して、４月１日にさかのぼって実施をするです。これが時系列の話です。","voiceIndex":70,"id":"exchange-021"},{"speaker":"本多委員","kind":"質問","question":"年度をまたいでのやりとりだと思うので、今回補正が出てくるわけですよね。今後はもうこの進め方では、例えば次の年度の予算を組むときには、もう補正というのはないと考えていいでしょうか。","respondent":"齋藤庶務課長","answer":"東京都から示される財務局の労務単価は、年に４回大きい変更があります。ただ今後につきましては、こういった大幅な労務単価の改定がなければ、今までどおり補正ということはないものと考えております。","voiceIndex":72,"id":"exchange-022"}]},{"id":"topic-04","title":"平成２５年請願第９号、希望するみんなが入れる認可保育園の増設を求める請願","agenda":"平成２５年請願第９号、希望するみんなが入れる認可保育園の増設を求める請願","exchanges":[{"speaker":"南委員","kind":"質問","question":"品川区はこれから長期基本計画の中間見直しをするに当たって、前回資料等々も出してきているということは承知しているのですけれども、改めて今後の出生数の見通しと、女性の就労希望がどの程度推移していくのかという見通し、そのあたりをどういうふうに考えておられるのか、それをまず伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"就労数の見通しについては、特に資料などはお出ししておりません。","voiceIndex":87,"id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"長期基本計画のその資料にはないかもしれないけれども、品川区としてそのあたりはどういうふうに見ているのか聞いたので、全然そういう情報はとっていないということなのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"入所のときのご答弁をさしあげましたとおり、申請者および内定者に対して、常勤またはパート労働の割合はとっておりますけれども、今後の見通し等につきましては、現状のところ、今は手元にデータはございません。","voiceIndex":89,"id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"それと、女性の就労については先ほどデータを持っていないとおっしゃったのですけれど、女性の就労が今後どのようになっていくかというあたりは、どのような見解を持っているか、改めて別の角度から伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そのため品川区でも、短時間型保育室をはじめ、家庭的保育事業などの就労要件などを緩和いたしまして、多様な就労形態に対応するように努めているところです。","voiceIndex":91,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"就労については、女性の就労希望があるというご認識を持っておられるということはわかりました。それで、この請願では二つ項目があって、一つ目は認可保育園を増やしてくださいというご要望なわけですから、改めてそのあたりについて品川区への要求との関係で、見解を伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"１点目の請願項目、認可保育園にかかわるご質問です。品川区も今般、予算プレス等でも既にお話ししていますとおり、認可保育園の開設も含め、認証保育所あるいは家庭的保育事業など、さまざまな対策を総合的にとる中で、待機児童解消をしていきたいと考えております。","voiceIndex":93,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"ただ、この要求との関係で、認可保育園を増やしてくださいというのが要求だし、これは今、とりわけ今年度の保育園の入所については、品川区に限らず２３区の結構多くのところで、他の自治体でもそうですけれども、認可保育園をつくってほしいと、そこに入れてほしいというのが社会現象となって、あっちでもこっちでも声が上がったではないですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"認可保育園につきましては、その位置づけ、認可というところで十分理解はしております。ただ品川区は、認可保育園だけではなく、さまざまな施設もあわせて整備することで、区民のニーズに応えていきたいというふうに考えております。","voiceIndex":95,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"私が聞いたのはそういうことではないのです。だけれど区民の要望との関係で、認可保育所をつくってほしい、認可保育所に入りたいけれども入れない、だからつくってほしいと、こういう要求が品川区にもあるけれども、他の自治体でもあると。だから今のご答弁は何回繰り返されても、私の聞きたいこととは違いますので、私はぜひ答えていただきたいと思います。","respondent":"金子子ども未来事業部長","answer":"これに対してどう対応していくかというのは、これはもう何年も前から申し上げているとおり、品川区の方針として認可保育園、認証保育所等々、先ほど制度改革・待機児童対策担当課長も申し上げたとおり、総合的な対策でこれについては答えていきたいというのが、区の方針です。","voiceIndex":101,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"部長も含めて、私の質問している趣旨をやはりしっかり受けとめていただきたいと思うのです。今のご答弁も全然私の答えにはなっていないですよ。私は認可保育園という要求が区民の中にいっぱいあるというふうに、考えているのかどうかということを聞いたのです。答弁ではないですよ。お答えできないのであれば、認可保育園という要求は、区民の中にあるというふうに思っていないということですか。","respondent":"金子子ども未来事業部長","answer":"委員はあくまでも認可保育園にこだわった質問をされておりますけれども、私どもとしましては、保育の希望に対しては総合的に対応していくというのが区の方針であるというふうにお答えしているので、質問にお答えしていないということはないと考えています。","voiceIndex":103,"id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"この請願を審査するに当たって、先ほども申し上げましたけれども、お出しになったこの女性の団体の方は、１項目と２項目を出されていて、そのトップに認可保育園を増やしてくださいという項目を挙げているわけです、はっきりと。それを、総合的な対策だと。認可保育園をどういうふうに捉えているかということを聞いているのです。ちゃんとご答弁をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"乳幼児人口に対しての保育園の申請は高まっているというご答弁で、認可保育園に対する区民要望はあるというふうに聞いていいのでしょうか。理解していいですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"申込みは一定の割合あるということで、ご理解いただければと思います。","voiceIndex":109,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"その申込みについて、申請が高まってきている、年度を追って高まってきているという事実は、やはり申請をされるときに最初から認定保育園でいいですとか、保育ママでいいですとか、そういう申請がどのぐらいあるのか、あるいは認可保育園に希望される方々がどのぐらいあるのか、その具体的数字、あるいは割合がわかったら教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現在、平成２５年４月におきましては、人口比の申し込みの割合率は１１.３％程度です。昨年平成２４年度は１０.９％でございました。平成２３年度は１０.３％でしたので、０歳から５歳の乳幼児人口に対する申込者の割合は高まっているところです。","voiceIndex":111,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"その窓口に来られた方々が、どういう保育園を選んでいきたいというふうに申請しているのか、具体的な状況を教えてくださいと質問したのです。大ざっぱに分けて、保育ママあるいは認証保育所、認可保育園、こういう分野で見たときに、それぞれどのぐらいの割合で、窓口へ申請している数字があるのですかということを聞いたのです。具体的に教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"認可と家庭的保育事業につきましては、一緒に申し込みをされております。平成２５年度の認可保育園の申込率は、在園率ということでしか把握しておりませんので、委員のご希望の数値ではないと思います。申しわけありません。","voiceIndex":113,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"申請数というのはわからないのですか。窓口に全員が来て、必ずそこで窓口の担当の方と相談をした上で、確認した上で申請書を書いて出すはずですよね。だからわからないということは、私はあり得ないと思うのですけれど。そういうカウントはしていないのですか。そこも含めて数字を教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"大変申しわけありませんが、現在手持ちで持っている申込者割合の、先ほど申し上げました数字の割合については、認可の方で申し込んでいる割合というふうな数字しか持っていませんので、手持ちの資料にはございません。","voiceIndex":115,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"したがってそういう資料等々を、できたら用意していただきたかったわけですけれども、先ほど書記に読んでいただいたこの請願文書について、何も説明することはないとおっしゃった、そしていろいろ質問してもそれに応えていただけるだけのデータを伺えなかったという点については、私はもう少しきちんと質疑ができるように、必要な書類は準備していただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-035"},{"speaker":"本多委員","kind":"意見","question":"私もそのとおりでいいと思うのです。それで聞きたいのは、この請願の２番目の認可外保育施設を認可に引き上げる支援ということなのですけれども、これをもし区がやるとした場合、費用はどのぐらいかかるのか、おそらく莫大な金額がかかるかと思うのですが、参考にもしわかれば、概要で結構です。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただ、今回のご質問の内容は認可外保育施設ですので、いわゆるベビーホテルから、既に東京都の認証になっております認証保育所までさまざまにありますので、一概にゼロベースからつくるのか、全く移転してつくるのかによりまして。","voiceIndex":118,"id":"exchange-036"},{"speaker":"本多委員","kind":"質問・要望","question":"やはり世論が望んでいるのは待機児童ゼロだと思います。その対策を今、区もやっているし、議会からもさまざまな意見を出していただいて、総合的に実施していただいていると思うのですね。世論の主眼というのは、認可が全てではないと思うのです。そのゼロを達成するには、どちらの方法をやったほうが先に達成できるとお思いでしょうか。考えをお聞かせいただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今、待機児童解消加速化プランの中では、２年後の子ども・子育て支援制度を見越しまして、特に認証保育所を含めた認可外の部分も合わせて、認証保育所や認可外への支援だけではなくて、例えば事業所内保育所ですとか、小規模保育。","voiceIndex":120,"id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"私は先ほどの質疑も含めて、やはり区民の方々は認可保育園を一番希望しているというふうに思うわけです。とりわけ少子化の中でそういう傾向がずっとある中で、しかし女性の就労が広がっていくという社会的な背景の中では、できるだけそういう要望に応えられるような条件整備を、自治体だからこそしていく必要があると思っているのです。それは要望として、意見として申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-038"},{"speaker":"本多委員","kind":"質問・要望","question":"結論を出していただきたいと思います。態度につきましては、願意に添えないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-039"},{"speaker":"塚本委員","kind":"意見","question":"考え方にしても、認可にあらずんば保育にあらずというような、そういった考え方というのは、この多様化してくる社会の中ではあまりそぐわなくて、やはりいろいろな保育の形があって、それぞれがそれぞれの子育てにおいていろいろな意味があって、親御さんたちがそれぞれ自分たちの保育のニーズに合った形で、いろいろな形を選んでいけるというような保育の形が今後必要になってくると思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":126,"id":"exchange-040"},{"speaker":"大倉委員","kind":"質問・要望","question":"態度としては、今、さまざまなお話がある中で、品川区としても多様な保育ニーズがある中で、待機児童ゼロを目指して、ここ数年で保育園の数を増やしているというお話も伺いました。しかし一方で、認可保育園を増やしてほしいというご要望があるというのも、確かに現実的にはあるということで、趣旨としては非常によくわかりますが、実現性等々見まして、趣旨採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-041"},{"speaker":"南委員","kind":"意見","question":"私は採択をしたいと思います。ほかの委員の皆さんにもぜひ採択をしていただけるように、お願いしたいと思います。理由は先ほども申し上げましたけれども、やはり区民の圧倒的な願いは認可保育園なのです。その認可保育園というのは、先ほども言ったように設備的にも人員配置的にも、圧倒的に違うわけです。したがって、ぜひ採択していただけるように改めてお願いしたいと思うし、採択を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-042"},{"speaker":"高橋委員","kind":"質問・要望","question":"理由は、いろいろ議論はありましたけれども、やはりスピード性があり、即効性のある施策で、まずはゼロを目指していく中で、説明にもありましたけれども認可保育園の増設、定員のための規制弾力的な扱いですか、そういうものを柱にしながら、それぞれスピードと即効性に向けてさまざまな方策を打っていただきたいという観点から、さらに新制度が施行されていきますので、その中でもいわゆる待機児ゼロを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-043"}]},{"id":"topic-05","title":"平成２５年陳情第９号、「子宮頸がんワクチン接種事業の見直しと、健全な教育を求める」陳情","agenda":"平成２５年陳情第９号、「子宮頸がんワクチン接種事業の見直しと、健全な教育を求める」陳情","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"この陳情は、大きく分けて子宮頸がんワクチンの接種そのものに対するものと、健全な教育を求めるというようなことと、二つだと思うのですね。その辺時間的に、ちょっとお答えづらいことを聞いてしまうのですが、じっくり考えるのにどのぐらいの時間が必要とお思いになられるか。非常にお答えづらいかもしれないのですが、いかがでしょうか。","respondent":"伊津野保健予防課長","answer":"国のほうで今、この秋から全国１６の大学病院を中心とした拠点病院で、今回問題になっております痛みが持続的に続くような病気を集約しまして、その頻度とかを調査して検討していきたいということを示されております。","voiceIndex":140,"id":"exchange-044"},{"speaker":"本多委員","kind":"質問・要望","question":"ちょっとお答えづらい質問ですみません。健全な教育を求めるというところでは、確かに国の定めた指導要領にのっとって、区としてできる範囲、できる限りのことを精いっぱいやっていただきたいと思います。現時点では、非常に慎重に、動向を見守るといいますか、そんな発言をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、今の説明の中で、できるだけ早く症状等々もしっかり集約していただいて、新しい推奨、厚生労働省が強力に推奨するということも含めて、きちんとした情報が提供されて、そういう副作用に対する対応も含めてきちんとした対策がとられることを望むところですけれども、そういう事実が本当かどうか、ひとつ確認したいのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"そういう考え方について見解を改めて聞きたいと思っています。しかし、学校の中で必要に応じてやはり、性教育に限らず自分自身を、自分の健康と自分の意志というものをしっかり持てる教育が大事なわけですから、そういう角度で教育していただくことが大事なので、そういう立場での性教育のあり方も含めて、きちんと律していただきたいということを要望しておきたいと思います。","respondent":"伊津野保健予防課長","answer":"今回の８６０万接種に対して１例のＣＲＰＳが発生したということですが、それ自体が中止の理由でなく、それについての情報提供がきちんとできないということで、ほかにも例がないかとか、因果関係につきましてもまだ不明なので、その辺を時間をかけて注視したいと。","voiceIndex":147,"id":"exchange-047"},{"speaker":"南委員","kind":"意見","question":"予防するということと、検診は検診でしっかりと受けていくということが、健康を守り感染しない、そういう衛生観念といいましょうか、健康感覚というか、そういうものを身につけていくことになると思いますので、検診を受けるということを抜かして、ただ予防接種を受ければいいのだよということではないと思いますので、そのことについても改めて、意見として申し上げておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":149,"id":"exchange-048"},{"speaker":"塚本委員","kind":"確認","question":"少し事実関係をお伺いしたいと思います。これは確認なのですけれども、まずこの子宮頸がんワクチンは、中学１年生が接種の時期ということになっていますけれども、この時期に打つということの意味、効果、これについて一つ確認したいと思います。その辺についてお伺いしたいと思います。","respondent":"伊津野保健予防課長、和氣学務課長","answer":"接種年齢につきましては、やはりこの子宮頸がんのウイルスにつきましては性交渉でうつるということで、性交渉が活発になる前の段階ということで、小学校６年から高校１年ぐらいの年代で接種することになっております。一回学校保健会で、家庭に対して性教育と子宮頸がんの話について、講演会を一度だけ持ったことはあります。","voiceIndex":150,"id":"exchange-049"},{"speaker":"塚本委員","kind":"確認","question":"ということは、確認ですけれども、学校教育の中で今回のこの奨励をしないという措置が厚生労働省から出たことによって、特段何かが変わったということはないということでいいのか、あるいは今後何か説明会を、この事態を受けてするという予定があるのかどうか。これについてお願いします。","respondent":"和氣学務課長","answer":"保健所のほうで、広報を通じて今回の厚生労働省の措置についての周知を図るということですが、私どももその保健所の要請もございまして、保健だより等で混乱がないように、積極的な勧奨はしませんと。","voiceIndex":153,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"私は基本的に、そういう陳述は審査をする前に聞くべきだと思っているのですけれども、今回はその点では意見を言わなかったので、遅ればせながら今、発言させていただきたいのですけれど、でも陳情者が陳述したいというお申し出があるのであれば、それは受けとめていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-051"},{"speaker":"本多委員","kind":"質問・要望","question":"こういう陳情とか請願を出されたものは、我々は議会人としてなるべく早く結論を出す努力はしたいと思うのですが、この陳情第９号に限りましては、もう少し時間をいただきたいということで、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-052"},{"speaker":"塚本委員","kind":"意見","question":"私としても、この子宮頸がんワクチン接種の勧奨をしないという判断は最近起きて、それは何が起こっているかわからない、本当の原因がわからない、説明ができないというようなことなので、先ほどの答弁の中でも暫定的な措置が、では今後もとに戻るのか、もっと違う形になるのかということを少し見る時間が、どうしても、陳情の本質が子宮頸がんワクチン接種事業ということになっておりますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-053"},{"speaker":"大倉委員","kind":"意見","question":"この陳情内容の、健全な性教育等々のことも、説明までいただいて非常によくわかってきたのですが、ご心配されているということも。やはり皆様言っているように、今後の国の、まだ今は暫定的な処置ということで、すぐにということではなくて継続をして見守っていくことがいいのかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"私は結論を出していただきたいと思います。態度は、主な訴えは子宮頸がんワクチンの問題というよりも、学校の中での性教育もきちんと取り扱ってほしいということと、性交渉を許容するような誤解を与えかねない、それがワクチンの接種だと、そういうことですよね。それで態度としては、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-055"},{"speaker":"高橋委員","kind":"意見","question":"この陳情の中の学校教育については、現在指導要領にのっとって行われているという実態なのですが、ワクチンの是非ということに関しては、現状を把握するにはまだ数々の調査等いろいろ必要だということがありますので、今日結論を出すのではなくて、継続として、国および関係機関の動向を見る必要があると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-056"},{"speaker":"南委員","kind":"確認","question":"そのあたりのことを一つ確認したいと思います。しかも１８歳で負債を背負うわけですよね。しかし、卒業して、就職も含めて思いどおりにいかなかった、そういう中で返済が滞ってしまっているというケースが大半なのではないかと思うので、そのあたりは区としてはどういうふうに考えてみているのか、ちょっと伺いたいと思います。","respondent":"福島青少年育成課長","answer":"そういった相談が一切ありませんでしたので、この８件につきましては訴えたものです。したがいまして、彼らがどういう状況にあるのか、そういうことについても、こちらとしては一切わかりようがないということもありましたので、やむを得なく行っているというものです。","voiceIndex":171,"id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"それでちょっと聞きました。それと、８人は大半が４０代ということなのですけれども、就労はしているのかどうか、収入がある人たちばかりなのか、その辺の調査というのはどうなっていたのでしょうか。それから家庭状況はどういうことなのか、就労もさっき伺ったのですけれど、家庭状況も含めて、どういうふうになって、どういうふうに情報をつかんだのか、そのあたりを教えていただきたいと思います。","respondent":"福島青少年育成課長","answer":"督促する段階では、何度も何度も返事がないと訴えますよということは毎回、毎年のように言っています。その結果、最終的に１０数回督促をしたということですから、かえって遅かったぐらいではないかというふうに考えているところもあります。","voiceIndex":173,"id":"exchange-058"},{"speaker":"南委員","kind":"質問","question":"そうするとこの８件については、区による督促状と訪問督促等々、もう１０年以上にわたってやっている、全然返事がない、いわゆる悪質だと、そういうふうに認定したということですか。","respondent":"福島青少年育成課長","answer":"実際に８件訴えまして、区のほうに連絡をとってきたりですとか、あるいは即金でお金を支払ったりとか、そういう結果が生まれていますので、別に悪質だからというふうに認定しているとか、認識しているということではございません。","voiceIndex":175,"id":"exchange-059"},{"speaker":"南委員","kind":"質問","question":"それからやはり、この社会全体の不況という経済状況が、個々のケースがわからないですから一概に言えないのかもしれないけれど、でもこのほかにもいっぱいまだあるわけではないですか、この報告の件数を見ると。そういう点では、経済状況もこの背景にはあるのではないかと私は思うので、その点についての見解を最後に伺って、終わりたいと思います。","respondent":"福島青少年育成課長","answer":"必ず返してくださいということは言っています。ただ彼らにつきましては、何しろもう１０数年前に貸したので、そのときの状況がどうだったか、そこまでは把握していませんが、多分そのときもちゃんと返還義務があるのだということは伝えていたと思います。","voiceIndex":177,"id":"exchange-060"},{"speaker":"南委員","kind":"質問","question":"これは、当然だとは思うのですけれど、違約金ということと利息というのは当然つくのですよね。つかないのでしたっけ。つかないのですか。そうすると元本を分割して返済するという、そういうシステムでしたっけ。","respondent":"福島青少年育成課長","answer":"実はそれ以降、６月になりまして和解したものもあるのですけれど、それらにつきましても、全額元本を払っていただければ違約金につきましては免除するというような和解を、今進めているところです。","voiceIndex":179,"id":"exchange-061"},{"speaker":"南委員","kind":"確認","question":"聞きたかったのは、貸付金そのものに対する利息というのはつかなかったのかというのを、ちょっと確認したかったので、そこだけ一点。","respondent":"福島青少年育成課長","answer":"一切ありません。","voiceIndex":181,"id":"exchange-062"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"石田ちひろ議員からの一般質問で、「憲法守りくらしにいかす今すぐ原発ゼロを品川から」のところだと思うのですが、給食費に関する質問で、放射能検査の件があったと思うのですが、それについて質問をさせていただきたいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4794#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":43823,"voices":191}},{"id":"h25-20130701-5","meetingId":"h25-cm07","date":"2013年7月1日","dateIso":"2013-07-01","committee":"総務委員会","time":"午前１０時００分～午前１１時２４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４６号議案、職員の給与に関する条例の一部を改正する条例","agenda":"第４６号議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この施行令が平成２５年４月１３日に施行されたことに伴って今回の条例が出されてきたということなのですが、ということは、これは全国的に同じようにこういう形で各自治体に出されて、同じように決めていくという考え方でいいのかということが１点と、それからあとは、どういう形で派遣されるのかをイメージできるようにご説明いただきたいのですけれども。","respondent":"堀越人事課長、工藤危機管理室長","answer":"それから派遣の話ですけれども、緊急事態宣言が国のほうで発せられた場合に、緊急事態に対応するために必要がある場合には、派遣を受ける側の自治体から派遣を求めまして、国、それからこの公共機関、例えば電気ですとか、ガスですとか。スケジュールとしては、今年度中にと考えているところです。対策本部条例につきましては、今年度、平成２５年１定でご審議いただいて議決いただきましたので、今、もう公布されているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの派遣される公用の施設とその他の施設は、派遣の手当の額も違うのですけれども、そこら辺がどういう施設で、なぜ違うのかというあたりを教えていただきたいのと、それから、この手当は全国一律、同じ額ということでいいのかということと、そうすると、その財源はどういう財源で出てくるのか、国から全面的に出てくると考えていいのか、そこのところについてもお聞かせください。","respondent":"堀越人事課長","answer":"これは、全国一律の形になっておりまして、これは総務大臣から告示をしていますので、その基準に沿った形で各自治体で考えておりますので、全国一律という形でこの金額で定められております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"工事予定価格に対する労務費の割合を工事ごとに教えていただければと思います。それともう一つは、その労務費に対して、今回、変更分ということで記載がされておりますけれども、それぞれ何パーセントぐらい、十、二十％ぐらいだとは思うのですけれども、どのぐらいのアップというのでしょうか、変更されるのかということを教えていただければと思います。","respondent":"平澤経理課長","answer":"２点目の変更の割合からご説明申し上げます。それぞれということになりますが、例えば２ページの改築工事です。２,２５９万６,０００円の増加ということで、１.１％のアップになります。","voiceIndex":22,"id":"exchange-003"},{"speaker":"浅野委員","kind":"質問","question":"労務単価のほうの話に入ってしまいますけれども、前回もいろいろお伺いしたそれ以外の契約関係で変わるものが、今回、いろいろな意味での変更点が出てくるのかなと思うのですけれども、どうかというのは、ある程度もう見えているのか、また、予算措置とかそういうものはどうされるのかをお伺いできればと思います。","respondent":"平澤経理課長、本城企画財政課長","answer":"私から、まず特例分と申しましょうか、４月１日以降で旧労務単価で積算したものにつきましての状況をご説明申し上げます。対象となっていますのが、７５件の工事があります。予算上の措置につきましては、今、経理課長からもご説明がありましたような状況を見きわめて、９月補正以降に補正する分が必要のあるものかどうか見きわめた上で、必要があれば、補正等の対応も含めて検討してまいります。","voiceIndex":24,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"今回、こうやってきちんと賃金に対して労務単価を上げるということならば、その辺の仕分けをきちんとした上で上げる、それが適切だという、今回、区のほうでそういうふうに労務単価のその分を上げて再見積りをして予算措置しているわけですから、その辺についてわかりにくいので、もう１回教えていただけますか。","respondent":"小林施設整備課長","answer":"その場合は、今言ったように材料が幾ら、実際は代価表といいまして、代わるお金ということで複合単価なのですが、そちらのほうの内訳もあるのですけれども、その単価が材工共で決まっておりまして、そこの労務単価だけ抜粋というのが。","voiceIndex":27,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"なぜ複合単価になっているのか、こういうわけでやむを得ずなっているのだというのがわかりにくいのです。もう１回だけ聞いていいですか。すみません。","respondent":"小林施設整備課長","answer":"それを使いますので、では、その労務単価だけは何パーセントとなると、材料のお金を別に拾ってきまして、そこでマイナスしてあげれば、残りが労務単価として出てくるのですけれども、それがかなりの件数がいっぱい出てきていますので、そこまではやっていないということで。","voiceIndex":29,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"わかりましたが、せっかくこういうふうに区できちんと労務単価を改定して、賃上げ分をプラス、再計上して、こちらへお支払いするわけですから、できるだけ正確な、より区民にもわかりやすいような仕組みづくりをしていただけるとありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"これを積算しますよね。そうすると、材工で今、切り離しがなかなか難しいということだと、この業者の方とどういう話をしたのかなと思ってしまうわけです。それが本当に品川区の考え方として反映できているのですか。国は十何パーセント上げますよと言ったものに対して、それは反映できているのですか、材工の問題を解決しないと。そこら辺の整理をどう考えてやっていらっしゃるのかを聞きたい。","respondent":"平澤経理課長","answer":"工費の積算からお話しさせていただかないといけないのかなと思います。私どもで予定価格は計上しています。ただ、各事業者がこの建物を建てるにはどのぐらいの見積もりになるのかは、各事業者が見積もっているものです。","voiceIndex":32,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"現実は、だって材工でこれぐらいあるから、平米数がこれぐらいだから、これぐらいの金額がかかるとか、そういう予定価格のつくり方ではないのかという質問をしたい。そこら辺を考えると、それを切り分ける作業を誰がやるのですか。国が十何パーセントだと言っている、では、区がそれをどうやっているのですか、そこを。新しい労務単価はいいのだけれども、そこら辺の考え方を教えてください。","respondent":"小林施設整備課長","answer":"今、委員がおっしゃった約１８％の労務単価の上がりなのですけれども、それを考えるもとにした単価表をつくってありまして、それが材工共の労務のほうに反映されています。","voiceIndex":34,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"それが、この１８％が基本的には全部下請へ行くわけですから、１８％多く払っているのか。材工でやった何平米の中のだとすると、では、１８％はどこにどういう計算をするの。多分、できない。そうすると、この１８％のせっかく上げたお金が効果的に使われるかどうかは非常に疑問があるのだけれども、ここら辺の後追いというのか、どういうふうにしていくという指導をしているのかどうかを教えてください。","respondent":"中山総務部長","answer":"これは、現実の運営のところについては、おっしゃるとおり個別の確認をするということはありませんけれども、個別の話の中できちんとこの趣旨を反映させて協議を行い、変更契約していくという形になっておりますので。","voiceIndex":36,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の労務単価で、確認はしないということなのですけれども、私は、ぜひ実際に働く方々の労務単価、賃上げがどうなったのかということを、区が調査をしていただきたいと思うのです。","respondent":"中山総務部長","answer":"ただ、当然ながら、きちんと契約を結び、今回については、先ほど申し上げたとおり、きちんとその趣旨を踏まえてやっていただくことを個別協議をしてあえてお願いして、確認をしてくる行為をとっておりますので。","voiceIndex":38,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私は、下請、それから孫請で実際に働く人たちがどういう、公契約の条例ということにもなってくると思うのですけれども、そういうところまで区としてしっかりとつかむことが、今回の本来の趣旨を現実のものとすることにつながってくるのではないかと思いますので、そこの単価は幾ら支払われているのか、区は協議の中でお願いしているので、あとは事業者任せですというのではなくて。","respondent":"平澤経理課長","answer":"したがいまして、その個別の賃金ということに関しますと、それは労使の関係等もありますので、そういった中できちんとした形の整理をしていただく。契約にかかわる約款上の行為がきちんとなされないような場合は、それはそれで個別に粛々と対応していく、こういった考えです。","voiceIndex":40,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区は委託先の労働の実態も賃金の状況も把握しないというところでずっと来ていますけれども、私はそういうところをしっかりと把握することで、責任を持った委託、それからこういう契約になると思いますので、それは今後、ぜひ調査していただくということでご検討をお願いしたいと要望しておきます。","respondent":"小林施設整備課長","answer":"今、その下に、シートパイルという仮設の山どめをやっているのですが、ここにこの崖を背負う擁壁を、今現在、築造しております。この鉄筋コンクリート造の擁壁ができましたら、この崖の部分を安定させるということで、今現在、工事を進めている段階です。","voiceIndex":42,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、もう一つ、この図面で、５ページの下の段で左側の上のところが白い空白になっているのですけれども、もともとここは、今、学校の校舎があるところだと思うのですけれども、ここのところを学校の敷地から外したのは、どういう理由でここが外されたのかということと、あとはここの問題では、この下側の南西に１４３メートル。","respondent":"小林施設整備課長","answer":"１点目の地震の対応で、今、委員がおっしゃったかなりの地震に対応できるかという、その「かなり」というのが、私もよくわからないのですけれども、基本的には、現在、法令で定めている地震等については耐えられるような設計をしております。","voiceIndex":46,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここは文教委員会ではないので、詳しい中身はこの契約のところで聞くのは難しいのかなとは思うのですけれども、ただ、どういう校舎が建つのかというところで、今までのいろいろ文教委員会でのやりとりとか、建設委員会でのやりとりとか、議事録を読ませていただいたところで、不安なところが日影の問題、結局、日影規制を外して４時間の日影をつくるということでずっと答弁されていましたので、それは同様に。","respondent":"小林施設整備課長","answer":"それと、風については、当然、こちらの超高層のほうでも各法律に沿って進めて、それがおりておりますので、問題ないと考えております。","voiceIndex":48,"id":"exchange-015"},{"speaker":"つる副委員長","kind":"質問","question":"労務単価の件で再度お聞きしたいのですが、詳細については先ほど石田委員のほうから質問していただいて、理解したところもあるのですけれども、今回の大きい流れは、公共工事が減少してというところと、あとは短いスパンで見ると、東北の復興関係の工事で入札不調が続いているとか、あとは人材が不足しているという流れの中でこういう大きいお金の流れがそこで自治体にいかなくなっていると思うので。","respondent":"平澤経理課長","answer":"ですので、一つには、皆さんにお集まりいただきまして、こういった趣旨で品川区で設計労務単価引き上げにかかわる特例措置を実施するというお話をさせていただきました。","voiceIndex":50,"id":"exchange-016"},{"speaker":"つる副委員長","kind":"確認","question":"経費の調査等を今後されていく中で、そういう範疇の中で何らかの形でダイレクトにそれ自体をどうこうということだけではなく、品川区だけがどうこうというのではなくて、幅がある形でもいいと思うのですが、そうした形でそれが反映されてきたということを確認調査できる何らかの方法はないのですか。","respondent":"平澤経理課長","answer":"その辺も含めまして、私どもでも、そういったことが品川区でもできるかどうかも含めまして、検討していきたいと考えているところです。","voiceIndex":52,"id":"exchange-017"},{"speaker":"つる副委員長","kind":"質問・要望","question":"いろいろ難しい部分もあると思うのですが、要は、結果として賃金が引き上がり、個人消費も上がっていくという流れが見えてくる形になればいいと思いますので、ぜひそうした投げかけについては、引き続き行っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"だけれども、これについては、最近だから、それも見込んで入札しているのだろうから、そこら辺はちょっとと思うけれども、だから、余り先に入るとなると、では、逆に、今度言うと、これだけ金額が上がっているのだから、もっと面倒見てくださいよとか、材料費だって高騰しているのだから、材料費もそれで区のほうで面倒見てくださいとか、そういう逆の話になりかねないから、余りそれは国が今。","respondent":"中山総務部長","answer":"個別のところについては、現実、難しい。というのは、先ほどもありましたけれども、いろいろな対応について既に、例えば説明会、個別対応だけでなく、ホームページでもこの趣旨をということは周知しております。","voiceIndex":55,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"４議案とも反対です。本来であれば、改築に当たって子どもたちの学ぶ環境を最優先にすべきところですけれども、しかも、開発は品川区が地権者でもあり、また、税金を補助金として２６４億円も投入しているにもかかわらず、開発を優先して学校敷地の真西に１４０ｍの４０階もの超高層のマンションを建てて、その日影を極力少なくするために校舎の位置をずらすというのは本末転倒だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-020"}]},{"id":"topic-02","title":"平成２４年度品川区一般会計予算繰越明許費繰越計算書","agenda":"平成２４年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"これは相手に損害を与えて、車が、一応、壊れたということであれば、修理代とかそういうような形になるのでしょうけれども、それが時価相当額になっている理由を一つ教えていただきたいのと、あと、前にも聞いたことはあると思うのですけれども、庁有車の保険の加入はどういう考え方になっているのかを、この際、教えていただきたい。","respondent":"平澤経理課長","answer":"そういたしますと、１９万５,０００円ほどになります。この時価相当額というのは、本車はちょっと古目の車両でございまして、事故後、相手方が車両の入れ替えというのですか、買い替えを検討されていたです。","voiceIndex":75,"id":"exchange-021"},{"speaker":"浅野委員","kind":"質問","question":"任意保険に加入しているということで、例えば今回の損害賠償額１４万２,２００円と、報告第１６号の８４万６,４１３円は、これは保険で全部賄ったという、そういう意味での損害賠償額ですか。","respondent":"平澤経理課長","answer":"失礼いたしました。委員ご指摘のとおり、保険により補填されるものです。","voiceIndex":77,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1950#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":26001,"voices":83}},{"id":"h25-20130702-6","meetingId":"h25-cm07","date":"2013年7月2日","dateIso":"2013-07-02","committee":"区民委員会","time":"午前１０時００分～午後 １時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の(1)、平成２５年度品川区民まつりの予定","agenda":"の(1)、平成２５年度品川区民まつりの予定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区としてのブースというのはどういう感じになっているのか、どういう考えなのか、ちょっと伺いたいと思います。","respondent":"久保田地域活動課長","answer":"品川区単独で、例えば耐震のブースとか、そういったものについては、私のほうでは、昨年回った中ではそういったブースはたしかあまりなかったと思いますけれども、あとは国際友好協会、国際関係のものとか、協働のものとか、それぞれの目的に応じて地域の方と連携して。","voiceIndex":5,"id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"２点お伺いしたいのですけれども、八潮地区の打ち上げ花火、荏原第五地区の花火教室というものに関しての安全性はどうなのかご存じかということと、それから猛暑だというお話、ちょうど真夏にやるので、熱中症対策など区からの指導みたいなものはあるのか、お聞きします。","respondent":"久保田地域活動課長","answer":"救護所等も本部に設けてございまして、それぞれ例えば看護師でしょうか、地域によってそれぞれありますけれども、そういった医療関係の方も待機していただいたり、また貸し出し用のＡＥＤを持ち込んで、万が一のときには何かあった場合の対応ということもあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問・要望","question":"要望で終わります。安全性は、やはりこういうお祭りに何かあってはいけないので、健康被害があるようなことがないように、十分注意していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"今の花火で、花火の安全性についてはよくわかったのですけれども、ずっと前の話になりますけれども、議会からも品川の花火大会を実施したらどうですかみたいなときの答弁に、花火を打ち上げてしまうと、大井競馬場の馬が何か暴れてしまうなり、怯えてしまうなりするから、あの辺での花火大会というのはできませんという答弁をたしかずっともらっていたと思いますけれども。","respondent":"久保田地域活動課長、米田商業・観光課長","answer":"打ち上げ花火といいましても、職人が来て何か大がかりな仕掛けをしてやっている花火ではなくて、市販のよくご家庭とかでも購入できるような簡単な打ち上げ花火をやってありますので。大井競馬場の花火との関係ですけれども、競馬の競争馬は、前にこちらから議会のほうでもお答えしたように、競走馬というのは非常に神経質、それでなくてもペットとかでも。","voiceIndex":10,"id":"exchange-004"}]},{"id":"topic-02","title":"の(2)、荏原第二区民集会所の休館","agenda":"の(2)、荏原第二区民集会所の休館","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"住民にとっては休館というのは大きな問題ですから、幾つか伺いたいのですけれども、２カ月間は使用できなくなるということですけれども、従来ここを利用していた方々の人数だったり、団体だったり、利用の仕方だったり、それはどういう方々が多くここを使っていたのかということと、この２カ月間は、この活動をどこでやったらいいのか、そういう区の案内だったり説明だったり。","respondent":"久保田地域活動課長","answer":"周辺の近隣の方への説明ですけれども、今後議会に報告した後に、周辺の方にご説明をして、工事の説明等を行っていくという予定で考えているものです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"恐らく町会とか地元の方なのかとは思いますので、要するに何らかの打ち合わせだったり、会議だったり、そういう使い方なのかとは思いますけれども、この状況を伺いたいのと、近隣の荏原区民センターや荏原第三地域センターを案内しているということですけれども、やはりご不便をかけるわけですから、丁寧にご説明していただきたいと思いますけれども、何か地域から挙がっている声などがありましたら。","respondent":"久保田地域活動課長","answer":"これから予約が始まりますので、それに対しては丁寧に対応させていただきたいと思います。","voiceIndex":20,"id":"exchange-006"}]},{"id":"topic-03","title":"の(3)、平成２５年度地域振興基金を活用した区民活動助成事業の決定","agenda":"の(3)、平成２５年度地域振興基金を活用した区民活動助成事業の決定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど少し理由がありましたけれども、その辺を伺いたいと思います。いろいろな要件を見ても、大体何らかのものにみんな当たってくるのかとは思いますけれども、そうは言っても実際審査があるわけですから、今、先ほど説明があった不採択になった主な理由というところを、もう少し詳しくご説明いただきたいと思います。","respondent":"寺嶋協働・国際担当課長","answer":"これも先ほどの繰り返しになりますけれども、初期投資の備品購入が申請の金額の中に、それが大半というか、ほぼ全部を占めているものについては、もともとこれは補助金がなくても実施が可能である事業で、それを拡張する、もしくはエリアを広げるとか。","voiceIndex":27,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"例えば全部で６個ありますけれども、それぞれにだめな理由というのは当事者には伝えてあるのか、差し支えなければどういう理由なのか。何かこの基準が合ってないようなものにも思えてならないのですけれども、そういうところは逆に熱意とかそういうところの判断になってくるということでしょうか。ちょっともう少しご説明いただけますでしょうか。","respondent":"寺嶋協働・国際担当課長","answer":"差し支えない範囲でということでしたので、不採択となったときの評価を幾つかご案内しますと、例えば実施回数が１回、２回という講習会だけでは、その事業目的の達成とはちょっと結びつくとは思えないといった評価があったということです。","voiceIndex":29,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"意見","question":"この事業の目的が書かれていますが、１回きりの事業に対して、１回だけこの基金を活用して事業が行われるというようなイメージなのですね。例えば連続的に毎年やっているようなものはできないのかと。何人かいるかと思いますが、その寄附をされた方の中から、どなたか審査委員として入ってもらうというような取り組みというのは、検討されたことがあるのかどうか、その２点をまずお知らせください。","respondent":"寺嶋協働・国際担当課長","answer":"寄附者を審査委員に入れるということにつきましては、実際にはそういった検討はこちらで行ったことはありません。ただ、公募という制度がありますので、ご本人が希望して公募委員に申請するということは、特段拒むものではございません。","voiceIndex":31,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問","question":"２点目のほうからいきますが、例えば何かの審査をするときに、そのもとになっている企業のトップの方を審査員にするとか、民間ではよく、例えばコンテストとかで協賛しているところの代表者を例えば審査委員長にあてるとか、よくそういうのは民間でやられていると思うのですね。そういう支援策というのがあるのかどうか、それだけ教えてください。","respondent":"寺嶋協働・国際担当課長","answer":"これの事業の続編というイメージでの位置づけの事業というのは特別用意しているものではないですけれども、いろいろな協働事業についての支援をさせていただいているという意味では、例えば協働事業の提案制度という、区の課題に対して応募していただくという事業がある。","voiceIndex":33,"id":"exchange-010"},{"speaker":"山元委員","kind":"質問・要望","question":"１つ教えてほしいのは、まず、この申請事業が１２事業あったのですけれども、これは一応助成対象となったのは６事業ですが、例えば１２事業あって、全部助成対象となることはあるのかどうか。","respondent":"寺嶋協働・国際担当課長","answer":"それからあと、実際に採択された団体がどういうことをやるかというと、先ほど説明が雑駁だったのでもう少し具体的にお話しますと、まず、一番最初の、申請団体名でいきますとパルレという団体ですけれども、これはネットの古本売買の就労体験みたいなものですね。","voiceIndex":35,"id":"exchange-011"},{"speaker":"山元委員","kind":"質問","question":"そのときは同じことだから採用しないというか、でも学校は違うから採用するか、そのときによって違うでしょうけれども、その辺、似たり寄ったりのものが毎年挙がってきた場合、その対象とか考え方はどうなのでしょうか。","respondent":"寺嶋協働・国際担当課長","answer":"それは審査のところでの判断ですけれども、可能性としてはある、事務局としては申請があればお受けするということになります。","voiceIndex":37,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"その実施報告書等も各年度であったと思うのですが、過去に当たってどのような結果が出ているのかということですよね。そういうこの何年もやってきている中で、どのような方向性になっているのかを聞きたい。それから審査委員に関しては、費用弁償に関してはどうなっているのか、教えていただきたいのですけれども。お願いします。","respondent":"寺嶋協働・国際担当課長","answer":"昨年度までの経過ということで、活動報告書のほうを確認しまして、一通りまた団体とも可能な範囲で接点があるときには行くようにしていますけれども、活動報告の中で特に広がっているという報告を受けている団体が幾つもありましたので、例えば昨年度実施した団体としては。","voiceIndex":39,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この事業自体は地域のことを進めていく上でぜひこれからも活用していただきたいと思うのがありますけれども、先ほど予算面で３００万円という話があり、これは現在、地域振興基金というのは幾らぐらい寄附がまず来ているのか、大体年間どのぐらい来ているのですか。","respondent":"寺嶋協働・国際担当課長","answer":"地域振興基金の寄附金です。ここ３年間の推移で見ますと、大体２００万円前後の寄附をいただいているです。","voiceIndex":41,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"さっき話したのだけれども、今年はケーブルテレビの株式売却がここへ入ったので、ですからお金としては十分あるから問題はないとして、そうすると、先ほど３００万円というのがこれからどういうふうに考えていくのか、数が増えてきたとき、もう少し中身を検討してプラスしてもいいのではないかという感じがちょっとしていますので、ぜひ。","respondent":"寺嶋協働・国際担当課長","answer":"１点目、ケーブルテレビの件につきまして、今のところ予算が３００万円ということですけれども、また今後の申請状況、採択状況等を見まして検討していきたいと考えております。","voiceIndex":43,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。ただ、やはりこういうせっかくいい事業をやっている中で、ある程度その辺も検討してもいいのではないかというところはちょっと感じたので、今後の検討に値するかどうか、ちょっとその辺を頭に入れておいてもらえば、せっかく寄附した人たちの思いもこういうところに使われているよというのが出てくるのではないかと思いますので、その辺をよろしくお願いします。これは要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"だから、今回の事業は資金を提供する、助成するという事業ですけれども、せっかくここに来てくださっている方で漏れてしまった方に対しての、協働としてのお金ではない支援というのは、担当の課として一定していかないといけないと思いますけれども、その辺についてはどうですか。","respondent":"寺嶋協働・国際担当課長","answer":"これは、採択になった団体、不採択の団体も共通の部分がありますけれども、区のほうで協働として取り組んでいます各種の施策について、例えば情報の共有ということでは、すまいるネットとかインターネットによる情報共有サイトがあります。","voiceIndex":46,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"何回も同じことを言いますけれども、この事業は基金から資金を提供するという事業ですけれども、区の行政としてというのは、お金だけではなくしての支援というのがそもそも一番私は大事だと考えていますので、そのくらい熱意のある団体に対して、本当に根本的に行政として何をしていくべきかということをいつも考えて、これからもやっていっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-018"}]},{"id":"topic-04","title":"の(4)、ベトナム（ホーチミン市）調査団派遣事業","agenda":"の(4)、ベトナム（ホーチミン市）調査団派遣事業","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この事業について、ちょっとまだ私もよくわからない部分があるので、基本的なところも含めて、この事業の考え方を伺いたいと思いますけれども、まず、この品川区内のものづくり、中小企業のどういう状況に目を向けて、それをどう改善させたいと思ってこの事業を位置づけたのか、全体の構成を伺いたいと思います。この製造業３名、サービス業４名という、製造業というのはどういう業種なのか。","respondent":"山崎ものづくり・経営支援課長","answer":"実施後の報告につきましては、やはり当事業の成果を一定わかりやすくまとめて皆様に報告ということになりますと、いわゆる冊子ベースをつくるということも基本にさせていただきながら、ホームページ上に掲示ですとか様々な工夫をして、本事業の成果について共有させていただき。","voiceIndex":54,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"それについては区はどうお考えなのか伺いたいのと、抜本的には国内の品川地域経済そのものを底上げしていかないといけなというところはあるとは思いますし、やはり消費を伸ばすためには、当然賃上げとか、支援とか、それは国内でやっていかなくてはいけないわけですけれども、ただ、言いたかったのは、町工場の人に話を伺うと。","respondent":"山崎ものづくり・経営支援課長","answer":"現在、品川区内には２,０００社から２,５００社のものづくりの製造業の中小企業が、様々な工夫をしながら地域産業の活性化という観点でいろいろ頑張って仕事をしていただいている状況です。","voiceIndex":56,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"税金を使っているわけですから、投資対効果がどういうふうに出たのか、すべてにおいて検証結果をまず教えていただきたいのですけれども、その辺の検証をきちんとして、こういうあれでこういうふうに品川区民のためになっていますというのを確実に説明されないと、何でまたベトナムになってしまうのか、その辺の検証はしていると思いますが、具体的に投資対効果。","respondent":"山崎ものづくり・経営支援課長","answer":"タイにつきましては、先ほどの説明の資料にも記載させていただいておりましたけれども、タイのレンタルオフィスを借りまして、そこで、現地進出や現地企業との技術の連携ですとか、販路拡大を目的とした営業活動を行うための活動拠点としての事務スペースを１つ確保しましたです。","voiceIndex":58,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"予算には賛成していますから、施策には賛成しているのですけれども。だから、タイの検証を具体的にきちんとして、しているということですけれども、検証してこういう投資対効果があってという形の裏づけがないと、なぜ、ベトナムなのかと。タイが失敗したからとは言っておりません。ジャカルタとかと思っていたのですけれども、その辺の案というのは出なかったのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"事業の効果の検証につきましては、私ども実施の所管課も含めまして、品川区におきましてはいろいろ客観的な評価を行う事務事業評価の制度などもありますので、品川区全体で事業成果については検証しつつ、次の展開に活かしてまいりたいと考えています。","voiceIndex":60,"id":"exchange-022"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もう区内企業というターゲットは決まっていて、そのパイで事業を展開するわけですから、アプローチの仕方というのは非常に限られたアプローチで進むような事業だと思うので、どのようにタイの事業と、今回のこのベトナムへの調査の事業、こういったこの事業を品川区がやっているというのを、そのターゲットとしているところへどういうように発信をして、民間で言えばいわゆる営業をかけているのか。","respondent":"山崎ものづくり・経営支援課長","answer":"委員がおっしゃられたことにつきましては十分踏まえまして、この調査に行ってまいりたいと考えております。","voiceIndex":62,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひよろしくお願いしたいと思いますが、やはり危機管理については、例えば現地に行った際に、海外ですから、正直どのような事態が起こるかわからない。これは要望で終わります。それで、アプローチですが、これは本当に限られた企業に対しての事業になるので、区民全員にこれをやっていますからどうですかというわけではないではないですか。これは要望で。参議院選挙もある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-024"},{"speaker":"山元委員","kind":"質問・要望","question":"１つお聞きしたいのは、１０名程度いらっしゃるというので、これはどのくらい金額がかかるのかというのはちょっと興味があるということと、それからこの製造業の方、サービス業の方たちの人の規模というか、中小企業といってもいろいろ様々ありますが、どのくらいの規模の方たちが参加なさるのかということと、まずはその２つを教えていただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"今回、中小企業３事業者のものづくりの業種の方、それからそれ以外のところということで、いわゆる中小企業の方々ですので、３０人から５０人の企業が半分で、あと１００人弱のところが１企業あります。それ以外は３０人から５０人規模という形です。","voiceIndex":65,"id":"exchange-025"},{"speaker":"山元委員","kind":"質問","question":"事業者の方たちもいろいろあって、海外に進出すると仕事がなくなってしまうのではないかと。私も地元の方たちと話をしていて、確かにそういう意見を聞いています。その道を開くための、日本ではやれないけれども、海外、例えばベトナムに行ったときには、そういう意味では広げることができる夢を持たせてあげられるということではないのですが、そういうことは考えていらっしゃるのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"様々な事業が展開しておりまして、事業の受け手の中小企業の方々がどういう受けとめをして、何が効果的でどういう支援が必要なのかというようなことについて、今年度中小企業を対象にしたアンケート調査などを行って、そうした結果に基づいて。","voiceIndex":67,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"委員会の予定もあるから、なるべく短く。産業ニュースなんかにも、この海外進出相談のことが随分出ていると思うのですけれども、今回、この事業者７社の中は、大体そういう相談に来ているような業者なのか。それから１点、バンコクに出たときにもう既に品川区と接触を持っているところが、やはり今回も申し出が来ているのかどうか、その辺をまずちょっと教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"バンコクの関係で、事業所をお借りになっていただいて活用していただいている企業の方も今回入っております。","voiceIndex":69,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"基本的な考えですけれども、バンコクのときには製造のために行くのではなく、販路拡大だよということがありました。今回の製造業に関しても、あくまでも販路拡大、要するに製造拠点をつくりに行くのではないということでよろしいですか。それから、サービス業３社というのは何の業者か。サービス業は範囲が広いではないですか。その辺、どういう関係の業種ですか。","respondent":"山崎ものづくり・経営支援課長","answer":"それからもう一つが、いろいろ環境に配慮しました商品ですとかサービスの提供で、ミニソーラーですとか、自然冷媒ガスなどの事業の提案をするという意味のサービス会社ということで、いわゆる接客などのサービス業というよりも。","voiceIndex":71,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"サービスというとちょっとイメージがね。今度のレンタルオフィスはＪＥＴＲＯとちょっと離れたところにあると、さっき耳にしておったのですけれども、そういう点でＪＥＴＲＯとのつながりというのは、やはり今度のベトナムのほうも、その辺のつながりというのはどのようになっているか、確認をしたい。","respondent":"山崎ものづくり・経営支援課長","answer":"こちらの日本貿易振興機構の事務所はホーチミン市内にございまして、こちらのＪＥＴＲＯで行われている日本からベトナムへの進出の支援、それから販路拡大の状況ですとか。","voiceIndex":73,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほどのバンコクのレンタルビジネスサポートセンター、さっきたしか２社とお話があったと思いますけれども、ご利用いただいている企業の方と会えて、非常に喜んで使いやすいということもお話があったのですけれども、逆に言うとその場所が２社だけというのは、さっきもちょっと話があったけれども、もっと増やしていきたいというお話もあったと思うのですけれども。","respondent":"山崎ものづくり・経営支援課長","answer":"やはりいろいろご利用いただいた企業の方からは、拠点としての活動の場とともに、いろいろなソフト的な支援をいただくコーディネーターなども配置しておりますので、そうした一つ付加価値のある事務所としまして、あるいはビジネスクラブのほうとも連携しながら。","voiceIndex":75,"id":"exchange-030"}]},{"id":"topic-05","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"非常に熱心で、ちょっと項目が多いけれども、熱心という意味では歓迎すべきことだと思っています。例えば観光だったら観光協会か。国際交流だったら、あとスポーツもあるし、商連、工場協会もあるし、ぜひそこの事業を区から聞くだけではなくて、そういう当事者の方にお話を伺って、要望も聞きながら、所管事務調査ができればよいかと思います。","respondent":"渡辺委員長","answer":"もう一つは、議会のあり方検討会の流れの中から、議長からの方向性の中で、本来は調査を目的とした所管事務調査から、さらなる提言という形が踏まえられていますので、そのときに、それでは、この４項目がおさまるかという議論がありました。","voiceIndex":81,"id":"exchange-031"}]},{"id":"topic-06","title":"に行かせていただきます。行政視察","agenda":"に行かせていただきます。行政視察","exchanges":[{"speaker":"鈴木（真）委員","kind":"提案","question":"自民党から提案します。それから視察に関して、今回の調査項目に合わせてということで、自民党としての提案の中で、東北方面、北から言うと盛岡、岩手のちょっと下に当たるのですけれども、これは岩手県の紫波郡というところの紫波町、そこが公民連携、商工支援というのをやっているということで、ここが１点、提案の材料です。それから、その下です。以上、自民党としては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-032"},{"speaker":"石田（し）委員","kind":"提案","question":"それと青森市のウォーターフロント活性化ビジョンについても、非常に水辺の利用としては参考になるのではないかということで、両方青森県で提案をします。個人的にではありますが、先ほども海外の販路拡大というような話が出ていたので、実現性は非常に厳しいかと思いますが、そういうのも今後、区民委員会はそういうのも所管ですので、少しずつ視野に入れていけばいいのかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-033"},{"speaker":"中塚委員","kind":"意見","question":"まだ今期の委員会も始まったばかりなので、この区民委員会でどこに議論を集中していこうかというのはまだ固まり切れていないので、今、挙がった意見も踏まえながら、どういうテーマがふさわしいのか、正副のほうでもんでいただいて、もむというか少し整理していただいて、示していただけたらと思います。ぜひそれぞれの問題意識にかなった、委員会としても調査研究にふさわしい中身になれればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2670#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":36115,"voices":95}},{"id":"h25-20130702-7","meetingId":"h25-cm07","date":"2013年7月2日","dateIso":"2013-07-02","committee":"厚生委員会","time":"午前１０時００分～午前１１時１７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)の生活保護法による保護基準の一部改正","agenda":"はじめに、(1)の生活保護法による保護基準の一部改正","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"今、モデルケースで３人世帯というのをご説明いただいたんですが、一番多い例というのがどこのあたりかわからないんですけど、生活保護を受けている方の中では、例えば一人暮らしの高齢者というのが多いような気がするんですけれども、そういうケースだとか、この例一つだけではなくて、傾向というのですか、全部の層でもいいですが、全体として下がるのか、それとも。","respondent":"竹田生活福祉課長","answer":"ちなみに、生活保護の中で一番多い単身世帯ですが、基準表２でお一人世帯のところは逓減率が１.０で現行のままですので、単身世帯には影響が少なく、多人数世帯に引き下げの大きい影響が出るというふうに、一般的に言われております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"たけうち委員","kind":"質問","question":"そうしますと、この表の見方ですけれども、例えば６５歳の方だと、基準表１の６０歳から６９歳のところを見ますと、第１類では３万６,１００円から３万７,８９０円と、１,７９０円上がっていると。片や上がっているのと、下がっているのと、これを相殺した分が二千何百円下がっていると、こういう見方で、これに基づいて見ていけばいいということですか。","respondent":"竹田生活福祉課長","answer":"委員ご指摘のとおり、例えば６５歳の層ですと、１類のほうは１,７９０円上がっている、世帯共通の第２類のほうは３,７８０円下がっているということですので、生活扶助だけで見れば、６５歳の単身層については、その分下がっているということになります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"たけうち委員","kind":"確認","question":"わかりました。そうしますと、確認ですけれども、生活扶助の部分だけの改定と、いわゆる住居の部分とか、医療の部分とかは現行のままということでいいのかどうかという確認。逆に、物価が少し上がってくるとなると、どこかの段階で、それはまた上げていくという判断があってしかるべきだと思うんですけれども、その辺の動きというのはどうなるんでしょうか。","respondent":"竹田生活福祉課長","answer":"２点目、今後の見直し等ですが、今、国でインフレ対策等数々の経済施策が行われているところです。今後、場合によっては消費税の税率引き上げ等も検討されているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"意見","question":"この対象者への周知というか、お知らせ等はどうされるのか。","respondent":"竹田生活福祉課長","answer":"７月半ばに計算のほうは予定しておりまして、計算金額が確定し次第、全世帯に変更金額のご通知を差し上げるところです。それ以外にも、ケースワーカーが家庭訪問時、あるいは電話等で受給者とお話をする機会を通じまして、皆様に周知を図っているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"今のたけうち委員のモデル世帯のケースというところに関連するんですけれども、厚生労働省が出した標準３人世帯のモデルケースというのは、夫が３３歳、妻が２９歳、子どもが４歳ということは、夫に当たる方の世帯主、働き手が何かの状況で生活保護になられているのかなと思うんですけれども、品川区の場合、そういう複数世帯の受給者数が多いのか、単身の方が多いのか。","respondent":"竹田生活福祉課長","answer":"今回の改定につきましては、物価の動向も勘案しておりまして、そちらは全世帯に影響があるものですので、程度の幅の差はありますが、基本的に、品川区の全世帯がマイナスの影響を受けると考えております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"そういうところに対して、ただこうなりましたからという説明だけではなく、ここで１０％の限度調整とかありますけれども、区として何か対策というのかちょっとわからないんですが、何かお考えをお持ちでしょうか。","respondent":"竹田生活福祉課長","answer":"今回の基準改定にあたりましては、全国の消費実態調査の最新のデータを使いまして、一般低所得者世帯の消費実態を相対的に指数化して検証した結果ですので、受給者の方はいろいろご意見はあろうかと思いますけれども、こちらの改定内容を丁寧にご説明することによって。","voiceIndex":15,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"ここの部分で、ほかに教育扶助とか、住宅、いろいろな法外援護があるわけですけれども、そこで相当カバーをしていかないと厳しい状況に、ただでさえ生活が大変な世帯のところにいくのではないかと思うんですが、そこについては、どういうふうな、今後の見通しと対策を考えていらっしゃるんでしょうか。","respondent":"竹田生活福祉課長","answer":"今回は、教育については、法内、法外とも見直しを行っておりませんので、今までどおり子どもの貧困の連鎖を防止するために、子どもの教育についても力を入れてまいりたいと考えております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"法外のほうは見直しは行われないということなんですが、全体的に、６歳以上の子どもを持っている世帯というのは、現状下がるという通知を、当事者の方たちに送られているのかと思うんですが、そこはどのくらいの減少率、多分１０％以上になるのか、そこが押さえられているのか、大体どのくらいの傾向があるんでしょうか。","respondent":"竹田生活福祉課長","answer":"こちらの子どものいる世帯ですけれども、現行の生活保護扶助基準と一般低所得者世帯の消費実態を、年齢別、世帯別に相対的に指数化して比較し、その乖離を検証し、解消したものですので、消費実態に沿ったものだと考えております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"本来、低所得の生活実態に生活保護を合わせるのではなく、低所得の部分を上げなければならないという前提の議論があってしかるべきだと思っているので、今の傾向だと、どんどんそういった形で、セーフティネットを低所得者層に合わせていくという議論はすごく危険だと思って、これは国の議論で、自治体としては、要望として上げていくしかないということだとは思うんですけれども。","respondent":"竹田生活福祉課長","answer":"今回の保護基準の改定には、さまざまな事業に影響があるものと考えておりますが、あくまでもそれぞれの事業は生活保護基準を一つの目安として扱っているものですので、それぞれの事業の中で、今後、どういった対応をとるのかというのは、それぞれの事業の所管。","voiceIndex":21,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"現場が一番身近にそういった事例をわかっているところですので、各所管が、というよりも、ほんとうに横串を差して情報交換をして、共有して、取り組んでいただきたいということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"今、ほかの委員からの話を聞いていまして、改めて、２点確認をさせてください。それから、世帯によってとか、やはり減額になっていますから、いろいろな問題が生じてくると思うんですが、ほかの委員からもありましたが、改めて確認ですが、今実際、区として法外援護の変更を考えているか、考えていないか、わかりやすくお願いいたします。","respondent":"竹田生活福祉課長","answer":"法外援護についてのご質問ですが、毎年、制度の必要性、妥当性等を検証しまして、それで継続等を決定しております。今後も、必要性、妥当性について十分検討のうえ、存続、あるいは、見直し等を決めていきたいと考えております。","voiceIndex":24,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"今、法外援護は、毎年妥当性を検討するというお話でしたけれども、その検討機関というのは、どういうメンバーで、どういうふうにされているのでしょうか。","respondent":"竹田生活福祉課長","answer":"それぞれの事業に一番精通しておりますのは所管課ですので、所管課で十分に検証のうえ、提案していきたいと考えております。","voiceIndex":26,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"所管課というのは、そちらの所管課なのか、ほかの事業を持っている所管課のことをおっしゃっているのか、ちょっとそこを教えていただけますか。","respondent":"竹田生活福祉課長","answer":"保護費を補う法外の部分についても、生活福祉課で所管しております。その他の保育料とか、就学援助等はそれぞれの所管課で扱っておりますので、それぞれの所管課で検討されるものだと考えております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"事務事業概要のほうで、生活保護の受給世帯と人員のところで、平成２４年度が４,６０４世帯、人員が５,５１１人となっているんですけれども、今現在の数字はわかるんでしょうか。","respondent":"竹田生活福祉課長","answer":"申しわけございません、ちょっと最新のものは持ってきてないのですが、リーマンショック以後は１０％等の増加率でございましたが、年々増加率は下がっておりまして、ここ数カ月では、対前年比二、三％で増加しています。","voiceIndex":30,"id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"事務事業概要で、生活保護基準改定の推移とありますね。それで、平成１６年、平成１７年のところでも３２０円減っていると。それで、平成１７年から平成２４年までは改定がなくて、今回、１万５,９８０円減るという、これだけ大幅に減になるという大きな理由というのは何か、お知らせください。","respondent":"竹田生活福祉課長","answer":"前回は、平成２０年に検証を行って、当時、据え置きという状態がずっと続いてきました。その間に、厚生労働省の発表によりますと、４.７８％のデフレが起きているということですので、今回の改定金額は合理的な根拠に基づいて適正化を図られたものだと考えております。","voiceIndex":32,"id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"ほかの委員からもありましたけれども、物価も上がっている状況で、今後どうなっていくのかというところですけれども、ここでこれだけ大幅に減になっていくというのは、今までも厳しかったはずなんですけれども、３人世帯の例ですけれども、１,４８０円程度で済んでいたものを、今、この厳しいときに１万５,９８０円減、ちょっとこれは現実に合っていないのではないかと、私は思うんです。","respondent":"竹田生活福祉課長","answer":"前回の平成２０年の見直し以降ですが、東京都区部におきましては、平成２１年度が、前年比１.２％の下落、平成２２年度が１.０％の下落、平成２３年度、平成２４年度は０.５％ずつの下落ということで、平成２１年度から４年連続。","voiceIndex":34,"id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"生活保護の基準額を基準に定められているものもありますよね、就学援助だったりとか、それはどういったものがあるのか、ちょっとお聞かせいただきたいと思います。","respondent":"竹田生活福祉課長","answer":"厚生労働大臣の見解によりますと、それぞれほかの制度への影響については、それぞれの制度の持った目的実態等を十分に勘案しながら、できるだけ影響が及ばないように対応することを基本的な考え方とする、とされております。","voiceIndex":36,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"生活保護基準を基準に、子どもの育成にかかわることだったり、課税限度額なんかもかかわってくると思うんですよね。表面に書かれています、社会保障審議会生活保護基準部会における検証結果のもとで、この基準を改定されたということなんですけれども、ここでは、どういった方々が、どういった話し合いをされているのか、わかれば教えていただきたいと思います。","respondent":"竹田生活福祉課長","answer":"今回におきましては、平成２１年度に行われました全国消費実態調査を、事務方のほうで検証しまして、さらに生活保護基準部会という、大学の先生が約１０名ほど参加されているんですが、そちらのほうの基準部会でさらに慎重な検証が行われた結果、今回の改定となっているものです。","voiceIndex":38,"id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そういうもとで、区におりてきて、そのままはめ込んでやっているものですから、区に言ってもなかなかというところもあると思うんですけれども、今の生活実態を踏まえて、毎年検証はしていくということなんですけれども、今がこれだけ大変で、１年間持ちこたえていけるかどうかという状況だと思うんです。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-019"}]},{"id":"topic-02","title":"の健康センター指定管理の更新","agenda":"の健康センター指定管理の更新","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"健康センターの管理業務、いわゆる指定管理については、議会でも、委員会、予算特別委員会、決算特別委員会等でいろいろ取り上げられて、非常に成功している例だと受け取っているんですけれども、利用料金制度の導入か何かによって、いわゆる指定管理料を押さえてきているのかなというイメージがあるんですけれども、その辺の所管のこの間の評価というのですか、それを一応聞かせていただきたい。","respondent":"江部健康課長","answer":"それによって、利用者が増えるということは、品川区にも２０％のキックバックといいますか、戻りがありますので、お互いの利益になるという考え方です。ここ数年を見ますと、年々利用者は増えている関係がありますので、自動的に還元金が増えております。","voiceIndex":46,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"今の一定金額を増えた分という、その一定金額というのは、年度ごとに変えていくものなのか、ちょっとそこのルールを教えていただきたい。それから、区の増収につながっていく部分ということで、稼働率を上げるということで増収になると思うんですが、ここにあるコースの単価というのは、指定管理者が決めるのはなく、条例で決まっていくのかと思うんですが、この５年間は変更はされてないわけですよね。","respondent":"江部健康課長","answer":"条例で定まりました利用料金につきましては、施行規則の中で、それぞれダンス、バレイは１,０００円ですとか、ヨガは幾らということで定額になっておりますので、その変更がないと変えられないという中でやっております。","voiceIndex":48,"id":"exchange-021"},{"speaker":"渡部委員","kind":"質問","question":"わかりました。ただ、実際に利用者負担を考えたときに、１日５００円、ないし４００円というのは、これは変更がずっとないわけですよね。それに関しての動静といいましょうか、今後、改定等を見込んでいるのか、どのような考えをお持ちなのか、これが妥当な金額でずっとこのままいくのか、その辺の考え方を教えてください。","respondent":"江部健康課長","answer":"ただ、受益者負担という観点で、区の施設の利用料全体の見直しを図る中では、検討の俎上には乗ってくるであろうと考えております。","voiceIndex":52,"id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"健康保健センターが平成１１年４月に開設して、その後、平成２１年度から指定管理者制度導入ということで、このことで、今、利用率も上がってきているというのですけれども、導入したら利用率が上がったのか、要は利用者の動向、推移なんかを、ちょっとお聞かせいただけたらと思います。それから、利用者の声なんかは、そういうプログラムなんかに反映させてこれたのかどうかということ。","respondent":"江部健康課長","answer":"今はどうなのかというと、現行のコース型メニューですとか、さまざまな受付の職員スタッフの対応につきましては、目安箱みたいなものを置いていまして、毎月それを私どもは把握しておりますが、おおむね好評な評価を受けております。苦情も若干あります。","voiceIndex":54,"id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問","question":"かなりしみがついていたり、汚れがついていたりというところで、建物の維持および修繕というのもあるんですけれども、これは建物の躯体自体なのかどうかというところで、こういったものは定期的に管理されるのは区なのか、指定管理者なのか、その辺について伺いたいと思います。","respondent":"江部健康課長","answer":"直接、受付業務、それから施設の維持・管理を行っているのは、この共同事業体にお願いしていますが、予定していた補修工事以外で突発的に発生するようなことは、建物はもう十四、五年たっておりますので、建物的にもあちこち出てきていたり。","voiceIndex":56,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"わかりました。私自身も使っていて、いろいろなタイミングの問題はあると思うんですけれども、業者はかなり多いというふうに、先ほども伺いましたので、健康課のほうともよく調整をしていただいて、交換するところは交換していただくということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"区民の健康づくりに関する事業、これは区立ですから、そこはベースにあるのかなと思うんですが、利用者は区内、区外を区切ってないと、今現状、あると思うんですが、利用者が大変増えているということは、人気のあるメニューで、いろいろなところからいらしていただいているんだろうと思うんですけれども、基本データとして、区内利用者。","respondent":"江部健康課長","answer":"調査といいますか、事業者のほうでデータ管理はしておりまして、比率は出ております。ちょっと今すぐに出てきませんが、たしか３割程度が区外の方だったというふうに記憶しております。","voiceIndex":59,"id":"exchange-026"}]},{"id":"topic-03","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"井上委員","kind":"質問","question":"項目案をまとめていただいて、ありがとうあります。就労に特化しての時間しかなければあれなんですが、ぜひともそういったところも視野に、時間があればお願いしたいと思いましたが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-027"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"自治体のできることのほか、いわゆる民間等の協力によって健康づくりを増進していくというところで、ちょっと調べてみましたら、北九州市がちょうど今のタイミングだったんですけれども、企業が健康づくりのコンペティションですね、それに対して有能な案を出してきたところを奨励するという形のことをやっていましたので、どのようなことをやっているのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問・要望","question":"北海道ということで、認知症ということで探しましたら、本別町というところがありまして、距離感まではちょっと調べ切れなかったんですけれども、そこが認知症の高齢者支援対策を非常に先進的にかなり前から取り組まれているということで、この二つを出させていただきたいと考えています。ぜひ、ご検討いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-029"},{"speaker":"井上委員","kind":"質問・要望","question":"今、社会的労働というところで、補助金というのが、障がい者の方たちは人件費には充てられないといった制約の中で、滋賀県が独自に補助制度をつくって、人件費、運営費に使えるというところで、大変力を入れている市民レベルのそういう労働も始まっていますので、そこをちょっと検討していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"健康づくりのところで、ほんとうに幅広いと思うんですけれども、私もずっと言ってきているんですけれども、歯の健康について、先ほど、介護予防なんていうことも出たんですけれども、そこにもつながる歯の健康ということで、全国を含めて、歯科の施策というのはなかなか充実しているところがあまりなくて、見つけるのも大変だったんですけれども、自治体としてというところでは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-031"},{"speaker":"たけうち委員","kind":"意見","question":"基本は、どこでも大丈夫なんですが、２１日まで最終本会議があるので、また決算特別委員会が間に挟まれますので、皆さん結構お疲れの中で、翌日出発というと結構ハードかなと思うので、その辺を考慮いただいて、ちょっとずらすか、もしくは翌週の２８日とかにしていただくといいかなと。翌日出発というと、ちょっときついかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3360#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":20249,"voices":83}},{"id":"h25-20130702-8","meetingId":"h25-cm07","date":"2013年7月2日","dateIso":"2013-07-02","committee":"建設委員会","time":"午前１０時００分～午前１１時５６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、「報告事項」を行います。 はじめに、(1)「しながわ中央公園拡張整備用地暫定整備の住民説明会開催について」","agenda":"の１、「報告事項」を行います。 はじめに、(1)「しながわ中央公園拡張整備用地暫定整備の住民説明会開催について」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この暫定の範囲なのですけれども、７,６００m2のうち３,３００m2をということで、この範囲に決めた理由というか、全体ではない理由を教えていただきたいのと、あと、この整備工事の内容、どういった中身をして使えるようにするのか、工事の内容も教えてください。","respondent":"多並公園課長","answer":"二つ目の工事内容ですが、工事もさることながら、開放期間が約１年強というところの範囲も考えまして、なるべく簡易であり、ただ、ご利用いただけるとともに、二重投資とならないようにということの考えのもとに工事内容を精査いたしました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"暫定開放が１年半ということですけれども、具体的に区民の皆さんにどのような使い方をしていただくのか、その辺と、あと予算と、開放のときの管理をどのようにされるのか、教えてください。","respondent":"多並公園課長","answer":"予算につきましては１,０００万円。ただ、精査をし、それをもう少し減額できないかということで、今起工金額の調整をしています。もう一つ、管理につきましては、昼間、いわゆる昼間の間開放させていただいて、夜は扉を閉める形で、施錠する形で考えてあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"地域の行事などに使うというようなお話だったのですけれども、具体的に窓口というか、どこに相談をすればいいのかということと、あと、本格実施に向けて２６年度設計・整備工事ということなのですけれども、今後のこの公園のあり方についての議論というのはどこでどのようにされるのかというところも教えてください。","respondent":"多並公園課長","answer":"整備内容、工事等につきましては、その都市計画手続後、工事の契約等を進めていく段階で、そのタイミング、タイミングを見ながら説明会等行いながら進めていきたい、そのように考えてあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"９月の説明会というのはどの範囲の方を対象にされるのか教えていただきたいのと、都市計画の位置づけをするということなのですけれども、この公園のあり方ってもう固まっていたのでしたか。共産党としては防災の広場はもちろん大事ですけれども、区民の願う施設もぜひつくってほしい、総務委員会でもそうやって言ってきたのですが、中身的にはかなり固まってきているのかどうか、その辺をお聞かせください。","respondent":"多並公園課長","answer":"ここの公園がある町会が３町会あります。３町会につきましては町会長または町会長の会議等、さまざまな機会を捉えながら、周知を図りながら、説明会を開くこと、また、いろいろご説明しながら進めていきたい、そのように考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"管理というお話がありました。それと、あと、広場になるわけですから、運動的なところ、スポーツに使えるような形にはならなかったのかなと。なかなかスポーツする土地がないので、要望は多いと思うのですよね。自分たちの思いというのがどの時点で反映することができるのか、できないのかというのも非常に気になる点だと思いますので、それについてどう考えられているか。","respondent":"多並公園課長","answer":"全体スケジュールを説明会の中でです。これにつきましては、委員のご指摘のとおり、説明会、暫定整備と言えども、全体の説明会を今後、９月にやり、こういうスケジュールで今後やっていきますということをお話して、的確にご説明したいと、そのように考えてあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"管理のほうはよろしくお願いします。そうすると、あれをつくれだ、これをつくれだ、あれだこうだのという、いろいろなことが広がってしまうので、やはり、ここはもともと防災ということで、しながわ中央公園も含めて、今後は全体を考えた中に防災対策の一つとして考えていくのだということはきっちりと話していただきたいと要望であげておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"意見","question":"だから、あそこにもし、ヘリコプターの発着ができれば、万が一の際もそういう物資をおろして、すぐに区役所に展開することができるというふうに、防災広場をつくっていくのであれば、いろいろな物事について、立地条件とか、区役所の前である位置づけを生かした活動をしていかないといけないと思うのだけれども、今、現時点のお考えをお聞かせください。","respondent":"多並公園課長","answer":"その位置づけの中に、今基本設計等を行っております。この中で、公園の整備という観点もありますが、やはり、防災公園ということで、中央公園と一体的に防災活用、どのような形になるかというのを今検討している最中です。","voiceIndex":16,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"個々具体的なところは実践できるのかどうか別としても、やっぱり私たちが思うのは、あそこに防災広場をつくっていくのであれば、区役所が目の前にあるわけですから、そこにうまく立体的に運用できる仕組みを前提とした広場をつくっていくことがＪＴの願いに応えることにもなるのかなと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"}]},{"id":"topic-02","title":"しながわ水族館の夏休みイベントについて","agenda":"しながわ水族館の夏休みイベントについて","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これは、お知らせというのはどういう形でお知らせをするのでしょうか。例えば、コストですね。どのくらいのコストがかかって、さかなクンをお呼びするのは結構お金がかかるのではないかなと思うのですけれども、その概要はどうなっているのですかということをお聞きしたいと思います。","respondent":"多並公園課長","answer":"そことの間で価格等、また、全体的なそこら辺につきましてはお話をして、今最終的にそのイベントの内容をもう一度最終精査しながら行っているところもあり、金額につきましては現時点でお幾らとはっきりお示しすることが、お話しできない形になってあります。","voiceIndex":24,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"もっと大々的にするべきだと思うのですよね。さかなクンを呼んで、それなりのサンシャインとの契約が決まっていないというにしても、やっぱり、品川区はそれなりに責任を負うわけですから、きっちりといろいろな品川区独自での品川区の中でもいろいろな関係があるわけですから、そこをぜひ活用しないといけないのではないかなと思うのですけれども、この考え方はいかがでしょうか。","respondent":"多並公園課長","answer":"イベントとしていろいろな形で一緒な形でできないかということで、観光協会だけに商業・観光課という形になりますが、今、経営改善検討委員会というのを立ち上げさせていただいて、昨年度入館者がかなり落ち込んだ関係で、まずはその対策を講じたいということで、区の中の所管。","voiceIndex":26,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろなところの団体もしくはその所管と、コラボレーションすることによって、いろいろな新しい方向づけができるのではないかなと思いますので、今進めていること、７月２０日ですので、今月ですので、それに間に合うようにできる限りのことをやっていただきたいという要望をしていきたいと思います。経営検討会、ちょっと気になるのが、子ども未来事業部ってこの中に入っているのですか。","respondent":"多並公園課長","answer":"青少年育成課であったり、さまざまな観点ですね。連携を図れるということで、中に入っていただいて、いわゆるその部のまとめということで、いろいろなアイデアを集約しながら、私どもと一緒に考えていこうということで進めているところです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"夏休みの間のイベントなので、本当に子どもたちでにぎわってほしいなと思います。水族館は結構大人でも好きな人がいるのですけれども、私は武蔵小山なのですが、とても不便なのですね。２回乗りかえないと行かれないのですよ。ぜひ再考していただきたいと思うのですが、ここで言っていいかどうかわからないのですが、いかがでしょうか。","respondent":"多並公園課長","answer":"もう一つの観点といたしまして、入館者がかなり落ちているという観点も含めて、どのようなことが経営の効率化を図れるかというのも一方では命題としてあるところで、全体的には今のような形で進めることが、大井町とのピストン輸送ということがあれば。","voiceIndex":30,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２６号線が早く開通すると、大井町にも大変便利になると思うのですが、今の状況ではなかなかそうなっていない。ルートを確保されても、品川区にある貴重なそういった観光地をつないでいくルートとかもぜひ考えていっていただきたいと思いますので、頭の片隅に置いておいていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"しながわ水族館の夏休みイベントでさかなクンの夏祭りｉｎしながわ水族館ということで、さかなクンが有名で、イベント自体がさかなクンの冠を利用して、ただ単にいろいろなところで連携を立てて、さかなクン、これ、何回来るのか、いろいろ費用のこともあるのですけれども、さかなクンの冠、イメージを利用して水族館の来客数を、要は集客として名前を利用するために、やるのか、それともさかなクンが、これ。","respondent":"多並公園課長","answer":"もう一つは、このさかなクンが魚のことを詳しいだけではなくて、本当に好きな方で、ご自分の家でもそういう飼っていらっしゃることがあって、そういう珍しい魚とか、こういうのはこういうエピソードですよというのを展示することで。","voiceIndex":33,"id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"両面、それはもちろん両面ということで、私、どちらに重きを置きますかという意味で伺ったつもりなのですけれども、これは７月２０日にオープニングセレモニーということで来ていただけるということなのですが、ギャラの問題もある、事務所との調整の問題もあるかと思う。当人のスケジュール的な問題もあると思うのですけれども、これは１回でさかなクンのほうにお出ましいただく機会は終わりなのですか。","respondent":"多並公園課長","answer":"１回で終わりです。これは先ほど費用の面もお話ししましたが、やはり１回だけでもかなり高額なところがあるもので、２回、３回と行かないだろうということで、今回は１回です。","voiceIndex":35,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"だから、１回ではなくて、ただ単に冠を利用したイベントなのでしょうか、それとも、もうちょっと思い切って人にやはり、さかなクンというキャラクターに資金をつぎ込んでここを活性化させる事業なのかという、どちらのほうが中心に考えていらっしゃるのかということで聞いたのですけれども、この１回、７月２０日ということで今提示をされておりますが、予算の問題もあろうかと思いますけれども。","respondent":"松代防災まちづくり事業部長","answer":"我々の区の水族館、アミューズメント施設ですので、どうしても例えば、先般の一般質問の答弁でも言いましたように５年に１回ぐらいの施設の更新だとか、新しいものを打ち出すというのが一番効果があるところなのですが、それがなかなか、非常に難しいということもありまして。","voiceIndex":37,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"十分そこのところのはわかりました。水族館は変な話だけれども、手っ取り早く学習ができる、夏休みの宿題の課題を得るには十分な材料がいっぱいあるので、そこらのあたりの活用というか、事務所とかいろいろ、人を派遣してもらういろいろなルートとか、大変な手続があると思うのですけれども、そこのあたりはこの事業を行うに当たってお考えに入っていらっしゃるのですか。","respondent":"松代防災まちづくり事業部長","answer":"今、貴重なご意見とアドバイスをいただきましたので、早速残された時間でどのような形ができるかわかりませんが、そういう機会を得る中にいろいろ交渉といいますか、お話をさせていただいて。","voiceIndex":39,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問","question":"そういうところに２０日を特に集中してＰＲしていくことが一点と、費用対効果でいくと最小で最大の効果とよく言いますけど、先ほど７月２０日にさかなクンの人件費等いろいろあったけれども、それだけのお金が出る。それがまた次につながっていくという仕組みをつくっていかないと、このさかなクンのイベントの成功はないと思うので、そういうことについてのお考えはいかがでしょうか。","respondent":"多並公園課長","answer":"もちろん今後も先ほど西本委員からもありました区内の学校等だけではなく、伊藤委員のご指摘もありました大田区側の学校等、また、回数券もどのような形のができるかも、いろいろな形でさまざまな機関等を調整しながら、できる限りこれからの期間進めていきたい。","voiceIndex":41,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"やっぱり、民間のアイデアにはかなわないところが相当あるので、私たちもない知恵を絞っているわけでありますけれども、やっぱり民間のそういう、行政側のアイデアも必要なのだけれども、民間の視点で７月２０日にどうやって仕掛けをするのか、仕掛けができたわけだから、そこにできるだけ多くの方々を呼んで、しかも来た方々ができれば９月１日の間で２回か３回ぐらい来てもらえればいいわけではないですか。","respondent":"多並公園課長","answer":"テレビ局も１局、私らに電話がかかってきたりなんていうのもありますので、いろいろな形でＰＲもさまざま、メディアも踏まえながら、ＰＲ、またいろいろな形の先ほどの、品川区内だけではなく、大田区も含めたＰＲはもちろん、サンシャインとも協議しながら進めてまいる。","voiceIndex":43,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"今言った新聞やテレビやマスコミにもどんどん出せばいいと思いますよ。ある意味、無料で宣伝してくれるわけですから。それで、しながわ水族館にさかなクンが来て７月２０日にイベントをやるということについては、それはぜひどんどんとマスコミに発表してくださいとお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"私のほうは答弁は要らないのですけれども、意見だけを言わせていただきます。これがある程度目安が見えているのかもわからないけれども、開示されてこない。ですから、当然にその数字等ある程度のものというものははっきりして物事を運んでいくということなので、その辺はしっかりと、今回の件に限らず、全体で記録に残したいというか、そういう思いがありますので、意見として述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-021"},{"speaker":"木村委員","kind":"質問","question":"今回、これが初めてのこのような芸能関係をお使いになって、芸能人などをお使いなることは初めてのことなのかどうか、そして、これがうまくいけば、次に何かもっとほかのことが考えられるのかどうか、もしあれば教えてください。","respondent":"多並公園課長","answer":"これにつきましては、今後、この動向を見ながら検討してまいりたいと考えています。","voiceIndex":47,"id":"exchange-022"},{"speaker":"木村委員","kind":"質問・要望","question":"さかなクンというのは、これはイコール水族館に直結していますけれども、それ以外に集客はできるのかどうか、そんなこともこれがうまくいけば、そんな可能性があるかどうかということも教えていただきたいと思います。","respondent":"多並公園課長","answer":"それで、一般的には今までは定期的にある程度改修をしながら新たな取り組みをやってきたところですけれども、また、これからのやり方として、今のものを活用しながら、魚が好きなリピーターの方が来ていただけるにはどのような形がいいのかというのも。","voiceIndex":49,"id":"exchange-023"},{"speaker":"木村委員","kind":"質問","question":"そういうこともこれから入館者数がどんどん減っている、年々減るわけですから、そこを何とか食いとめるためのこのさかなクンのショーだと思うのですが、もしいろいろなことを考えられるのであれば、そういうことも考えることを少し視野に入れながらやっていかれるということは可能かどうか。","respondent":"多並公園課長、松代防災まちづくり事業部長","answer":"それも期間限定でやっていましたが、そのような、それが効果があったのか、そこら辺も含めながら、今後しながわ水族館でもこの展開についてはサンシャインとよく協議しながら進めてまいりたいと思います。それがリピーターとして来ていただく。そういった工夫も一つの中には入ってくると思いますが、基本はやはり水族館としての本来の目的にまずそういうような形を第一に考えながら運用をしていければと、このように考えているところです。","voiceIndex":51,"id":"exchange-024"},{"speaker":"こんの副委員長","kind":"提案","question":"いろいろなご説明を今聞いていて、今回のこの夏休みイベントを何とか成功させていただきたいという思いから、大沢委員の質問と重なる部分があるのですけれども、具体的に提案をしたいと思うのですが、いわゆるさかなクンのこのフィッシュハウス、これは展示だけのものかというのを確認させていただきたいのと、あと、先ほどのご答弁の中に今後の動きの中で、子ども未来事業部の方とも連携をするという。","respondent":"多並公園課長","answer":"そのような展示を中心とするものです。子ども未来事業部との関係といたしましては、先ほど検討委員会または課長級で言うと作業部会というのをその下でやっております。","voiceIndex":54,"id":"exchange-025"},{"speaker":"こんの副委員長","kind":"質問","question":"そこら辺のところは何かワークショップみたいなところがこの期間中に毎日とは言わなくても、１日のどこかの時間帯でとか、その魚をつくる、あるいは魚をつかった、何というのでしょうか、つくって遊べるような、そういったワークショップみたいなのももし、もう間もなく始まりますので、何ですか、そういったものも、何というのでしょうか、ちょうどお盆の時期に重なる。","respondent":"多並公園課長","answer":"ただ、今のご提案、ありましたですね、そういうのにかかわらないようなイメージするようなものであればできるかと思いますので、どんな形でできるかはサンシャインと協議しながら、どんな形にできるかというのは検討してまいりたいと、このように思っています。","voiceIndex":56,"id":"exchange-026"},{"speaker":"こんの副委員長","kind":"提案","question":"当然さかなクンに関係して、していただく、それはもうありがたいことですが、それはもう予算の関係上またあれなので、それとは別のお考えでされるという意味のことですので、何かご検討いただければ、そこでのまた集客効果で、夏休みイベントはそういったものをされると、より効果が出るのではないかと思いますので、ご提案させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-027"}]},{"id":"topic-03","title":"平成２５年度立会川環境美化運動の開催について","agenda":"平成２５年度立会川環境美化運動の開催について","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これはもう１７回目ということなのですが、そもそもの始まりのきっかけは何だったのでしょうか。協働と書いてありますけれども、協働は協働でいいのですが、主体は誰なのでしょうか。１７回されていて、区としての評価はどのように感じられているのかをお聞きします。","respondent":"奥田河川下水道課長","answer":"３点目といたしまして効果等なのですけれども、まさに今回も立会川をやるに当たりまして、地元のほうからぜひ啓発でやってほしいというのでやってもらいますので、区としては非常に効果があるものと考えています。","voiceIndex":63,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"協働というのが難しいなと思っているのは、どこが主体かといったときに、協働とは言いつつも、行政というのは行政側がかなり力が強いですから、これだとやらせ感が出てきたりとかする部分が出てきてしまうのですよね。ただ単に手を引いてはいけないし、でも、かかり過ぎると、結局やらされ感が出たりということで、その辺の考え方というかやり方はどういうふうに考えていますでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"これが非常に大きなことだと考えています。まだまだ周辺の方々、理解を求めることが引き続き必要だと考えていますので、こういったことを継続してやる、それが我々に一番重要ではないかというように思って取り組んでいるところです。","voiceIndex":65,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"それぞれの立場で努力されているというのは非常にわかります。だからこそなのですけれども、やはり原点にいつも立ち返っていくべきところが必要かなと。住民主体でいろいろお世話になっていってありがたいと思っているのだけれども、もっと進めていきましょうということは常に言っていかなければいけないのではないかなと思いますので、要望等含めて、考え方をもう一度お願いしたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"そういった輪が少しずつ広がっていくことが川の近隣の方を含め、少し周辺を取り巻く方々にこの意識を持っていただく、そういう形になってきていると思いますので、これを引き続き継続してやっていきたいというふうには思っているところです。","voiceIndex":67,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に私の思いなのですけれども、要は褒めてほしいと思うのです。ごみってそんなにないですよね。なので、やっぱり、こういう活動が地道に働いている部分なのかなと思うので、そこはやっぱり評価の部分で区側からまず、誰でもいいですけれども、よくなりましたねというのを聞きましたとかということでもいいので、ぜひ啓発活動の中で取り入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問・要望","question":"この立会川の環境美化運動は非常にすばらしいと思います。それが小学校なり地域に広がっていくことを通して、結果として立会川がきれいになっていくわけだから、私はこういうものをぜひもっと進めていっていただきたいと思います。確かにそういう一面もあるのかもしれない。それは否定できないかもしれない。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-032"}]},{"id":"topic-04","title":"品川区国民保護計画（本冊および資料編）の配布について","agenda":"品川区国民保護計画（本冊および資料編）の配布について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"内容を伺おうかなと思ったのですが、２月２６日に報告があったということなので、結構いろいろな箇所の変更があったのでしょうか。","respondent":"鈴木防災課長","answer":"以前の修正前の計画では、ここにＪアラートの開発検討を踏まえて、区でも必要な体制を備えるというような予定の記述がございました。ところが、Ｊアラート自体が平成２１年度からもう区のほうで導入しておりますので、そこの部分を削除しまして、後ろの７７ページをご覧ください。","voiceIndex":75,"id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"そういった意味ではすごく、何というのでしょう、防災無線の内容に地方自治体が関与できない。だから、平穏な町が、この有益に機能するときはいいのだけれども、そうではないときにはすごい重大な影響を与えるということにおいて、防災のＪアラートが発信する部分で、何というのですか、地方自治体がチェックできたりとか、そういう機能というのは今の時点ではないのですか。","respondent":"鈴木防災課長","answer":"ご質問の誤報とか、それから自然災害についての対応ですが、自然災害につきましては、申しわけありません、さっき例示に入れなかったのですが、自然災害については、もちろん、Ｊアラートの対象になっております。","voiceIndex":77,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"意見","question":"何もないことを願っているのですけれども、使い方によっては国からの一方的な発信をふせぐことができない状況にあるということにおいては、私たちとしては有事法制とかに反対していますけれども、流れてくる情報、やはりきちんと注視をしていきたいと考えています。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"いろいろとまとめられているなと思うのですけれども、これの配布予定がここに書いてあります。これ、はっきり言って理解が難しいですね。多分、これが広報がしてから、いろいろ実際個別のもつくられたのはわかっているのですけれども、果たして住民の皆さん、区民の皆さんが知っているかなと思って、知っていないのではないかなと思うのですが、その辺はいかがですか。","respondent":"鈴木防災課長","answer":"この国民保護計画の中身もしくは区民の方の対応についての周知というご質問ですが、まず、この計画自体が委員からもお話がありましたように、区とか行政サイドでどのような対応をして国民の方を保護するかという観点ですので。","voiceIndex":80,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"なかなか緊急事態ですので、迅速にということで、特にＪアラートについては全国的にも有名、知れ渡っておりますし、実際使われているということもあって、ただ、何ですか、北朝鮮等々近隣の国の動きもあると、ただ、遠い、関係はしないだろうと思ってもわからないのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-037"},{"speaker":"伊藤委員","kind":"意見","question":"中身のことになるかもしれないけれども、この中に、この計画の中に品川区議会の役割なり責任が一切触れられていないのですよ。議会のほうが自主的にそれを決めていく話なのかもしれないけれども、だけれども、この保護計画の中に議会の立ち位置がどこにも示されていないというのは何となくしっくり来ないので、品川区のお考えをお聞かせください。","respondent":"鈴木防災課長","answer":"この計画に関して区議会との関係性、役割というお話ですが、先ほど申し上げましたようにこの国民保護計画自体は区の責務なり対応、そのための体制を規定するものでございまして、確かに議会の役割とか区との関係についての記載が今は入っておりません。","voiceIndex":83,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると、国民保護計画には掲載できないけれども、地域防災計画に準じた本部がつくられて、地域防災計画上の中では議会の位置づけがあるという判断ですよ、今のお話だと。それで、ちょうど議会の見直し、こちらの話ですけれども、議会のあり方検討会でさまざまな議論を重ねてきた中で、区議会議員として大災害時にどうするか、行動するかというのも、ここまでで言うと確認できています。","respondent":"鈴木防災課長","answer":"ただし、地域の方との大事な、区と地域の方との大事な連結器といいますか、仲介をしていただく役職の方ですので、区からの情報提供なり、それから議員の皆様がお知りになった地域の情報等については、本部で区議会事務局が議会対応の部隊になりますので。","voiceIndex":85,"id":"exchange-039"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、今の段階でできることというのは、やはり、ある種のこういった緊急時の啓蒙的なことなのかなと。ですから、こういったものができてきて、一般は読まないよというかもわからないけれども、行政側としてはやらざるをえない、いろいろしていかなければいけないというその辺の担当者レベルのご苦労とか大変さ、それと啓蒙活動、この辺についてご意見があればいただきたいのですけれども。","respondent":"鈴木防災課長","answer":"ただ、それは仕事ですので、それで、では、実際に啓発のほうですが、先ほども申し上げましたように、例えば、９月１日の広報の防災特集であるとか、それからＪアラートの試験だとか、機会があるごとにＪアラートについてのお知らせもしておりますが。","voiceIndex":87,"id":"exchange-040"},{"speaker":"原委員","kind":"質問","question":"すごく大変なポジションだと思います。本当に２４時間体制で連携をとっていかなければいけませんし、ラジオなんか、この間は祭日の日に急に入ったものですから、あれ、これはまた地震かなと思ったら、それが選挙へ行ってくださいという、そういうような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-041"}]},{"id":"topic-05","title":"の３、「行政視察について」","agenda":"の３、「行政視察について」","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"それからこれは北海道ですから、同じように北海道も防災対策基本条例、改正をされていますので、これもやっぱり３.１１以降ですね。そういうふうなことがあって変えているというようなことを確認できましたので、いろいろなことを勉強していきたい、提案であります。だけれども、一応案として提案します。函館から約１０時間とか、というところにありますので、本当に山の中にある水族館なのですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"提案","question":"小平市。一つは小田原市。なので、一致できるところもあれば、宿泊をしなくても行ける距離のところでもいいのかなという提案をします。震災のところも、今の時期なのでとても大事であるなと思って受けとめたのですが、できたら大都市のところ、大阪とか名古屋とか、東京都と似たような首都圏のようなところの対策を学んでみたいなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-043"},{"speaker":"原委員","kind":"意見","question":"私もこの際、密集市街地とかその辺を考えたり、それから震災のほうの関係とやっぱり似たところで、類似したところで行きますと大阪市、大阪なのかなという感じがしております。新橋ですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-044"},{"speaker":"こんの副委員長","kind":"意見","question":"そうしましたら、今回の所管事務調査に入りました空き家対策というところ、これは地方と近隣区のほうが参考になるものが多いかなと思うのですが、それでも、地方のほうでこうした対策がなされているところがあれば、参考までに。","respondent":"あべ委員長","answer":"空き家と。幾つかの考えが挙がってきました。まだそれではここに決めましょうという段階にはないかなとは思うのですけれども、まずは皆さんの出していただいたご意見をもとに正副でお話をさせていただきたいと思います。","voiceIndex":100,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"質問","question":"思いなのですけれども、東日本大震災の被災地、前は行けなかったのですけれども、もし向こう側に余裕があれば、だからそういうことを、あれだけのことを経験されて、当該自治体が当然新たな災害対策条例等つくっているでしょうから、どういうふうに危機管理をもって対処していくのかということが今非常に勉強しに行く価値はあるのではないでしょうかという思いがあるのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"私の郷里であるいわき市も水族館再生という形で、水族館、これは震災関係ですけれども再生したというところもあるので、あそこは完全に再生しましたから、そういうところは参考になるのかなと思うのですが、ただ、地区全体を見ると、全然出来ていないので、そこに行っても逆に圧力を、変な話を言うようですけれども、何かそんな、何となく逆効果みたいな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4078#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":37472,"voices":111}},{"id":"h25-20130702-9","meetingId":"h25-cm07","date":"2013年7月2日","dateIso":"2013-07-02","committee":"文教委員会","time":"午前１０時００分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２６年度新入学者の取扱い","agenda":"の平成２６年度新入学者の取扱い","exchanges":[{"speaker":"南委員","kind":"質問","question":"３５人学級になっているということと、中学生についても３５人学級の編成で組むということになったのは本当によかったなと思います。それで、今の説明では、学級増によらず、教員の加配というところも選択可能だという話ですが、学級増したところ、加配をしたところというのは、小・中学校それぞれ何校ぐらいになるのか、それを１つ伺いたいと思います。","respondent":"和氣学務課長","answer":"小学校はもう３５人で決まっていますので、中学校が柔軟に対応できます。中学校ですが、今年度、平成２５年度入学でいいますと、４校が学級規模縮小以外ということで、教員の加配をいただいております。２校が学級規模を増やしているという実態です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"それで、先ほどの説明では、できるだけ希望者を受け入れたいということで、そういうふうに配置をしたという話で、それはそれとして、保護者やお子さんの立場からすると、よかった、やれやれということになるんだろうと思うんですけれども、日常的な教育を受ける、授業に参加するという点で、できるだけ３５人に抑えられるような学級構成であってほしいと私は思っているんです。","respondent":"和氣学務課長","answer":"そちらのほうが自分の学校の教育方針には合致している、ということで選択したものです。いろいろな、多様な教育の形態がありますので、それぞれの学校の方針に従って選択できますので、選んだです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"確かにフリーの教員がいたほうがいいと思います。しかし、できるだけ教師の数が、子どもに触れる大人の複層的な数が大きいほうがいいに決まっているわけですから、もっと教員の数が増えていけるような方向になっていってほしいという思いを込めて、ちょっと質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"(3)、一番下の学区域内の希望者が受け入れ可能学級数を超える場合は、抽せんをすることなく全員を受け入れるということなんですが、住民登録上、何校ぐらいが当てはまるのか、教えてください。","respondent":"和氣学務課長","answer":"次の荏原西ブロック１番の京陽小学校も同じですが、これは住民基本台帳上の数字を見て、京陽小学校は何とかなるかなと思っているんですが、芳水小学校のほうは、数字をしっかり見て判断をさせていただきたいと思ってあります。","voiceIndex":13,"id":"exchange-004"}]},{"id":"topic-02","title":"平成２５年度品川区におけるいじめ対策","agenda":"平成２５年度品川区におけるいじめ対策","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ＨＥＡＲＴＳのところについて、事務事業概要の対策が今年度改めて盛り込まれたので、そこといろいろ比較しながらこれを見ていたんですけれども、今の説明も、私が聞き逃してしまったのかもしれませんが、ＨＥＡＲＴＳのところで、こちらの事務事業概要では、３名の教育心理相談員と書いてあるのは、ここの図でいうと、弁護士、精神科医に当たることなのかなと、それは１つ教えていただきたいのと。","respondent":"渋谷指導課長","answer":"通常の電話とちょっと音色の違う電話を設定して、今ご説明した教育心理相談員がその電話に直接対応し、子どもたちから電話がかかってきたり、いじめに関する保護者からの相談に対応できる体制を、９時から５時という時間帯で実施しています。","voiceIndex":21,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"３名のところは、スクールカウンセラーということでわかりました。それから、チャイルドラインというのがありますけれども、あれは２４時間体制のもあったと思うんですけれども、必要性があって、そういう体制を敷いていると思いますので、区でもそのあたりはしっかりと検討していただきたいと思っていますので、その点についての見解を１つ伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"子どもの成長途上で、いじめというのはだれにでも生じ得るものであるということの中で、教育の営みとしていじめというものを解決するということが大事だと思うので、そういう角度から、法律で禁ずるとなっていることについては、そっくりそのままを品川区の教育行政におろしてくるというのは、ちょっと慎重に検討して、対応していただきたいと思っていますので。","respondent":"渋谷指導課長","answer":"品川区の子どもの実態、地域の実態に応じて、さらにさまざまな施策に取り組んでまいるです。","voiceIndex":27,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"それは１つの方策としてですけれども、教師の方々が、子どものいじめの問題にどう取り組もうとしているのかがここでは見えないので、あるのであれば、ここの部分がそうなんですという指摘をしていただきたいと思うし、それはしっかりと明らかにさせていくことが、対外的にも、父母の皆さんにも、社会的にも、ああ、そういうふうにやっているんだということが見える、そこが大事だと思うので。","respondent":"田村教育次長、渋谷指導課長","answer":"ぜひそういうふうにご理解いただかないと、何かあるのではないかというやりとりを延々とやっていても、正直これ以上何も隠してもいないですから、全て調べて、アンケートをとって出しているということで、当然ご遺族の気持ちに沿って。その中では、先ほど委員からもお話がありましたように、情報共有の場を各学校それぞれの仕組みの中で位置づけたり、校長による全員面談を実施するですとか。","voiceIndex":29,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"どこなんですか、というのをまたちょっと聞きたいと思います。事実そのとおり、でないと、委員ですから、あり得ない話ですものね。あの新聞を読んだけれども、今はどうなんですかとか、本当に知りたいところ、あの新聞ではそういうふうに書いてあったけれども、どういう思いなんでしょうかということを、むしろ聞くべきだと私は思うんです。その辺について、最後にしっかりと伺いたいと思います。","respondent":"田村教育次長、渋谷指導課長","answer":"ですから、教育委員会にまた追加でアンケートをしてほしい何とかという話がご遺族からあれば、それはそういうことで話せるように協力させていただきたいと思っています。いじめ対策のＡ３判の資料のどこにそれが該当するのかですが、各学校個別の取り組みについては、こちらには記載してございません。","voiceIndex":32,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"そういうふうになっていれば、新聞の取材でああいうふうに書いているというのは、今の次長のご答弁では、何か、ああ、なるほど、そうだったのかとはリンクできずに、思いがちょっと残ってしまいますので、ご遺族としてのつらい気持ちというのを、それはそれとして受けとめて、新聞社はどういう意図があって、ああいうふうに書いているか、それはわかり得ないところですから。","respondent":"田村教育次長","answer":"だけれども、それに書いてあるのが、ええ、どうして、と。もともとマスコミに対しての対応も聞いている話と違った。だけれども、それをここでやりとりしてもしようがないので、大変申しわけないですけれども、同じ話の繰り返しになるので、ぜひご理解いただきたいと思います。","voiceIndex":35,"id":"exchange-010"},{"speaker":"本多委員","kind":"意見","question":"スクールバディ・プログラムの中では、学校の対応という、学校の先生ももちろんやるべきことがありますが、その前に、子どもたちの中で、そういうことに遭遇したときに、ここにはＨＥＡＲＴＳのそれぞれの書いてあるところも全部同じ趣旨だと思うんですが、勇気を持って本当に助け合えるのかというところを、その辺をどうしっかりと植えつけていけるのか、その辺についてお聞かせください。","respondent":"渋谷指導課長","answer":"なかなか難しいご質問ではあります。実際、このプログラムは４回のワークショップを通して、いじめは許されないという定義について理解し、加害者としてはどんなイメージなのか、その背景を考え、また、３回目には大切な自分自身と向き合って、自尊感情を高める。","voiceIndex":37,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"ＨＥＡＲＴＳということで、大変注目もされていると思いますし、初めての取り組みであるので、今いろいろ試行錯誤しながら、取り組みをされているんだろうと思いますけれども、一応この７月、今日は２日ですけれども、これまで専用電話と目安箱と６月から開始しましたアイシグナルという３つのチャンネルで、どれぐらいの事案、案件が寄せられてきているのか、それをちょっと教えていただけますか。","respondent":"渋谷指導課長","answer":"アイシグナルにつきましては、６件のうち、２件が同一の人物で、この子については、名前が書いてありましたので、ＨＥＡＲＴＳからお手紙を出して、本人確認をして、ＨＥＡＲＴＳの人間が面接をするという対応をしております。","voiceIndex":39,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"それはもちろんプロの方たちですので、十分な配慮をされながらやっていらっしゃるとは思うんですが、一応その辺の対応の、前に出るべきなのか、ここは様子を見るべきなのかというところは、ＨＥＡＲＴＳの中でどのような形で意思決定というか、決断をされているのか、その辺だけちょっとお伺いしたい。","respondent":"渋谷指導課長","answer":"すぐ助けてほしい、話を聞いてほしい、学校に見にきてほしい、友達を助けてほしい、先生に伝えてほしい、家の人に伝えてほしい、詳しく話をしたいので自宅に電話をかけてほしい、まだ先生には内緒にしておいてほしい、まだ家の人には内緒にしてほしい。","voiceIndex":43,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。ちゃんとケアされていると思うんですが、一応確認でそこだけ話していただきたい。","respondent":"渋谷指導課長","answer":"今回、個人情報の管理については、ＮＰＯ法人ときちっと書面で管理するということで取り交わして、情報の守秘の徹底を図っているところです。","voiceIndex":45,"id":"exchange-014"},{"speaker":"高橋委員","kind":"質問","question":"今これまでのいろいろな相談というんでしょうか、通報のお話があったんですが、アイシグナルについては、地域の方々からの相談も重要なポイントであると思うんですが、そちらに説明等をされたと思うんですけれども、そのときの地域の方々の反応というんでしょうか、協力度合といいましょうか、そういったことはいかがだったのかということで、今の通報の中には地域の方はなかったみたいなんですけれども。","respondent":"渋谷指導課長","answer":"１点目のアイシグナルの地域の方の受けとめですが、現在３つの地域健全育成運営協議会に指導主事が行ってご説明を差し上げているところです。","voiceIndex":47,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"アイシグナル、先ほども地域関係の方にお配りしてということだったんですが、地域の方、関係者というのはどういった方にお配りして、それでどういった地域の方の役割、先ほどちょっとありましたが、もう一度伺いますが、地域の方にどういうふうに対応していただきたいとか、これを見て、今後この地域でいじめというのを捉えていっていただきたいのかという方向性を教えていただきたい。","respondent":"渋谷指導課長","answer":"目安箱の扱いについては、校長会ともさまざまな意見交換をさせていただいて、実際の学校数とＨＥＡＲＴＳの指導主事の人数等々から勘案して、各学校に回るのは、２週間に１遍ぐらいだったら、全部の学校を回ることが物理的に可能だろうというところから。","voiceIndex":50,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"ありがとうございました。目安箱も穴をあけて確認ということで、先ほどのアイシグナルのほうでもありましたが、そこから特定されたり、抜かれたりというのがないようにだけ気をつけていただきたいと思います。アイシグナルのほうなんですが、その地域で、先ほどおっしゃっていた方々以外でも、例えば、野球関係だったり、サッカー関係者への配布というのは可能なんでしょうか。","respondent":"渋谷指導課長","answer":"それぞれ地域の実情もありますでしょうから、例えば、少年野球やサッカーが盛んな地域だったり、そういった地域の実情については、また地域の方とご相談させていただきながら、配布対象については検討させていただきたいと思います。","voiceIndex":52,"id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"地域においても、子どもをみるほかのいろいろな目というのがあると思いますので、クラブ活動以外でも、地域のスポーツ団体だったり、通っているところであったりというところにも、もしできるなら声をかけて、できるだけ子どもの変化というのを地域でも見守っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"いじめ根絶協議会のさっきの説明では、中学校区ごとにとおっしゃっていたと思うんですけれども、たしか中学校区ごとに地域健全育成運営協議会があると思うんですけれども、そことの関係をもう一回教えてください。","respondent":"渋谷指導課長","answer":"地域健全育成運営協議会は年間３回程度開催してくださいということをお願いしております。そこに必ずいじめについてのテーマを取り扱ってくださいということで、中身というか、メンバーと会そのものは同一のものです。","voiceIndex":55,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"もう一つは、さっきもちょっと質問して伺って、各学校の教育過程を出していただいている、そこにいじめ対策もきちんとした計画を出してもらっているという話なので、それはそれとして受けとめたんですけれども、私は、できるだけ教師と子ども・生徒が一緒になって話し合える場を、学校の中でたくさんつくっていくことが大事だと思うので、１つは自治能力を育てるという活動を通して、みんなの認識として。","respondent":"渋谷指導課長","answer":"中学校区いじめ根絶協議会と品川区いじめ根絶協議会の関係ですが、今ご説明申し上げた中学校区いじめ根絶協議会は、各中学校ごと、八潮で行われている地域健全育成運営協議会、それぞれが１５の中学校で行われるです。","voiceIndex":57,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、改めて新聞報道との関係で非常に心配した、そういう心配に対して、情報を提供していただけていなかったからわかり得なかったと、私は情報不足として言われてしまえば、それはそれまでなんですけれども、そういう思いがあって、心配があって質問をさせていただいたところなので、それは要望も含めて、公表していただける部分は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-021"}]},{"id":"topic-03","title":"子育て交流サロンの開設","agenda":"子育て交流サロンの開設","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"したがって、月３回ということよりも、むしろ常設してできるような取り組みが必要ではないかと私は思っているんですけれども、そのあたりのことと、それから、ほかに品川全体を見て、とりわけこの２カ所なんですけれども、今後の考え方というんですか、子育て交流サロンの設定について、今後どういうふうに見通していこうとしているかという計画、予定みたいなものがもしありましたら。","respondent":"伊崎子育て支援課長","answer":"品川区全体を見ましたところでは、現在のところ、児童センターのこういった機能が不足しているのはこの地域であるということで、荏原と大崎の地域でやっと開設をいたしました。ほかにもこういうお声が上がってくれば、またそこで考えていきたいと考えています。","voiceIndex":66,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"これは要望ということで、答弁はいいですけれども、これからの子育て支援計画の中でしっかりと位置づけていただきたいということをちょっとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-023"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"大倉委員","kind":"質問","question":"今回、給食食材の放射能検査が前年度と変わったところがあるというお話だったので、そのことについて、ちょっと詳しく教えていただければと思います。","respondent":"和氣学務課長","answer":"保護者の方に安心していただくため、学校は学期に１回、保育園は年３回の頻度で検査を実施しております。流通段階の検査体制も強化されていることから、測定回数を増やすつもりはございません、という答弁をさせていただきました。","voiceIndex":72,"id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"給食食材の検査のフォロー質問なんですけれども、私どもの会派としては、給食食材の検査はもちろん回数を増やして、年５回をさらにもうちょっと広げてほしいということと、１週間分まとめての検査ではなくて、できるだけもっとタイトな状況でやっていただきたいという思いは私自身もあるし、食べてしまったものを測定するというのは、なかったんだ、よかったで終わってしまうし。","respondent":"和氣学務課長","answer":"それ以外のことについては、こちらでお答えできる範囲ではございませんので、よろしくお願いします。","voiceIndex":79,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、できるものとできないものがあるし、１回そういうふうに仕入れたものについての測定をすればその後は測定しなくていいという、仕分けも含めて、大変な作業になるかもしれないけれども、できるだけそういう要望にこたえていただくということが、１つ安心感、信頼を区民の間につくっていけることになると思うので。","respondent":"和氣学務課長","answer":"そのことによって、安全を確保していきたいと考えております。","voiceIndex":81,"id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"私の認識が違ったら、訂正しなければいけないと思いますけれども、例えば、さっき多古町とおっしゃったけれども、八ヶ岳の農場という言い方をしていいと思うんですけれども、そこからジャガイモだとか、タマネギ、私の認識ではそういうふうに思っていたんですけれども、そこで一定程度の量を一括に仕入れて使っているんじゃないかと思っていたんですけれども、各学校への配達そのものは。","respondent":"和氣学務課長","answer":"八ヶ岳のほうもしっかりと自分たちで検査をしていただいていますので、そういう意味でいえば、生産地でしっかり検査をしていただいてというのが、今確実な方法になっていると考えています。","voiceIndex":83,"id":"exchange-027"},{"speaker":"本多委員","kind":"質問・要望","question":"昨日決定しました所管事務調査の項目を充実するべきじゃないかなと。それが１つの考えで、都市とか、そういうのはまだそこまで考えなく、所管事務調査を充実していただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-028"},{"speaker":"塚本委員","kind":"提案","question":"案として幾つかありますので、一応提案をさせていただいて、ご検討いただければと思います。１つは、病後児、病気が終わってから回復期にある子どもたちの保育のケアセンターをやっているということで、太宰府市です。それから、発達障害の方などのインクルーシブ教育での取り組みをされている多治見市の３つを提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-029"},{"speaker":"南委員","kind":"意見","question":"品川区の行政との乖離というのをわりと感じていたんです。だから、今日そういう思いもあって、どこという用意は全然してこなかったんですけれども、日帰りで近場に行って、大いに研究することはやぶさかでないですけれども、どうなのかなとすごくいつも思ったりして、現実的にそういう場面もあったので、そんな気がしました。ちょっと発言だけしておきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4796#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":34035,"voices":98}},{"id":"h25-20130702-5","meetingId":"h25-cm07","date":"2013年7月2日","dateIso":"2013-07-02","committee":"総務委員会","time":"午前１０時００分～午後 １時５９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４５号議案、平成２５年度品川区一般会計補正予算","agenda":"第４５号議案、平成２５年度品川区一般会計補正予算","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１０ページなのですけれども、衛生費補助金が、補正額のマイナス８,１３１万６,０００円になっているのですけれども、これは予防接種が任意から定期になったことで、東京都の補助金はなくなるのでしょうか。任意から定期になることによって財源の流れがどうなるのかについてお聞かせください。","respondent":"本城企画財政課長","answer":"国の制度移行に伴う説明としては、住民税の年少扶養控除廃止等によって税収が増えた分等も含めて財源に充てることによって、基本的には一般財源化されたという、そのような位置づけの中の今回の東京都の補助金の削減です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのことが１点、確認をお願いしたいのと、それからもう一つ、その下の繰越金の基本的なところで教えていただきたいのですけれども、補正額が３億１,７９８万５,０００円ということなのですけれども、この補正額はどこから生み出されたものなのかをお聞かせいただきたいと思います。","respondent":"本城企画財政課長","answer":"繰越金につきましては、当初、補正前の額に２４億円と書いてありますが、今回、当初予算の中では２４億円の繰り越しを見込んでいたところですが、最終的に補正を組む段階で、平成２４年度の年度を終了した段階で、一定額の不用額がある中で特別区税等も増収された。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平成２４年度の不用額から、今回必要なお金は生み出すことができるということで、ここの補正額に充てたということなのですけれども、そうすると、不用額はまだ確定はしないけれども、もっとたくさんあるという考えになるのか、そこら辺はおよそどれぐらいというのはあるのでしょうか。","respondent":"本城企画財政課長","answer":"先ほどのご説明が少し言葉足らずだったかもしれないので、不用額を充てるということではなくて、新たに当初予定していた２４億円よりも繰越金として充てられる財源が出てきた要因の１つとして、平成２４年度、１年間を通して見たときに出た不用額が歳出部分では減って、一方では。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"わかりました。もう一つ、１５ページの教育費の学校教育費ですけれども、これも労務単価の関係で組まれたものだと思うのですけれども、このお金は一般財源ということなのですけれども、これは学校の施設にかかわることですけれども、後で国から戻ってくることはないのか、そこのところを教えてください。","respondent":"本城企画財政課長","answer":"今回の補正額です２８３万５,０００円につきましては、一般財源を充てるもので、これが後から国から戻ってくるとか、そういう関係ではございません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、労務単価の引き上げは、どんなものであっても一般財源で賄うということになるのか、そこら辺の仕組みを教えてください。","respondent":"本城企画財政課長","answer":"今、学校建設費の中でのご説明で一般財源ということでご説明させていただきましたが、それに対応する歳出の中においては、当然、補助金等が含まれるということもありますので、労務単価だからということではなくて、今度、学校建設費のこの豊葉の杜学園の今回のこれについては。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２つ教えてください。１つは、先ほど、子宮頸がん等の予防接種で一般財源化すると、それは区長も国に負担を求めていく、それは一般財源ではひどいだろうというような話があって、それを求めていくというのはいいのですが、そっちはそっちで置いておいて、それで、今のお話だと、交付金が我々特別区は財調だと。今の話だと、担保はないように聞こえたのです。それが上がるのか。","respondent":"本城企画財政課長","answer":"労務単価の関係ですが、基本的には今回の労務単価の改定を受けて、いろいろ公共工事をやっていくわけですが、基本的には、先ほどご説明させていただいた中で、この工事については労務費については一般財源で充てるけれども、ただ、歳出の種別によっては。","voiceIndex":17,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"財調のパーセントは変わらないのであれば、特別区の中で調整しても、児童相談所の問題も何もいろいろなことがあるのだろうけれども、どんどん区が受けていくけれども、結局、区の財源は、やることだけ増えて金は来ないみたいな形で、２３区がどれだけ耐えられるかみたいな話をしてもしようがないわけで、だから、そこら辺のところはぜひ踏まえて、課長会でも言っていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"賛成です。その理由ですけれども、区民委員会でオリンピックの問題で、オリンピックは賛成なのですけれども、税金の使い方としてこれは問題があるということで反対をしたのですけれども、全体の予算としては、予防接種の定期接種化ですとか、労務単価の引き上げということで、積極的な予算だということで評価をしますので、ここでの予算全体の態度としては賛成することでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-008"}]},{"id":"topic-02","title":"債権の放棄","agenda":"債権の放棄","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"今、説明を伺いました。５５カ月でこの金額ですと、最低、月２０万円近くになるということで、不正受給という言葉が出てきたと思いますが、今になって言うのもあれですけれども、途中でそういう状況は、確認と言うとおかしいですけれども、発見することは難しかったのかなというところだと思うのですけれども、もしそのところで情報等があれば教えていただきたいと思います。","respondent":"久保田会計管理者","answer":"東京都が実施した監査によってそういうような問題のある状況がわかったということで、区としては、サービスを受けることでなかなかそこまでは立ち入った形での調査はできていなかったです。","voiceIndex":35,"id":"exchange-009"},{"speaker":"浅野委員","kind":"意見","question":"サービスがスタートして４年たってから都が監査したということですけれども、こういうことについては、なかなか立ち入った調査は難しいかもしれませんけれども、ある意味、対応もそうでしょうけれども、心していかなければならないのかなという気がいたしました。やはりこれだけの金額がある意味不正に使われてしまったのは残念なことではあるけれども、手続上はやらざるを得ないというところだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう少し詳しく教えてほしいのですが、４年目に気がついて平成２０年７月までの５５カ月間だと。破産が平成２５年１月１０日だと。その間はどういう形の対応をされていたのでしょうか。返還を求めていたのだと思いますが、その間が、気がついてからの、平成２０年７月からそれだって４年半ぐらいあるわけで、その４年半はどうされていたのでしょうか。","respondent":"久保田会計管理者","answer":"もう少し経過を詳しく説明しますと、監査の後なのですけれども、これだけの不正を発見したということから、東京都は翌平成２１年１月１９日にこのサービス指定事業者の取り消しを決定しております。ですから、監査から約１カ月後にはそういう取り消しをしたです。","voiceIndex":38,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今までの総務委員会の報告がわからないので、基本的なことを教えていただきたいのですが、これは品川区が持っていた株を東京急行電鉄株式会社に譲渡するという今の説明だったと思うのですけれども、品川区はもともとどれぐらいの株を持っていたのか、それから、ケーブルテレビの株はほかに持っているところがあると思うのですけれども、どこがどれぐらいずつ所有しているのかというところを教えてください。","respondent":"柏原行財政改革担当課長","answer":"２点のご質問です。品川区の保有株数ですけれども、この譲渡前の状態は、品川区は１万３,５００株の株式を所有してございました。それから、ほかの部分につきましては、品川区以外ではこの４月１日以降ということでよろしいでしょうか。","voiceIndex":45,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私も、ここら辺はよくわからないのですけれども、品川区が持っていた株１万３,５００株を１万株譲渡して、では今、残りは３,５００株になるのでしょうか。そこら辺で、ケーブルテレビへの品川区の株の持ち分にかかわっての影響はどうなるのかについてもお聞かせください。","respondent":"須藤委員長、柏原行財政改革担当課長","answer":"今までの経緯をお話ししないと、ケーブルテレビの株を譲渡したのだけれども、今までと同様の仕組みをとっているとか、そういうのを説明していただくとわかると思うので、よろしくお願いします。ただ、３,５００株のもとの株式はまだ今も持っておりますので、地域メディアというところがありますので、地域メディアと自治体は深いつながりがあって、自治体側も発言力がありますし、それから。","voiceIndex":49,"id":"exchange-013"}]},{"id":"topic-03","title":"品川区長期基本計画の中間見直し","agenda":"品川区長期基本計画の中間見直し","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この資料Ｎｏ.７なのですけれども、いろいろと広域にわたって書かれて、資料もそれぞれに出されているのですけれども、そうしますと、品川区の現況と中間見直しにおける論点ということで書かれているのですけれども、これはどういうふうにつくられたのかということをお聞きしたいのですが、各所管でこれを作成したということでいいのでしょうか。この点をお願いします。","respondent":"黒田長期計画担当課長","answer":"資料につきましては、長期基本計画の改訂委員会の資料ですので、事務局側の企画部が長期計画担当ですので、こちらで素案をつくりまして、各所管と調整して作成したものです。","voiceIndex":57,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"例えば、介護保険などにしても、認知症高齢者がすごく強調されている状況なのですけれども、区民の状況で言えば、私は特別養護老人ホームの申し込みがどれぐらいあって、どれぐらいが入れているのかとか、そういう区民の切実な実態がわかるような資料もすごく必要なのではないかと思いましたし、その前の健康づくりにしても、特定健診の受診率の向上がすごく取り組まれてきたところだと思うのですけれども。","respondent":"須藤委員長、黒田長期計画担当課長","answer":"今のご意見があったので、そのあたりを承知しながら答えてください。その他、庁内でも区政モニターアンケート等、資料を取得しまして、今回お示ししたのはあくまでも長期計画策定以降の経済環境の変化がこうなっているということを長期基本計画の基本方針、２４面あるのですが。","voiceIndex":59,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"中間の見直しで、これはこれで委員会も立ち上がって、ぜひしっかりやっていただきたいと思いますけれども、物事の考え方として、やはり今、施設をつくるなり対応をするなり何なりすると、必ず１０年後、２０年後が来るわけで、そこにまた費用がかかるものもいろいろ見えてきたり、いろいろあるわけですから、そういうものも踏まえた、そこら辺の先まで見込んだ中間の見直しみたいな議論は必ず。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-016"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"できましたら、品川区と同じような人口密度、規模、それから産業、その他を含めまして、類似したところに行かないとなかなか勉強という形に、我々としてもさまざまなことを勉強して、またこれからいろいろ議論を重ねていくと思うのですが、遠方に行きますと、そこの自治体でそれぞれの苦労はよくわかるのですが、なかなか参考になりにくいこともありますので、その辺はぜひ委員長、副委員長。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も、どこにという要望を出していないのですけれども、視察は２泊３日に限らなくても、例えば日帰りとか、そういうところも検討しながら、２泊３日で行くことを決めずに、何を見たいかというところから議論して、私は公契約条例をやっているところの都市、自治体に視察に行けたらいいと思っているのですけれども。","respondent":"須藤委員長","answer":"契約については、今回、行財政改革特別委員会で視察等も考えているようなので、総務委員会としては余り行財政改革特別委員会とぶつかってしまうと、また今年度から各常任委員会も議長にまとめを出していくということで。","voiceIndex":70,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1952#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":20342,"voices":78}},{"id":"h25-20130703-14","meetingId":"h25-cm07","date":"2013年7月3日","dateIso":"2013-07-03","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山元委員長","kind":"提案","question":"前回の委員会において、皆様からいただきましたご意見・ご要望を踏まえ、先日、理事者の意見も伺いながら、正副委員長で調整をさせていただきました。以上、調査事項の項目につきまして、区の動向等を踏まえて、適宜、各委員の意見・要望もお聞きしながら、柔軟に進めていきたいと考えております。今期１年間、このような形で進めさせていただきたいと思いますので、どうかよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":1,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"今の委員長の説明は、それはそれとして伺ったのですけれども、しかし、長かったし、それから４項目について、いろいろ細かく正副で調整していただいた結果だという気持ちで聞いていたのですが、なかなかメモもとりにくかったので、ボリュームにもよりますけれども、できたら事前にいただきたかった。よろしくお願いします。","respondent":"山元委員長","answer":"確かに、聞いていて、私は読んでいたからわかりましたが、確かにそうかなとは思いますので、この辺、正副でちょっと検討させていただいて、わかるような形、またどのようにしたらいいかを検討しますので、お時間をいただきたいと思います。よろしいですか。","voiceIndex":2,"id":"exchange-002"},{"speaker":"あべ委員","kind":"質問・要望","question":"今の件なのですけれども、ご検討いただけるということで、お任せしてもいいのかなと思うのですが、やはり今のペーパーをできるだけ早いうちに手元にいただきたいと要望します。","respondent":"山元委員長、柏原行財政改革担当課長","answer":"申しわけありません。お二方のご意見をいただきまして、十分に検討させていただいて、なるべく意に沿えるように頑張りたいと思います。そのほかにご意見はいかがでしょうか。ないようですので、先に進めさせていただきたいと思います。それを受けまして、昨年１１月末ですけれども、これに基づいたコスト比較等と個別検討を国で行いまして。","voiceIndex":6,"id":"exchange-003"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"私は６月７日付の東京新聞に、今説明されたような内容の趣旨の新聞記事が出ていましたので、保育園の待機児解消策に活用するのであれば、本当に早く手を挙げて区民の要望に応える、そういう結論を導き出してほしいと思っていたのですけれども、回答をもう少し延長していただくことが可能かどうかという問い合わせをするということは、区としては、定期借地権も含めて、この土地を求めていきたいという趣旨。","respondent":"柏原行財政改革担当課長","answer":"国に回答期限を延長してほしいという旨は、先ほど来申し上げているとおりでございまして、待機児童解消対策という新たなスキームということで定期借地権の話、それから保証料は要らないとか、今まで出てこなかった話が出てきておりますので。","voiceIndex":14,"id":"exchange-004"},{"speaker":"南委員","kind":"確認","question":"待機児解消策の保育園、保育事業を行っていくことで検討をしていきたいということで、受けとめていいのかどうかというところをもう一度確認したいと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、先ほど来申しておりますように、地域のニーズであるとか、行政がやらなくてはいけない仕事というところをトータルで考えなくてはいけないですので、保育所という考え方も１つありますけれども。","voiceIndex":16,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"区が出した数としても、平成２３年度に５０人だったでしょうか。５０人、６０人を前後して、この３年間そういう数字が出ているわけです。したがって、保育園１園を建設する程度の待機児が毎年出ているわけです。そういう点で、ぜひ保育所をつくるという方向で検討すべきだと強く求めたいと思います。もう一度伺いますけれども、検討としては、いろいろな需要も含めて検討するということなのですか。","respondent":"桑村企画部長","answer":"そうすると、どういう建物が建てられて、それが果たしてあそこの場所でどう展開できるかというのを検討しなくてはいけないですから、そういう意味では、少し国のほうに待ってくれというお話をさせていただいていますので。","voiceIndex":18,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"私はぜひ保育園をつくってほしいと思っているし、それも１つの選択肢に入れているという話なので、大いに期待したいと考えていますけれども、そこを改めて強くお願いしておきたいというのと、社会福祉施設でもオーケーだという点で言えば、やはり区民の要求に沿った方向できちんと検討をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"今、国に返事を少し先延ばして、待ってくれということを言っているということなのだけれども、実際にあれだけのスペースで、今お話があったように、あそこに建てられるとしたら、限られたものでしかない。何かそういうことがプランにあって、先延ばしているのかという質問です。","respondent":"桑村企画部長","answer":"それは今おっしゃったようにいろいろな高齢者の施設、障害者の施設、あるいはほかの場面で施設展開ができないかということをいろいろ検討してまいりました。その検討の中で、国から定期借地という違う考え方が出てまいりましたので、それを含めるとどのくらいの展開ができるか。","voiceIndex":21,"id":"exchange-008"},{"speaker":"須藤委員","kind":"質問","question":"それよりもっと根本的に、国が行革の一環として、こういった寮を削減させる。私自身は、もともと削減したことによってほかに移れる。我々としても、国に単に待ってくれと言うのではなくて、むしろ活用するためには、無償でよこせという話をしていくべきだと思うのだけれども、そのあたりはどうですか。","respondent":"桑村企画部長","answer":"今回のことも、定期借地というのはいまだに２番目でして、買っていただきたいというのが基本の考えですので、そこのところは十分に交渉させていただきたいと思いますけれども、その中で実際上、期限が来たものについては一定の判断をさせていただきたいです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"ただ、ここにきて新しい条件を示してきたということで、先ほどから幾つか出てきていますが、ちょっとまとめて、どことどこが変わったというのを、もう一度確認させていただけますでしょうか。それと、もし可能であれば、先ほどおっしゃっていた、国の示してきた提示額がお幾らであったのかを教えていただきたいと思います。この２点をお願いします。","respondent":"柏原行財政改革担当課長","answer":"おおむね全体の額の１割とか、そういった金額になるのですけれども、そういったものは不要ということです。これは当たり前の話なのですけれども、先ほど申しました貸し付けをする際には、更地にして国が貸しますということです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"私もこの地域は保育園を増やしてほしい地域であると思っています。そして、そのあいた土地に保育所がつくられるといったようなバランスを見ながらの組み替えということも含めて、ぜひご検討をしていただきたいと強く要望をして、とりあえず質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、具体的な場所あるいは締め切りがあったのですが、その背景の中で伺います。今回、公務員宿舎というくくりで５つ出てきました。これは削減計画で指定されたところ。それ以外に、そもそも公有地全般と考えたときに、国であり都有地でありという中で、今すぐ数字を求めるわけではないのですが、どの程度、割合としてはごく一部だというものだとは推測できます。それをお願いします。","respondent":"柏原行財政改革担当課長","answer":"ただ、それが実際にニーズとか、区の財政的な負担であるとか、トータルに考えたときにどうなのだろうかということで、実際にそれを欲しいということで積極的にとっていくというところまでは、内部の検討レベルといいますか、情報をとる状況です。","voiceIndex":30,"id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問・要望","question":"物事の考え方になってしまうと思うのですけれども、今回はそういう方針が出た、あるいは国の都合の部分で出てきて、順番の話になると思うのです。公と公という、自治体対国という点では、どうしても品川区サイドが受け身のような気がしてしようがないのです。これから、限られた都市部という中では、そういったアプローチがぐっと高まるような気がするのですが、お考えを教えていただきたいと思います。","respondent":"桑村企画部長","answer":"ただ、こういう国有地とか、公有地の話は、今までもそうですが、処分する場合は原則まず自治体へお話が来るという前提がありますので、それも先ほど申しましたとおり、今までは何らかの有利な条件がついて、自治体に来る場合は、半分減額ですとか。","voiceIndex":32,"id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問・要望","question":"最後に、これからの展開の中で、現状を教えていただきたいのですが、それぞれ所管を中心に用地取得等はアンテナを張られていると思います。あるいは折衝能力、そこまで委託してでも効率的な用地取得の方法というのは、現状ではどうなのか。あるいは今後、そういう可能性があるのかどうかだけ、最後にお聞かせください。","respondent":"桑村企画部長","answer":"その意味では、区の職員がなかなかできないようなところを、実際上、本当のディベロッパーではないですけれども、開発をやっているところに組ませていただいて、うまい方法がないか、あるいは共同で住宅を建てることはできないか、そういう形で事業を進めしています。","voiceIndex":34,"id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問","question":"今日、視察も含めて５カ所拝見した中で、前段に早めに資料をいただいた中で、私どもも党内議論、あるいは第三者の民間の方とかとちょっと下話的なものを伺ったときに、やはり用途という意味で限界がある。ただ、政策的な必要性は踏まえてはいるのですが、これはやはりまだ時間延長というものも踏まえて、適切な延長願いというのか、事業を判断されるというのが適切だと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今日、５カ所拝見をさせていただいて、小山台住宅は東京都から公園と一体化といいますか、防災目的での要望が出ているということでありました。先ほどの企画部長のお話の中で、地域のお声も聞きながらということだったのですけれども、今日見た中で、南品川、上大崎、小山台で、もし地域の声を吸い上げているものがあれば教えていただきたいというのが、まずお伺いしたいところです。","respondent":"柏原行財政改革担当課長","answer":"現段階で直接的に何かお伺いをしているというところではございませんけれども、所管等を通して、この地域での行政のニーズであるとか、施設の状況であるとか、そういったところを調査している状況です。","voiceIndex":37,"id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"小山台住宅については、先ほど各委員からもありましたけれども、私も拝見させていただいて、いわゆる地域の方が避難をする際の動線確保という意味で、一体化の整備という考え方もうなずけるところがあったものですから、その中で、これは会派というよりは私の個人的な考え方ですけれども、１つは、２万m2以上の広大な敷地がありますので、その考えの１つに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"本件については、この半年くらいで話が持ち上がって、すごい進展してきたという気がいたします。ある可能性もあるかなと思ったので、その点で民間の動きがわかるようであれば教えていただければと思います。","respondent":"柏原行財政改革担当課長","answer":"今回の件、品川寮については地元自治体には照会していますということで、ホームページ等には出ているのですけれども、それについて民間から問い合わせ、社会福祉法人から国への直接の問い合わせであるとか、区に対する問い合わせというのは。","voiceIndex":40,"id":"exchange-018"},{"speaker":"浅野委員","kind":"質問・要望","question":"気になることはたくさんあるのですけれども、その中でも、面積の問題ですとか、その後の用途の問題ですとか、区でもしっかりこれからも考えていかれるとは思うのですが、今までの話ですと、区が購入しないとか、定期借地もやらないとなった場合には、区を離れて民間に対して、定期借地ですとか、購入とか、そのような流れに自動的に、今回においてもなっているのかどうか、教えていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"地元自治体の品川区が、こういった形で全てにおいて取得、貸借を希望しないということであれば、民間のほうに大きく広げる。それが売却のなのか、定期借地なのか、わかりませんけれども、広く民間に門戸を開けて募集する形になると聞いています。","voiceIndex":42,"id":"exchange-019"},{"speaker":"浅野委員","kind":"質問・要望","question":"民間も、定期借地か購入か、まだはっきりしていないというところですかね。今回は１カ月待ってもらえればいいのですけれども、時間切れのようなことになってしまうと、せっかくのチャンスを逃してしまうことになりますので、今回も含めて、今後こういう形で提供される可能性があるものについては、早急に並行して検討していただきたいと思いますが、いかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"ほかの物件ですけれども、委員がおっしゃるとおりでございまして、こういった形でいずれは出てくるというのが見えてありますので、行政需要等を含めながら、並行しながら、どういったものに使えるかというところで検討を進めていきたいと思ってあります。","voiceIndex":44,"id":"exchange-020"},{"speaker":"あべ委員","kind":"質問・要望","question":"この情報というのは、当然品川区だけではなくて、東京都にも、同じように提示されていると思うのですけれども、東京都の動きはどのように把握されているのでしょうか。あるいは南品川の１番のほうだって、もしかすると都が入手して、都の施設ができて、それが近隣住民に役立ってくれるということであれば、それはそれでありがたい話ですし、そういった都の動きを教えていただきたい。","respondent":"柏原行財政改革担当課長","answer":"東京都の動きです。国のほうからしますと、委員のおっしゃったとおり、東京都にも情報提供をしているとは聞いてあります。東京都にも確認をとっているのですが、正直申しまして、具体的な明確な回答をいただけない状況です。","voiceIndex":46,"id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"都と一緒に、国に何かを言っていくという環境にはないということですか。都は、余り自分の動きについては、周りに出していないということですか。","respondent":"柏原行財政改革担当課長","answer":"特に小山台につきましては、品川区におきましても、広域避難所である林試の森公園がありますので、これにつきましては東京都と歩調を合わせながらやっていくほうがよろしいのではないかという考えもございまして、東京都と連携をとりながら。","voiceIndex":48,"id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうは、南品川、１カ月ということでありますけれども、それ以外のところで、ほかの土地についてはどうなっているのか、まず、その辺をお聞かせいただきたいと思いますけれども。","respondent":"柏原行財政改革担当課長","answer":"小山台住宅、上大崎寮は、ご覧いただいておわかりのとおり、まだ住んでいる方がいらっしゃいますので、これについても、いつ来るかというのは、まだ財務事務所から聞いてございませんが、国は平成２８年度までに処分を行いたいと言っておりますので。","voiceIndex":50,"id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"というのは、国の資産の場合には、よくある一番多いケースとしては、郵政との絡みであったり、ある程度の大きさになってくると、それからあとは地検が一時期長期で借りていて、それを財務省に戻したというケースもあるので、交渉相手はどちらなのかというのを教えていただければと思います。","respondent":"柏原行財政改革担当課長","answer":"具体的なこういうやりとりをする相手先は、財務省の東京財務事務所というところが一括して交渉役になりまして、こちらの資料にあります省庁名は、現段階でこの寮を所管している、もしくは当時所管していたところでございまして、実際に処分、動きが決まったときには。","voiceIndex":52,"id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"使い道というのは、当然あるでしょうから、全体的な価値、価値というのは金額だけではないと思いますので、その辺も特に民間の仕事ではありませんので、さっきから、普通なら不動産というのは値段から出てくる問題なのですけれども、国も出していない、こちらも出していないということですので、それは逆に言うと、自治体として花房山の価値を認識していただきたい。","respondent":"柏原行財政改革担当課長","answer":"そういったところを今、順次調べているところですので、そういったところを総合的に判断しながら決めていくものであろうと考えています。","voiceIndex":54,"id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、当然、先ほど企画部長の答弁にもありましたように、金額でいけば、なかなか民間には、時間、スピードにしても、金額にしても、自治体というのは民間ディベロッパーには対抗しづらい部分もあるので、ただ、逆に先に国から自治体として話をいただいているわけですので、その辺をしっかり、かえってプラスに働いていただければいいと考えていますので、これは要望でお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"品川第二寮のほうですが、急に寮が廃止になって、以前からうわさが出ていた中の、方向性出てきた部分があると思うのですけれども、品川税務署が１階に移転するだろうという状況がありましたよね。これは、もう正式に廃止になっている話なのか、そこら辺の状況をつかんでいるでしょうか。","respondent":"桑村企画部長","answer":"それと、正直言って、何か近所の方のご協力を得て１０メートルにできないかという努力をされたようですけれども、結局できないということになったので、この話自体はなくなったと区のほうでは判断しています。","voiceIndex":57,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ただ、あの隣が青色申告会とか、法人、税理士会とか、あそこは逆に言うと今、既存不適格的になっている部分です。そういうのに対して、区として、国と一体で考えてあげれば、あそこの建物ももう大分たっているし、区との協力団体でもある中で、そういう折衝というのは行われたものなのでしょうか。","respondent":"桑村企画部長","answer":"詳しいあれはないのですけれども、十分折衝させていただいて、何とかならないかというお話をさせていただいたのですけれども、どうしても了承を得られなかったということなので、税務署としては、これ以上やっても難しいということで諦めたという経過があります。","voiceIndex":59,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ありがとうございました。わかりました。それと、この品川寮に関してなのですが、今まで皆さんの各意見が出ている中で、自民党として今度の委員会に先立って資料をいただきたいとお願いしたのも、ある程度会派の中で方向性を出したいということで検討しました。その時点では、いろいろご説明が変わってきた状況も踏まえながらも、やはり効率的な土地ではないのではないかという１つの考え方が出ています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"時価が高いということで、それではとてもということもあるのですけれども、その辺の違いというのはどうなっているのかを、今わかっている範囲でいいですから、教えていただきたいというのが１つと、さっきも言った６月７日付の東京新聞、私はこの表現にこだわるのですけれども、該当する用地があって、なおかつ５０人以上の待機児童を抱えている自治体に６月末までに情報提供をすると書いてあるんです。","respondent":"柏原行財政改革担当課長","answer":"現段階でこの品川寮が、処分が決定していますので、これについて早々に回答をいただきたいということと、それから先ほど口頭で申し上げましたけれども、こういったスキームが新たに出ているので、こういったところも踏まえて検討していただければという情報提供をいただいたです。","voiceIndex":62,"id":"exchange-030"},{"speaker":"南委員","kind":"確認","question":"そうすると、私は国から照会が来ているところが、第一の品川寮だけなのかと受けとめていたので、非常にそこにこだわって保育園という主張をしたのですけれども、もちろんどこでも保育園をつくっていただければ一番いいとは思っております。この５物件に対して、保育園の待機児解消の対象物件だと捉えていいということですか。もう１回、その点を確認したいと思います。","respondent":"柏原行財政改革担当課長","answer":"待機児童対策で使える物件ということで、こちらの４地区５物件が対象になっているということで、情報提供いただいています。","voiceIndex":64,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"キャパが受け入れられれば、複合的な施設をつくっていくということは全然やぶさかではないし、検討する価値はあると思うので、そのこともあわせて主張したいと考えていますけれども、ぜひ大所高所から検討していただいて、５物件の中で、できるだけ待機児解消、国の方針を受けとめて、やっていただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"自民党の考え方を。今のご意見でもあったとおり、財政面を考えたときに、全然金額を聞かなかったときに、効率を考えたときにどうかというのが、一番大きな問題でもあります。行政側の回答もありますし、各会派の意見の話にもありましたけれども、今、南委員はほかに移ったから、あの辺はないという話もありましたけれども、地域の中で要望の数がどれぐらいになるかがつかみ切れていない。そういう考え方です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"今回これだけの物件が出てきて、品川区の区民の要望との関係でも、本当に待機児を抱えている。しかも、これでは５０人以上の待機児を抱えている自治体というところで、特に出てきている情報提供なので、そこは重く受けとめるべきだと思うのです。その辺を含めて、ぜひ、そういう角度からもご検討をしていただければいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-034"},{"speaker":"井上副委員長","kind":"質問","question":"品川第二寮のところなのですが、視察をしたときにコンクリートのスペースありましたよね。品川寮から第二寮を見たときのあそこが、同じ敷地の枠のような説明をされたかと思うのですけれども、この図だと四角いスペースしかないのですが、それはどのような、もし、そこが同じスペースだったら、ここがこういうふうにひしゃく形に伸びるわけです。先ほど現場でしたので。教えていただければと思います。","respondent":"柏原行財政改革担当課長","answer":"あとは下側に南品川四丁目アパートとありますけれども、こちら側に細い道ですけれども、路地が伸びているという状況で、路地が西側と南側に小さい土地が出てきていて、そこも国の敷地であるです。失礼いたしました。","voiceIndex":71,"id":"exchange-035"},{"speaker":"井上副委員長","kind":"質問","question":"そうすると、あそこのコンクリートの出たところというのも、思いのほか広かったような。いろいろと何か用途とか、立体化すればあるのかなと思ったのですが、そこも含めて、全体の敷地、建物には直接関係ないのかもしれないのですが、どのくらいになるかわかりますか。今、ここに書かれているのが２,３７５.８９m2です。この中には含まれていないのですよね。含まれているのですか。","respondent":"柏原行財政改革担当課長","answer":"路地状の敷地も含めて、この敷地面積になっております。","voiceIndex":73,"id":"exchange-036"},{"speaker":"井上副委員長","kind":"質問","question":"前に聞いたときは、建物が建てにくい場所なんだという前提があったのですけれども、工夫をすれば、保育園の施設とか、もう少し規模が小さければということで理解をしていいのでしょうか。","respondent":"柏原行財政改革担当課長","answer":"例えば、事務所的なものであるとか、そういったものであれば建つようなのですが、条例をそのまま読む範囲では、そういった建物は、条例そのものにできないと書いてありますので、そういったところも見ながら、どういったものができるのか、できないのかというのを今。","voiceIndex":75,"id":"exchange-037"}]},{"id":"topic-03","title":"契約のあり方に関すること","agenda":"契約のあり方に関すること","exchanges":[{"speaker":"向委員","kind":"質問・要望","question":"よくわからないので教えていただきたいのですけれども、一番最初のページに戻って、３つ契約方法の種類があるということで、品川区としてせり売りをしていないということで、これはわからないので教えていただきたいのですけれども、品川区としてこれをしていない理由と、今後もこれはしない方向で変わらないのでしょうか。お考えをお伺いしたいのでお願いします。","respondent":"平澤経理課長","answer":"そういった案件がなかったです。物を売る、または土地を売る場合にこういったものを使うわけですが、昨年度実は１件、一般競争入札で土地を売りました。こういったところで、本来の原則である一般競争入札で土地を売ったです。","voiceIndex":81,"id":"exchange-038"},{"speaker":"向委員","kind":"質問","question":"そういう案件はなかったということで、それに伴い、区としてデメリットが大きかったわけではないということですか。","respondent":"平澤経理課長","answer":"さまざまな収入の確保という面では、手法は当然あってしかるべきだと思いますので、その時代に即した形で今後もいろいろな形の検討をしていくということになると思います。その中の１つの手法として、せり売りも当然考えられるです。","voiceIndex":83,"id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"改めて、こうやって一覧というか、一つにまとめていただいて、契約の内容、種類を含めて、非常に勉強になったのですけれども、とりわけ３ページに出ている、工事代金債権信託制度とか、工事前払金および中間前払制度は、平成２３年度、平成２２年度で比較的新しいのですけれども、私の認識では、不況がずっと長引き、工事業者の倒産だとかを防ぎ。","respondent":"平澤経理課長","answer":"もう一つの公共工事代金債権信託制度につきましては、これは資金繰りという意味合いが強いと思います。工事完成前に全額を債権化して、証券化して、その部分を担保に銀行から借り受けるというものです。","voiceIndex":85,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"その周知等々について、改めてどういうふうになっているのかを教えていただきたいのと、電子入札だったか、つまり、聞きたいのは、区内登録業者にできるだけ仕事を発注していけるような仕組みになってほしいと思っているのですけれども、先ほどの説明では、東京電子自治体共同運営サービスの登録事業者と区内事業者の数が出ているのですけれども、そのほかの契約については。","respondent":"平澤経理課長","answer":"そういうところによりまして、例えば、約款の中に全て法令遵守のところを入れさせていただいている。ダンピング防止ということでは、先ほどご説明させていただきましたが、今年６月から最低制限価格制度の試行を再開させていただいたというところもあります。","voiceIndex":87,"id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"補正予算を組まれて、代金は業者に払いました。しかしその先の本来の趣旨であるところに全うされていかなければ、それこそ税金の無駄遣いになってしまうわけですから、やはりきちんと見届けていく姿勢が、私は、とりわけ今の状況の中では必要なのではないかと思うのです。時間の関係もありますので、それを最後に伺って終わりにしたいと思います。","respondent":"平澤経理課長","answer":"したがいまして、これが賃金の確保ということで、重要なものであるということは、国のほうの考え方を準用したところで、私どもといたしましても、申請書にこの背景、趣旨をきちんと執行する形で使うという担保をとった申請書をいただいて、契約変更の協議に応じているというのが。","voiceIndex":89,"id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"大変だと思うのです。ですから、その２省単価を大幅に値上げした、上げろという指導をしたことが、本当にどこまで実際に手元に届くかというところは、やっぱり一定の申請書の取り交わしだけではなくて、きちんと担保できるようなシステムが、まさに今この時期に必要なのではないかと私は思っているのです。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-043"},{"speaker":"あべ委員","kind":"確認","question":"幾つかお伺いします。１点目、先ほどせり売りの話が出ましたけれども、ちょっと前に自治体の差し押さえ品などのインターネット競売がよく話題になっていたりするのですけれども、品川区はそういった検討を一時したというお話を聞いたような気もするのですけれども、その関連では、結局、品川区としては特にやっていないということでよろしいでしょうか。","respondent":"平澤経理課長","answer":"このやり方についてですけれども、ご質問があった方に関しましては、私を含め、契約係の職員が１つ１つ個別に、ご指導と言っては大変失礼なのですけれども、お話をして、ご説明をしています。","voiceIndex":92,"id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"５,０００m2の国の附則については、また教えてください。できればご検討いただきたいのですが、それについてご見解をお願いします。最後、８番の表が２つとも経理課契約に限るとあります。確認なのですけれども、２ページの表には経理課契約は、上限で言えば１,０００万円未満。この表の中では１,０００万円以上の契約は入っていないということなのでしょうか。以上、確認させてください。お願いします。","respondent":"平澤経理課長","answer":"そういった場合には、こういうことでとお話を申し上げているです。それからもう１点、小規模なものといいますか、こちらの契約権限の委任でお示ししたところですが、予定価格が低いものにつきましては、各主管課に契約権限があるということになります。","voiceIndex":94,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"委員長にお伺いしたいのですけれども、今後の委員会の進め方というか、先ほど、一番初めにあって、その後どういう形で調査するかということをおっしゃっていただいたのですけれども、それによって今日の質問の仕方も変わってくるので、多分、これを１つ１つやっていたら、今日終わらないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"今日は１点だけ伺いたいのですけれども、昨年末の総選挙で政権交代しまして、自民党と公明党で連立政権ということで、そのときは自民党では国土の強靭化計画ということで、私ども公明党では防災・減災ニューディールということで、共通していることは、社会インフラの老朽化対策というところを頂点に取り上げまして、ご信託をいただいたと思っているのですけれども、今。","respondent":"中山総務部長","answer":"利益という話がありましたけれども、これは区民の方の利益を確保していく。こういうことと、片や、地元の区内企業をきちんと育成し、また地元に精通した企業を育てていく。こういう面で、さまざまなことのバランスをとりながらやっていくということかと認識しています。","voiceIndex":102,"id":"exchange-047"},{"speaker":"浅野委員","kind":"提案","question":"１ページ、一番下の随意契約の中で、競争見積合わせとプロポーザルとあるのですけれども、「区が指名する複数の業者から」、また、下は「複数から」となっているのですけれども、複数というと多分２以上だと思うのですけれども、複数にならないケースというのはあるのかということと、あとは複数というと大体恒例ですと何者くらいを、区が指名したりとか。","respondent":"平澤経理課長","answer":"例えば、１,０００万円未満の場合は５者以上とか、これは委託についても準用しています。２点目、委託における単価契約、総価契約のお話だと認識しました。こちらにつきましては、いわゆる単価契約の部分もあることはあるというふうに、変な言い方なのですけれども。","voiceIndex":104,"id":"exchange-048"},{"speaker":"浅野委員","kind":"意見","question":"大体わかったというか、認識したのですけれども、最後のところで複数年次は２年目以降は随意契約と言われたのが、ちょっと認識が違っていたら申しわけないのですけれども、そうするとその言い方からすると、この場合は単価で決めているのか。単価の出し方なのですけれども。","respondent":"平澤経理課長","answer":"決めた場合、その年の１年間の契約になります。成績が優秀であれば、次の年についても随意契約でやっていくです。そういった大きな委託といいますか、随意契約がある関係で、金額的に多くなっているです。説明が悪くて申しわけございません。","voiceIndex":106,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問","question":"中身には入っていかないですけれども、３ページ目で総合評価方式による契約の中で、平成２４年度の実績、工事（試行）で１件３,９２７万円とあるのは、どのようなものが試行されたのかというのが１点。２３件全部だけではなくていいです。概略だけ教えてください。","respondent":"平澤経理課長","answer":"プロポーザルです。プロポーザルの主なものでまいりますと、平成２４年度につきましては、例えば品川区の高層マンションの防災対策の推進に関する検討、それから品川区の長期基本計画の改訂の支援業務といったところ。調査が多いです。","voiceIndex":110,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"これが手元に来るのは２日前ですから、なかなか契約がとか、そういうことについて、私はですよ、ほかの方はわからないけれども、私は十分準備ができなくて困るので、ある程度の計画がわかれば非常にありがたいので、次回でいいですから示していただきたいと思います。","respondent":"山元委員長","answer":"今のご意見、正副でしっかりと検討させていただきたいと思います。そのほかに何かご意見はないですか。以上をもちまして、本日の予定は全て終了いたしました。","voiceIndex":115,"id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5948#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":47673,"voices":116}}]);
